cases.old_string:
@functools.cache
def _model():
    """Load the model once per process. Repeat calls to detect_pii reuse it."""
    return load(MODEL)

def detect_pii(source: str | os.PathLike) -> str:
    """Return "YES" if the text contains PII about a real person, else "NO".

    Accepts raw text or a path to a file holding the text.
    Raises ValueError if the model answers with anything else.
    """
    model, tokenizer = _model()
    prompt = tokenizer.apply_chat_template(
        [{"role": "system", "content": SYSTEM}, {"role": "user", "content": resolve_text(source)}],
        add_generation_prompt=True,
        tokenize=False,
    )
    reply = "".join(
        response.text
        for response in stream_generate(model, tokenizer, prompt, max_tokens=8, sampler=make_sampler(temp=0.0))
    )
    verdict = re.search(r"\b(YES|NO)\b", reply.upper())
    if not verdict:
        raise ValueError(f"model did not answer YES or NO: {reply!r}")
    return verdict.group(1)


if __name__ == "__main__":
    argument = " ".join(sys.argv[1:]).strip()
    print(detect_pii(argument or sys.stdin.read()))

it("keeps a message Pi has finished but not yet written", async () => {
  // Pi awaits an extension hook between the two. In that window the message
  // is only in the agent's array, and a reader attaching there was handed a
  // transcript without it.
  const { supervisor, entries, messages, entryFor, session } =
    await openWithTranscript();
  const asked = { role: "user", content: "q", timestamp: 1 };
  const finished = { role: "assistant", content: [], timestamp: 2 };
  entries.push(entryFor("e-user", asked));
  messages.push(asked, finished);
  session.state = { pendingToolCalls: new Set<string>() };

  const snapshot = await supervisor.getThread("t1");

  expect(snapshot.messages).toEqual([asked, finished]);
  expect(snapshot.entryIds).toEqual(["e-user", null]);
  // Nothing is streaming, so there is no pointer to restore.
  expect(snapshot.streamingMessageIndex).toBeUndefined();
});

