it("carries a finished message once its end has been announced", async () => {
  // Pi writes the entry immediately AFTER announcing the end, so between the
  // two the message is announced and unwritten. It rides the snapshot from
  // its announcement, and leaves the tail again once the session file has
  // it — one message, one copy, whichever side of the write a reader lands.
  const { supervisor, entries, messages, entryFor, session, emit } =
    await openWithTranscript();
  const asked = { role: "user", content: "q", timestamp: 1 };
  const finished = { role: "assistant", content: [], timestamp: 2 };
  entries.push(entryFor("e-user", asked));
  messages.push(asked, finished);
  session.state = { pendingToolCalls: new Set<string>() };
  emit({ type: "message_end", message: finished });

  const announced = await supervisor.getThread("t1");
  expect(announced.messages).toEqual([asked, finished]);
  expect(announced.entryIds).toEqual(["e-user", null]);
  // Nothing is streaming, so there is no pointer to restore.
  expect(announced.streamingMessageIndex).toBeUndefined();

  entries.push(entryFor("e-answer", finished));
  const written = await supervisor.getThread("t1");
  expect(written.messages).toEqual([asked, finished]);
  expect(written.entryIds).toEqual(["e-user", "e-answer"]);
});

