it("keeps a message Pi has finished but not announced out of both transcripts", async () => {
  // The other end of the window round 22 closed. Pi puts the FINISHED
  // assistant object into its array BEFORE it awaits the `message_end` hook,
  // and writes the entry only after — so inside that hook the message is in
  // `session.messages`, absent from the session file, and announced to
  // nobody. Taking it from the array while also carrying the last announced
  // partial put the same answer in a snapshot twice, and the held
  // announcement then replaced the partial and left the extra copy for good.
  const { supervisor, session, entries, messages, entryFor, emit } =
    await openWithTranscript();
  const asked = { role: "user", content: "q", timestamp: 1 };
  messages.push(asked);
  entries.push(entryFor("e-asked", asked));

  const connected: PiClientEvent[] = [];
  supervisor.subscribe("t1", (event) => connected.push(event));
  await vi.waitFor(() => expect(connected).not.toHaveLength(0));

  emit({ type: "agent_start" });
  session.isStreaming = true;
  const partial = {
    role: "assistant",
    content: [{ type: "text", text: "half" }],
    timestamp: 2,
  };
  emit({ type: "message_start", message: partial });
  emit({ type: "message_update", message: partial });

  // Pi finalizes the answer into its array and holds the announcement. The
  // two objects carry the same role and timestamp, which is how a reader
  // recognises the finished message as the one it was watching.
  const answered = {
    role: "assistant",
    content: [{ type: "text", text: "half an answer" }],
    stopReason: "stop",
    timestamp: 2,
  };
  messages.push(answered);

  const reduce = (events: PiClientEvent[]) =>
    events.reduce(
      (state, event) => reducePiThreadState(state, event),
      createPiThreadState("t1"),
    );
  const fresh: PiClientEvent[] = [];
  supervisor.subscribe("t1", (event) => fresh.push(event));
  await vi.waitFor(() => expect(fresh).not.toHaveLength(0));
  expect(reduce(fresh).messages).toEqual([asked, partial]);
  expect(reduce(fresh).messages).toEqual(reduce(connected).messages);

  // The hook lets go: Pi announces the end, then writes the entry.
  emit({ type: "message_end", message: answered });
  entries.push(entryFor("e-answer", answered));

  expect(reduce(fresh).messages).toEqual([asked, answered]);
  expect(reduce(connected).messages).toEqual([asked, answered]);
  expect((await supervisor.getThread("t1")).messages).toEqual([
    asked,
    answered,
  ]);
});

