cases.new_string:
/** The roles Pi persists as a `message` entry, holding on to the very object it
 * emitted. Every other role in a transcript is synthesized from some other
 * entry when the transcript is built, and Pi builds a fresh object each time —
 * so only these three can be recognised again once they are written, and only
 * these three may wait in `announcedTail` for that to happen. */
const WRITTEN_AS_MESSAGE_ENTRY: ReadonlySet<string> = new Set([
  "user",
  "assistant",
  "toolResult",
]);

cases.old_string:
