cases.old_string:
/**
 * The thread's transcript and the entry id of every message in it.
 *
 * The canonical transcript is what Pi PERSISTED, plus the message it is
 * streaming right now. Pi's in-memory array is not canonical: it mutates
 * without events — a failed attempt is dropped on retry, an overflow error is
 * dropped after the compaction that recovers from it — so a reader following
 * it would show something no reload can reproduce. Pi's own cold path
 * restores those attempts, so matching the live array would mean
 * reimplementing Pi's filtering in every cold reader.
 *
 * The persisted view is append-only, which is why no removal events are
 * needed, and every entry carries an id, so ids never go missing. A failed
 * attempt renders as what it is: an assistant message whose stop reason is an
 * error. Warm, reconnected and cold readers all build from this one shape.
 */
private transcriptOf(
  sessionManager: SessionManager,
  tail: readonly unknown[] = [],
): PiTranscript {
  const messages: unknown[] = [];
  const entryIds: (string | null)[] = [];
  for (const entry of sessionManager.buildContextEntries()) {
    for (const message of sessionEntryToContextMessages(entry)) {
      messages.push(message);
      entryIds.push(entry.id);
    }
  }
  for (const message of tail) {
    messages.push(message);
    entryIds.push(null);
  }
  return { messages, entryIds };
}

/**
 * The live transcript: what Pi has written, then what it has not written yet.
 *
 * Pi writes a message's entry after the message ends, and it awaits an
 * extension hook in between — a window in which the finished message lives
 * only in the agent's array. A reader that attached there used to be handed a
 * transcript missing a message it had watched arrive, with no way to get it
 * back. So the tail is every trailing message the session file does not have,
 * plus the one being streamed, which the agent keeps to one side until it
 * completes.
 *
 * Only the trailing run is taken from the agent's array. The array is not the
 * transcript: it also DROPS messages Pi persisted, which is what makes the
 * written session canonical in the first place.
 *
 * The streaming message is the one the host ANNOUNCED, never Pi's live
 * `state.streamingMessage`. Pi assigns that a hook before it emits
 * `message_start`, so reading it handed an attaching reader a message a
 * connected one had not been told about — two transcripts of different
 * lengths, and with them two sets of positional ids for the same answer. A
 * reader that attaches inside the hook converges when the held
 * `message_start` arrives, on a later seq than its snapshot.
 */
private liveTranscriptOf(record: ThreadRecord): PiTranscript {
  const written = this.transcriptOf(record.session.sessionManager);
  const known = new Set(written.messages);
  const live = record.session.messages as readonly { role?: string }[];
  let firstUnwritten = live.length;
  while (firstUnwritten > 0) {
    const message = live[firstUnwritten - 1]!;
    // Only the roles Pi writes as message entries can be ahead of the
    // session. The others are BUILT from entries, and Pi builds a fresh
    // object every time, so identity says "unwritten" about a message that by
    // definition already is — which is how they came to be duplicated.
    if (!WRITTEN_AS_MESSAGE_ENTRY.has(message.role ?? "")) break;
    if (known.has(message)) break;
    firstUnwritten -= 1;
  }
  const tail = [...live.slice(firstUnwritten)];

  const streaming = record.announcedStreamingMessage;
  const streamingIndex =
    streaming && !known.has(streaming) && !tail.includes(streaming)
      ? written.messages.length + tail.push(streaming) - 1
      : undefined;

  const transcript = this.transcriptOf(record.session.sessionManager, tail);
  return streamingIndex === undefined
    ? transcript
    : { ...transcript, streamingIndex };
}

cases.new_string:
/**
 * The thread's transcript and the entry id of every message in it.
 *
 * The canonical transcript is what Pi PERSISTED. Pi's in-memory array is not
 * canonical: it mutates without events — a failed attempt is dropped on
 * retry, an overflow error is dropped after the compaction that recovers from
 * it — so a reader following it would show something no reload can reproduce.
 * Pi's own cold path restores those attempts, so matching the live array
 * would mean reimplementing Pi's filtering in every cold reader.
 *
 * The persisted view is append-only, which is why no removal events are
 * needed, and every entry carries an id, so ids never go missing. A failed
 * attempt renders as what it is: an assistant message whose stop reason is an
 * error. Warm, reconnected and cold readers all build from this one shape.
 */
private transcriptOf(sessionManager: SessionManager): PiTranscript {
  const messages: unknown[] = [];
  const entryIds: (string | null)[] = [];
  for (const entry of sessionManager.buildContextEntries()) {
    for (const message of sessionEntryToContextMessages(entry)) {
      messages.push(message);
      entryIds.push(entry.id);
    }
  }
  return { messages, entryIds };
}

/**
 * Take an announced message into the tail, if the session file could be
 * behind it.
 *
 * Pi persists a message entry from inside its own `message_end` handling, one
 * statement after it announces the end, so the tail holds it for that gap and
 * `liveTranscriptOf` drops it again as soon as the file has it. The gap is
 * narrow, and the point is not its width: it is that ONE rule decides what a
 * snapshot carries, rather than the transcript resting on Pi's statement
 * order staying as it is.
 */
private holdAnnouncedMessage(record: ThreadRecord, message: unknown): void {
  const role = (message as { role?: string }).role ?? "";
  if (WRITTEN_AS_MESSAGE_ENTRY.has(role)) record.announcedTail.push(message);
}

/**
 * The live transcript: what Pi has written, then what the host has announced
 * and Pi has not written yet.
 *
 * Nothing here reads Pi's live state, and that is the whole rule. Pi runs
 * ahead of its own announcements at both ends of a message — it assigns
 * `state.streamingMessage` a hook before `message_start`, and it puts the
 * finished object into `session.messages` a hook before `message_end` — so
 * either one hands an attaching reader a message the connected reader has
 * never been told about. That is two transcripts of different lengths, two
 * sets of positional ids for the same answer, and, once the held
 * announcement lands, the same answer twice in the reader that attached.
 *
 * A reader that attaches inside a hook converges when the held announcement
 * arrives, on a later seq than its snapshot.
 */
private liveTranscriptOf(record: ThreadRecord): PiTranscript {
  const transcript = this.transcriptOf(record.session.sessionManager);
  const persisted = new Set(transcript.messages);
  record.announcedTail = record.announcedTail.filter(
    (message) => !persisted.has(message),
  );
  for (const message of record.announcedTail) {
    transcript.messages.push(message);
    transcript.entryIds.push(null);
  }
  const streaming = record.announcedStreamingMessage;
  if (streaming === undefined) return transcript;
  transcript.messages.push(streaming);
  transcript.entryIds.push(null);
  return { ...transcript, streamingIndex: transcript.messages.length - 1 };
}

it("leaves a failed run failed when the stop ended only maintenance", async () => {
  // A manual compaction is work the host can see, so a stop reaches it and
  // honestly reports `true`. It belongs to no run, though, and the failure
  // on this thread was recorded by a run that settled long before — so
  // clearing the outcome there took a genuinely failed thread to idle on
  // the strength of an unrelated Stop. A run's outcome is the run's, and
  // only a stop that ended THAT run's work may touch it.
  const t = await openForSends();
  t.emit({ type: "agent_start" });
  t.session.isStreaming = true;
  t.emit({ type: "message_start" });
  t.session.state.errorMessage = "503: mock upstream overloaded";
  t.session.isStreaming = false;
  t.emit({ type: "agent_end", willRetry: false });
  t.emit({ type: "agent_settled" });
  expect((await t.supervisor.getThread("t1")).metadata.status).toBe(
    "failed",
  );

  // Later, with nothing running, the user compacts the conversation and
  // then presses Stop.
  t.emit({ type: "compaction_start", reason: "manual" });
  t.session.isCompacting = true;
  const stopping = t.supervisor.cancelRun("t1");
  await t.tick();
  t.session.isCompacting = false;
  t.emit({ type: "compaction_end", aborted: false, willRetry: false });

  expect(await stopping).toEqual({ stopped: true });
  const after = await t.supervisor.getThread("t1");
  expect(after.metadata.status).toBe("failed");
  expect(after.lastError).toBe("503: mock upstream overloaded");
});

