it("answers a bare settlement the same for a mid-run attacher", () => {
  // Deciding for itself means applying an ORDER the events carry: a message
  // announced after the settling run's own attempt ended was written by a
  // newer run, so the group stays where it is. A reader that followed the
  // stream saw that order. One that attached mid-run did not, and a snapshot
  // that said nothing about it left the two answering the same settlement
  // differently — the connected reader keeping the group, the fresh one
  // completing an answer still being written.
  const answer = assistant([{ type: "text", text: "…" }]);
  const connected = apply(
    createPiThreadState("t1"),
    ev({ type: "agent_start" }),
    ev({ type: "message_start", message: answer }),
    ev({ type: "agent_end" }),
    // An extension starts a run inside the first one's settled hook, and it
    // announces its own message before that hook lets go.
    ev({ type: "agent_start" }),
    ev({ type: "message_start", message: answer }),
  );
  const attaching = apply(
    createPiThreadState("t1"),
    ev({
      type: "snapshot",
      snapshot: {
        metadata: { id: "t1", status: "running", runActive: true },
        messages: [answer, answer],
        hasMessageSinceAttemptEnd: true,
      },
    }),
  );

  const settled = ev({ type: "agent_settled" });
  expect(apply(connected, settled).runActive).toBe(true);
  expect(apply(attaching, settled).runActive).toBe(
    apply(connected, settled).runActive,
  );
});

