it("puts the order behind the group on the snapshot", async () => {
  // A settlement's rule reads an ORDER, and a snapshot is a state — so a
  // reader that attaches mid-run cannot work the order out for itself. This
  // host resolves its own settlements and never needs it, but the two halves
  // of that fact are separately optional on the wire, and a host that
  // adopted only the snapshot half had a mid-run attacher answering the next
  // bare settlement differently from the reader beside it.
  const { supervisor, session, entries, entryFor, emit } =
    await openWithTranscript();
  const asked = { role: "user", content: "q", timestamp: 1 };
  entries.push(entryFor("e-asked", asked));

  emit({ type: "agent_start" });
  session.isStreaming = true;
  emit({
    type: "message_start",
    message: { role: "assistant", content: [], timestamp: 2 },
  });
  expect(
    (await supervisor.getThread("t1")).hasMessageSinceAttemptEnd,
  ).toBe(true);

  // The attempt ends, and until a newer one writes something the order is
  // back to "nothing since" — which is what lets a settlement hand the
  // group back.
  emit({ type: "agent_end", willRetry: false });
  expect(
    (await supervisor.getThread("t1")).hasMessageSinceAttemptEnd,
  ).toBeUndefined();
});

