it("stops a branch summarization and waits for it to let go", async () => {
  // Pi counts a branch summarization as compacting, so the host reports
  // the thread busy and holds the deploy gate shut for it. Nothing else
  // about it was true. `session.abort()` waits for an agent RUN and this
  // is not one, `abortCompaction()` is a different controller, and Pi
  // announces neither end of `navigateTree` — it runs entirely through its
  // extension events — so the boundary wait skipped it as well. Stop
  // answered `{stopped:true}` over a live model call that was still about
  // to rewrite the branch.
  const t = await openForSends();
  t.session.isCompacting = true;

  let answered = false;
  const stopping = t.supervisor.cancelRun("t1").then((report) => {
    answered = true;
    return report;
  });
  await t.tick();
  expect(t.session.abortBranchSummary).toHaveBeenCalled();
  expect(answered).toBe(false);

  // The summarization request dies on the signal and `navigateTree`
  // unwinds, dropping the controller behind the flag.
  t.session.isCompacting = false;

  expect(await stopping).toEqual({ stopped: true });
  expect(t.supervisor.getRunningThreadCount()).toBe(0);
});

