cases.old_string:
/**
 * Wait for the compaction to end.
 *
 * Keyed on the event stream and not on `session.isCompacting`: every
 * `compaction_start` the host has been told about is followed by a
 * `compaction_end`, while Pi also counts a branch summarization as
 * compacting and announces neither end of it.
 */
private awaitCompactionEnd(record: ThreadRecord): Promise<void> {
  return new Promise<void>((resolve) => {
    record.compactionWaiters.add(resolve);
  });
}

cases.new_string:
/**
 * Wait for the compaction to end.
 *
 * Keyed on the event stream and not on `session.isCompacting`: every
 * `compaction_start` the host has been told about is followed by a
 * `compaction_end`, and the two agree on which compaction is meant.
 */
private awaitCompactionEnd(record: ThreadRecord): Promise<void> {
  return new Promise<void>((resolve) => {
    record.compactionWaiters.add(resolve);
  });
}

/**
 * Wait for a branch summarization to let go.
 *
 * Pi runs `navigateTree` entirely through its EXTENSION events and emits no
 * session event at either end, so there is no boundary to key on the way
 * `awaitCompactionEnd` does — Pi's own flag is the only signal there is, and
 * it counts a branch summarization as compacting.
 *
 * Reading live state is exactly what the transcript rules forbid, and this is
 * not that: it decides when ONE caller's `cancelRun` may answer, nothing is
 * derived from it, and nothing about it crosses the wire. No two readers can
 * be told different things by a value no reader is ever told.
 */
private async awaitBranchSummaryEnd(record: ThreadRecord): Promise<void> {
  while (record.session.isCompacting) {
    await new Promise((resolve) =>
      setTimeout(resolve, BRANCH_SUMMARY_POLL_MS),
    );
  }
}

cases.old_string:
