// How far each geometry actually reaches along its own X and Z before scaling.
// A boulder's warp and a slab's flared base both push past the nominal unit
// radius, so a collider sized from width and depth alone would sit inside the
// rock you can see. Measured once per geometry, then scaled per part.
function measureGeometryExtents(geometries) {
  return Object.fromEntries(Object.entries(geometries).map(([name, geometry]) => {
    const positions = geometry.attributes.position;
    let maximumX = 0;
    let maximumZ = 0;
    for (let index = 0; index < positions.count; index++) {
      maximumX = Math.max(maximumX, Math.abs(positions.getX(index)));
      maximumZ = Math.max(maximumZ, Math.abs(positions.getZ(index)));
    }
    return [name, { x: maximumX, z: maximumZ }];
  }));
}

