// --- The hitbox ---
// It is measured, not authored. Every bone that owns skinned vertices gets the
// box those vertices fill, taken once in the bind pose. At runtime each box
// rides its own bone, so the feet swing with the walk and the belly stays where
// the belly is. Nothing needs re-tuning when the model, the tier, or
// DINOSAUR_GAME_SCALE changes — which is the point, because at this scale the
// truck fits under the belly and between the legs, and that clearance has to
// stay honest.

function dominantSkinSlot(skinWeight, index) {
  let bestSlot = 0;
  let bestWeight = -1;
  for (let slot = 0; slot < 4; slot++) {
    const weight = skinWeight.getComponent(index, slot);
    if (weight <= bestWeight) continue;
    bestWeight = weight;
    bestSlot = slot;
  }
  return bestSlot;
}

function measureBoneBoxes(root) {
  root.updateMatrixWorld(true);
  const bounds = new Map();
  const vertex = new THREE.Vector3();

  root.traverse((child) => {
    if (!child.isSkinnedMesh) return;
    const position = child.geometry.getAttribute('position');
    const skinIndex = child.geometry.getAttribute('skinIndex');
    const skinWeight = child.geometry.getAttribute('skinWeight');
    if (!skinIndex || !skinWeight) {
      throw new Error(`T. rex mesh '${child.name}' is skinned but carries no skin weights.`);
    }

    for (let index = 0; index < position.count; index++) {
      const slot = dominantSkinSlot(skinWeight, index);
      const bone = child.skeleton.bones[skinIndex.getComponent(index, slot)];
      if (!bone) continue;
      vertex.fromBufferAttribute(position, index).applyMatrix4(child.matrixWorld);
      const box = bounds.get(bone.name) ?? new THREE.Box3().makeEmpty();
      bounds.set(bone.name, box.expandByPoint(vertex));
    }
  });

  if (bounds.size === 0) throw new Error('T. rex tier has no skinned vertices to measure a hitbox from.');

  const center = new THREE.Vector3();
  const size = new THREE.Vector3();
  const bonePosition = new THREE.Vector3();
  return Object.freeze([...bounds].map(([boneName, box]) => {
    root.getObjectByName(boneName).getWorldPosition(bonePosition);
    box.getCenter(center).sub(bonePosition);
    box.getSize(size).multiplyScalar(0.5);
    return Object.freeze({
      boneName,
      offsetX: center.x,
      offsetY: center.y,
      offsetZ: center.z,
      halfWidth: size.x,
      halfHeight: size.y,
      halfDepth: size.z,
    });
  }));
}

