// Rebuilt every frame from the posed skeleton, because the animal walks and its
// legs swing. The bone's world position already carries the animation, the
// group's scale and the terrain tilt; only its measured box has to be turned
// from model axes into world ones, which the heading does.
const dinosaurSolidList = [];
const bonePosition = new THREE.Vector3();

function appendActorSolids(actor, solids) {
  const cosHeading = Math.cos(actor.heading);
  const sinHeading = Math.sin(actor.heading);

  for (const { box, node } of actor.hitboxBones) {
    node.getWorldPosition(bonePosition);
    const centerY = bonePosition.y + box.offsetY * actor.scale;
    const halfHeight = box.halfHeight * actor.scale;
    solids.push(boxSolid({
      x: bonePosition.x + (box.offsetX * cosHeading + box.offsetZ * sinHeading) * actor.scale,
      z: bonePosition.z + (-box.offsetX * sinHeading + box.offsetZ * cosHeading) * actor.scale,
      halfWidth: box.halfWidth * actor.scale,
      halfDepth: box.halfDepth * actor.scale,
      yaw: actor.heading,
      bottom: centerY - halfHeight,
      top: centerY + halfHeight,
    }));
  }
}

/** Every dinosaur's live hitbox, for this frame. Immovable, like the rocks. */
export function dinosaurSolids() {
  dinosaurSolidList.length = 0;
  for (const actor of DINOSAURS) appendActorSolids(actor, dinosaurSolidList);
  return dinosaurSolidList;
}

