// Drives the truck at the solid from `from` metres back, one 60 Hz step at a
// time, exactly as the main loop does: move first, then resolve.
function driveInto(solid, { heading = 0, speed = MAX_SPEED, from = 12, height = CAR_Y } = {}) {
  const carRig = new THREE.Object3D();
  const travelX = -Math.sin(heading) * Math.sign(speed);
  const travelZ = -Math.cos(heading) * Math.sign(speed);
  carRig.position.set(-travelX * from, height, -travelZ * from);
  const driveState = createDriveState();
  driveState.heading = heading;
  driveState.speed = speed;

  const puffs = [];
  const { resolveCollisions, lastImpact } = createCollisionSystem({
    solids: [solid],
    bodySize: TRUCK_BODY,
    emitWorldPuff: (position) => puffs.push(position.clone()),
  });

  let contacts = 0;
  let speedOnFirstContact = null;
  for (let step = 0; step < 180; step++) {
    carRig.position.x += -Math.sin(driveState.heading) * driveState.speed / 60;
    carRig.position.z += -Math.cos(driveState.heading) * driveState.speed / 60;
    const approachSpeed = driveState.speed;
    resolveCollisions(carRig, driveState, []);
    if (lastImpact.contacts === 0) continue;
    contacts += lastImpact.contacts;
    speedOnFirstContact ??= approachSpeed;
  }
  return { carRig, driveState, contacts, speedOnFirstContact, puffs, lastImpact };
}

