test('a square hit spends the truck and throws it back at the bounce fraction', () => {
  const run = driveInto(testWall());

  assert.equal(run.speedOnFirstContact, MAX_SPEED, 'The truck must arrive at full speed.');
  assert.ok(
    Math.abs(run.driveState.speed + MAX_SPEED * COLLISION.bounce) < 1e-12,
    `Expected a rebound of exactly ${MAX_SPEED * COLLISION.bounce} m/s, got ${run.driveState.speed}.`,
  );
  assert.equal(run.driveState.heading, 0, 'A square hit has no lever arm and must not twist the truck.');
  assert.ok(run.driveState.impactPitch < 0, 'A nose-first hit must dive the nose, not lift it.');
  assert.equal(run.puffs.length, 1, 'One hit must throw exactly one burst of dust.');
});

test('a hit leaves the truck touching the face it struck, never inside it', () => {
  const wall = testWall();
