    - TRUCK_BODY.width * 0.5;

  assert.ok(
    capsuleFront >= wall.halfDepth - 1e-9,
    `The truck's front reached z=${capsuleFront}, inside the wall face at z=${wall.halfDepth}.`,
  );
  assert.ok(
    capsuleFront - wall.halfDepth < 0.5,
