  );
});

test('reversing into a solid mirrors driving into it', () => {
  const forward = driveInto(testWall());
  const reverse = driveInto(testWall(), { heading: Math.PI, speed: -MAX_SPEED });

  assert.ok(
    Math.abs(reverse.driveState.speed + forward.driveState.speed) < 1e-12,
    'Reverse must rebound by the same amount forward does, with the opposite sign.',
  );
  assert.ok(reverse.driveState.impactPitch > 0, 'Backing into something must lift the nose.');
});

test('a graze keeps most of the speed and slides the truck along the face', () => {
  const grazeHeading = 1.22;
  const run = driveInto(testWall(), { heading: grazeHeading });

  assert.ok(
    run.driveState.speed > MAX_SPEED * 0.6,
    `A 70-degree graze must not stop the truck; it kept ${run.driveState.speed} m/s.`,
  );
  assert.ok(run.contacts > 1, 'A graze must keep sliding along the face rather than bouncing off once.');
  assert.ok(
