export function createBumpStage(shell, hooks) {
  const solids = hooks.solids ?? [];
  const keys = hooks.keys;
  const lastImpact = hooks.lastImpact ?? { approachSpeed: 0, impact: 0, kind: 'none', solids: 0, contacts: 0 };
  const params = new URLSearchParams(location.search);
  const state = { showColliders: true, topDown: params.get('top') === '1', target: 'none', ramming: false };
  const staticLines = createWireframe(0x36f2a0);
  const movingLines = createWireframe(0xff5aa8);
  const lookTarget = new THREE.Vector3();

  function lineUpOn(kindMatches, label) {
    const solid = nearestSolid(solids, shell.carRig.position, kindMatches);
    faceTarget(shell, solid.x, solid.z, RUN_UP);
    state.target = label;
    stopRamming();
  }

  const TARGETS = {
    rock: () => lineUpOn((solid) => solid.kind !== 'tree', 'nearest rock'),
    tree: () => lineUpOn((solid) => solid.kind === 'tree', 'nearest tree'),
    belly: () => lineUpOnDinosaur(shell, state, false),
    foot: () => lineUpOnDinosaur(shell, state, true),
  };

  function startRamming() {
    state.ramming = true;
    if (keys) keys.f = true;
  }

  // The truck drives in on the real throttle, then parks itself the moment it
  // touches something — so a screenshot taken any time after shows exactly where
  // the solid stopped it, rather than wherever the rebound carried it.
  function stopRamming() {
    state.ramming = false;
    if (keys) keys.f = false;
    shell.driveState.speed = 0;
  }

  return {
    state,

    setup() {
      shell.carRig.parent.add(staticLines);
      shell.carRig.parent.add(movingLines);
      staticLines.visible = state.showColliders;
      movingLines.visible = state.showColliders;

      window.addEventListener('keydown', (event) => {
        if (event.key === '1') TARGETS.rock();
        else if (event.key === '2') TARGETS.tree();
        else if (event.key === '3') TARGETS.belly();
        else if (event.key === '4') TARGETS.foot();
        else if (event.key === '0') state.topDown = !state.topDown;
        else if (event.key === 'k' || event.key === 'K') {
          state.showColliders = !state.showColliders;
          staticLines.visible = state.showColliders;
          movingLines.visible = state.showColliders;
        } else if (event.key === 'g' || event.key === 'G') startRamming();
      });

      // URL-driven setup, so one `open` call produces the exact frame wanted and
      // no synthetic key has to be injected into a page that repeats them badly.
      const requested = params.get('at');
      if (requested) {
        if (!TARGETS[requested]) {
          throw new Error(`Unknown bump-stage target '${requested}'; expected one of ${Object.keys(TARGETS).join(', ')}.`);
        }
        TARGETS[requested]();
        if (params.get('ram') === '1') startRamming();
      }

      console.log(
        '[stage] bump · 1 nearest rock · 2 nearest tree · 3 T. rex belly · 4 T. rex foot · '
        + 'g ram at full speed · k colliders · 0 top-down',
      );
      console.log(`[stage] ${solids.length} fixed solids · ?at=rock|tree|belly|foot &ram=1 &top=1`);
    },

    tick(camera) {
      if (state.ramming && lastImpact.contacts > 0) stopRamming();
      if (state.showColliders) {
        redrawWireframe(staticLines, solids, shell.carRig.position);
        redrawWireframe(movingLines, dinosaurSolids(), shell.carRig.position);
