const RUN_UP = 26;          // metres back from a target the truck lines up at
const WIREFRAME_RANGE = 140; // only draw colliders this close, or the lines are soup

function appendSolidEdges(solid, positions) {
  const centerY = (solid.bottom + solid.top) * 0.5;
  const halfHeight = (solid.top - solid.bottom) * 0.5;
  const corners = EDGE_CORNERS.map(([signX, signY, signZ]) => {
    const localX = signX * solid.halfWidth;
    const localZ = signZ * solid.halfDepth;
    return [
      solid.x + localX * solid.cosYaw + localZ * solid.sinYaw,
      centerY + signY * halfHeight,
      solid.z - localX * solid.sinYaw + localZ * solid.cosYaw,
    ];
  });
  for (const [from, to] of EDGE_PAIRS) positions.push(...corners[from], ...corners[to]);
}

function createWireframe(color) {
  const material = new THREE.LineBasicMaterial({ color, depthTest: false, transparent: true, opacity: 0.9 });
  const lines = new THREE.LineSegments(new THREE.BufferGeometry(), material);
  lines.frustumCulled = false;
  lines.renderOrder = 999;
  lines.visible = false;
  return lines;
}

function redrawWireframe(lines, solids, near) {
  const positions = [];
  for (const solid of solids) {
    if ((solid.x - near.x) ** 2 + (solid.z - near.z) ** 2 > WIREFRAME_RANGE ** 2) continue;
    appendSolidEdges(solid, positions);
  }
  lines.geometry.dispose();
  lines.geometry = new THREE.BufferGeometry().setAttribute(
    'position',
    new THREE.Float32BufferAttribute(positions, 3),
  );
}

