const RUN_UP = 26;             // metres back from a target the truck lines up at
const FLOATS_PER_SOLID = EDGE_PAIRS.length * 2 * 3;
const MOVING_SOLID_CAPACITY = 128; // room for every dinosaur bone box, with slack

// Writes one box's 12 edges into `positions` starting at `offset`, and returns
// where the next box should start.
function writeSolidEdges(solid, positions, offset) {
  const centerY = (solid.bottom + solid.top) * 0.5;
  const halfHeight = (solid.top - solid.bottom) * 0.5;
  const corners = EDGE_CORNERS.map(([signX, signY, signZ]) => {
    const localX = signX * solid.halfWidth;
    const localZ = signZ * solid.halfDepth;
    return [
      solid.x + localX * solid.cosYaw + localZ * solid.sinYaw,
      centerY + signY * halfHeight,
      solid.z - localX * solid.sinYaw + localZ * solid.cosYaw,
    ];
  });

  let cursor = offset;
  for (const pair of EDGE_PAIRS) {
    for (const corner of pair) {
      positions[cursor++] = corners[corner][0];
      positions[cursor++] = corners[corner][1];
      positions[cursor++] = corners[corner][2];
    }
  }
  return cursor;
}

// One LineSegments with a fixed buffer, drawn up to `drawRange`. Rebuilding the
// geometry every frame instead would churn megabytes a second and take the tab
// down with it.
function createWireframe(color, capacity) {
  const positions = new Float32Array(capacity * FLOATS_PER_SOLID);
  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
  const material = new THREE.LineBasicMaterial({ color, depthTest: false, transparent: true, opacity: 0.9 });
  const lines = new THREE.LineSegments(geometry, material);
  lines.frustumCulled = false;
  lines.renderOrder = 999;
  lines.visible = false;
  return lines;
}

function redrawWireframe(lines, solids) {
  const positions = lines.geometry.attributes.position;
  const capacity = Math.min(solids.length, positions.array.length / FLOATS_PER_SOLID);
  let cursor = 0;
  for (let index = 0; index < capacity; index++) {
    cursor = writeSolidEdges(solids[index], positions.array, cursor);
  }
  positions.needsUpdate = true;
  lines.geometry.setDrawRange(0, cursor / 3);
}

