/** Move a solid that keeps its shape. A dinosaur's bone boxes are sized once
 * from the bind pose and only ever travel, so `reach` and the half extents stay
 * valid and a moving solid costs no allocation per frame.
 * @example placeBoxSolid(boxSolid({ kind: 'x', x: 0, z: 0, halfWidth: 3, halfDepth: 4, yaw: 0, bottom: 0, top: 2 }), 9, 0, 0, 1, 3).x === 9
 */
export function placeBoxSolid(solid, x, z, yaw, bottom, top) {
  solid.x = x;
  solid.z = z;
  solid.bottom = bottom;
  solid.top = top;
  solid.cosYaw = Math.cos(yaw);
  solid.sinYaw = Math.sin(yaw);
  return solid;
}

