const bonePosition = new THREE.Vector3();

function appendActorSolids(actor, solids) {
  const cosHeading = Math.cos(actor.heading);
  const sinHeading = Math.sin(actor.heading);

  for (const { box, node } of actor.hitboxBones) {
    node.getWorldPosition(bonePosition);
