cases.new_string:
// Re-placed every frame from the posed skeleton, because the animal walks and
// its legs swing. Each bone's world position already carries the animation, the
// group's scale and the terrain tilt, so only the measured offset has to be
// turned from model axes into world ones, which the heading does.
//
// The heading alone, deliberately: the group's terrain tilt is left out of that
// turn, exactly as the rock colliders leave out each part's small X/Z tilt. The
// error is the offset times the sine of the tilt, so it is worst for the biggest
// offsets, which belong to the torso and neck ten metres up where no truck can
// reach, and it stays under about 20 cm at the feet, which are the parts you
// actually hit.
const dinosaurSolidList = [];
const bonePosition = new THREE.Vector3();

function appendActorSolids(actor, solids) {
  const cosHeading = Math.cos(actor.heading);
  const sinHeading = Math.sin(actor.heading);

  for (const { box, node, solid } of actor.hitboxBones) {
    node.getWorldPosition(bonePosition);
    const centerY = bonePosition.y + box.offsetY * actor.scale;
    const halfHeight = box.halfHeight * actor.scale;
    placeBoxSolid(
      solid,
      bonePosition.x + (box.offsetX * cosHeading + box.offsetZ * sinHeading) * actor.scale,
      bonePosition.z + (-box.offsetX * sinHeading + box.offsetZ * cosHeading) * actor.scale,
      actor.heading,
      centerY - halfHeight,
      centerY + halfHeight,
    );
    solids.push(solid);
  }
}

test('moving a solid keeps the size and reach it was built with', () => {
  const solid = boxSolid({
    kind: 'foot_left', x: 0, z: 0, halfWidth: 3, halfDepth: 4, yaw: 0, bottom: 0, top: 2,
  });

  const moved = placeBoxSolid(solid, 40, -25, Math.PI / 2, 7, 11);

  assert.equal(moved, solid, 'Moving a solid must rewrite it in place, not allocate a new one.');
  assert.deepEqual(
    { halfWidth: moved.halfWidth, halfDepth: moved.halfDepth, reach: moved.reach, kind: moved.kind },
    { halfWidth: 3, halfDepth: 4, reach: 5, kind: 'foot_left' },
    'A bone box is sized once from the bind pose; travelling must never resize it.',
  );
  assert.deepEqual(
    { x: moved.x, z: moved.z, bottom: moved.bottom, top: moved.top },
    { x: 40, z: -25, bottom: 7, top: 11 },
    'Every part of the placement must follow the bone.',
  );
  assert.ok(Math.abs(moved.cosYaw) < 1e-15 && Math.abs(moved.sinYaw - 1) < 1e-15, 'Yaw must follow too.');
});

