/**
 * Raised instead of creating a chat whose FIRST message is a command.
 *
 * `createThread` cannot answer until the message it carries is admitted, so
 * the chat has no id for as long as Pi holds the prompt — and a command that
 * raises a host-UI dialog would then be waiting on a client that has no thread
 * to subscribe to. Nothing can tell an interactive command from a quiet one,
 * so all of them are refused in that one position. A command sent to a thread
 * that already exists is unaffected.
 */
export class PiFirstMessageCommandError extends Error {
  readonly commandName: string;

  constructor(commandName: string) {
    super("a command cannot be a chat's first message");
    this.name = "PiFirstMessageCommandError";
    this.commandName = commandName;
  }
}

/**
 * The command name Pi would parse out of this text — the first token after a
 * leading slash — or undefined when the text is not slash-shaped.
 *
 * Pi does not trim: `prompt()`, `steer()` and `followUp()` all test
 * `text.startsWith("/")` on the text exactly as given.
 *
 * >>> commandNameOf("/noop with args")
 * "noop"
 * >>> commandNameOf("how many customers churned")
 * undefined
 */
const commandNameOf = (text: string): string | undefined =>
  text.startsWith("/") ? text.slice(1).split(/\s/)[0] : undefined;

/**
 * The command this text names in THIS session's registry, or undefined.
 *
 * Three sources, because Pi dispatches a slash-prefixed prompt against three:
 * an extension command executes immediately, a `/skill:` name expands into a
 * skill block, and any other name expands as a prompt template.
 *
 * It has to be the SESSION's registry. An extension registers commands from
 * its `session_start` handler and contributes prompts and skills from
 * `resources_discover`, and neither hook has run on a resource loader built
 * outside a session — so a list taken there is missing exactly the entries
 * nothing else can see.
 */
const sessionCommandNamed = (
  session: AgentSession,
  text: string,
): string | undefined => {
  const name = commandNameOf(text);
  if (name === undefined) return undefined;
  const known =
    session.extensionRunner.getCommand(name) !== undefined ||
    session.promptTemplates.some((template) => template.name === name) ||
    session.resourceLoader
      .getSkills()
      .skills.some((skill) => `skill:${skill.name}` === name);
  return known ? name : undefined;
};

