cases.new_string:
const record = await this.openSession(sessionManager, cwd, {
  threadId,
  isNew: true,
});
// A command cannot be a chat's FIRST message, and this is the one place
// the rule can be answered honestly: the session exists, so its registry
// is the one Pi will dispatch against, and the message has not been
// admitted yet. Refusing here rather than from a list built elsewhere is
// the whole point — a list built outside a session is blind to the two
// hooks that register during one.
const refused = input?.initialMessage
  ? sessionCommandNamed(record.session, input.initialMessage.content)
  : undefined;
if (refused !== undefined) {
  this.discardSession(record);
  throw new PiFirstMessageCommandError(refused);
}
this.invalidateCatalog(cwd);

/**
 * Let go of a session the host is not going to use, before it has been given
 * anything to do.
 *
 * Nothing has to be unlinked: Pi holds a new session's entries in memory and
 * writes the file only once the session has an ASSISTANT message
 * (`SessionManager._persist`), so a session refused before its first message
 * leaves nothing behind. Anything the host may already have created FOR the
 * thread — an artifact directory from `createResourceLoader`, say — is the
 * host's own, and it is the same litter a chat the user abandons leaves.
 */
private discardSession(record: ThreadRecord): void {
  const sessionFile = record.session.sessionFile;
  record.unsubscribe();
  record.session.dispose();
  this.records.delete(record.threadId);
  if (sessionFile) this.recordsBySessionFile.delete(sessionFile);
}

