// Pi's own registry answers whether a slash-prefixed prompt is a command,
// and it has three parts: an extension command executes immediately, a
// `/skill:` name expands into a skill block, anything else into a prompt
// template. All three are read off the SESSION, because two of Pi's hooks
// add to them while the session is being built.
extensionRunner: { getCommand: () => undefined },
promptTemplates: [] as { name: string }[],
resourceLoader: { getSkills: () => ({ skills: [] as { name: string }[] }) },

describe("a command cannot be a chat's first message", () => {
  /** A session whose registry only fills in once Pi has bound its
   * extensions, which is what a `session_start` handler and a
   * `resources_discover` handler both do. Before that call the session
   * answers exactly what a resource loader built outside one answers:
   * nothing. */
  const sessionWithLateRegistry = () => {
    let bound = false;
    return createLiveSession({
      sessionId: "new-thread",
      sessionFile: undefined,
      bindExtensions: vi.fn(async () => {
        bound = true;
      }),
      extensionRunner: {
        getCommand: (name: string) =>
          bound && name === "latecommand" ? { invocationName: name } : undefined,
      },
      get promptTemplates() {
        return bound ? [{ name: "lateprompt" }] : [];
      },
      resourceLoader: {
        getSkills: () => ({ skills: bound ? [{ name: "lateskill" }] : [] }),
      },
    });
  };

  beforeEach(() => {
    sdk.create.mockReturnValue({ getSessionId: () => "new-thread" });
    sdk.createAgentSession.mockImplementation(async () => ({
      session: sessionWithLateRegistry(),
    }));
  });

  it.each([
    ["an extension command registered in session_start", "/latecommand"],
    ["one with arguments", "/latecommand everything older than May"],
    ["a prompt contributed by resources_discover", "/lateprompt"],
    ["a skill contributed by resources_discover", "/skill:lateskill"],
  ])("refuses %s", async (_label, content) => {
    const supervisor = new PiThreadSupervisor({ workspacePath: "/ws" });

    await expect(
      supervisor.createThread({ initialMessage: { content } }),
    ).rejects.toThrow("a command cannot be a chat's first message");
  });

  it("leaves nothing behind when it refuses", async () => {
    const supervisor = new PiThreadSupervisor({ workspacePath: "/ws" });

    await expect(
      supervisor.createThread({ initialMessage: { content: "/latecommand" } }),
    ).rejects.toBeInstanceOf(PiFirstMessageCommandError);

    // The session is disposed and forgotten. Pi writes no file before a
    // session has an assistant message, so there is nothing to unlink and
    // nothing for a later lookup to find.
    const session = sdk.createAgentSession.mock.results[0]
      ?.value as Promise<{ session: { dispose: ReturnType<typeof vi.fn> } }>;
    expect((await session).session.dispose).toHaveBeenCalled();
    await expect(supervisor.getThread("new-thread")).rejects.toThrow(
      "Unknown Pi thread: new-thread",
    );
  });

  it("lets an ordinary first message through, slash-shaped or not", async () => {
    const supervisor = new PiThreadSupervisor({ workspacePath: "/ws" });

    // The registry is the authority, not the shape of the text: a question
    // that merely starts with a slash is still a question.
    for (const content of [
      "how many customers churned",
      "/how many customers churned",
    ]) {
      const snapshot = await supervisor.createThread({
        initialMessage: { content },
      });
      expect(snapshot.metadata.id).toBe("new-thread");
    }
  });

  it("still runs a command on a thread that already exists", async () => {
    const supervisor = new PiThreadSupervisor({ workspacePath: "/ws" });
    const created = await supervisor.createThread();

    await expect(
      supervisor.sendMessage(created.metadata.id, {
        content: "/latecommand",
      }),
    ).resolves.toBeUndefined();
  });
});

