/** One loader for the whole host, reloaded on first use. Discovery reads the
 * filesystem, and the menu is not worth a walk per keystroke. */
let discovery: Promise<DefaultResourceLoader> | undefined;

const loadResources = (): Promise<DefaultResourceLoader> => {
  discovery ??= (async () => {
    const loader = new DefaultResourceLoader({
      cwd: workspacePath,
      agentDir: agentDir ?? getAgentDir(),
    });
    await loader.reload();
    return loader;
  })();
  return discovery;
};

cases.new_string:
/** One loader for the whole host, reloaded on first use. Discovery reads the
 * filesystem, and the menu is not worth a walk per keystroke. */
let discovery: Promise<DefaultResourceLoader> | undefined;

const reloadResources = async (): Promise<DefaultResourceLoader> => {
  const loader = new DefaultResourceLoader({
    cwd: workspacePath,
    agentDir: agentDir ?? getAgentDir(),
  });
  await loader.reload();
  return loader;
};

/** A SUCCESS is cached; a failure is not. Discovery walks the filesystem, so
 * it can fail for a reason that has already passed — and a rejected promise
 * left in the cache answers every later call with that same failure for the
 * life of the process, which is a menu that never comes back. */
const loadResources = async (): Promise<DefaultResourceLoader> => {
  const pending = (discovery ??= reloadResources());
  try {
    return await pending;
  } catch (error) {
    if (discovery === pending) discovery = undefined;
    throw error;
  }
};

