/**
 * What a session has spent, or `undefined` when the value is not that.
 *
 * Both fields are required and both have to be FINITE. This event and the
 * metadata carrying it cross a process boundary as JSON, and the reducer is
 * where that JSON first becomes state a component renders — the header calls
 * `usage.cost.toFixed(4)` on it, so a string reaches the user as a thrown
 * error. Finite and not merely numeric, because the accumulator below takes a
 * maximum: one `NaN` wins every comparison after it and the total is stuck
 * there for the life of the thread.
 *
 * >>> sessionUsage({ cost: 0.5, toolCalls: 2 })
 * { cost: 0.5, toolCalls: 2 }
 * >>> sessionUsage({ cost: "bad", toolCalls: [] })
 * undefined
 */
const sessionUsage = (value: unknown): PiSessionUsage | undefined => {
  if (typeof value !== "object" || value === null) return undefined;
  const { cost, toolCalls } = value as { cost?: unknown; toolCalls?: unknown };
  return Number.isFinite(cost) && Number.isFinite(toolCalls)
    ? { cost: cost as number, toolCalls: toolCalls as number }
    : undefined;
};

