/**
 * Metadata carrying only a spend this reader can use.
 *
 * A snapshot's metadata is ADOPTED, field for field, and it arrives as JSON
 * over the same stream the events do — so an unusable `usage` on it reaches
 * readers even when the merged value is refused. The refusal has to be taken
 * off what travels on, which is the rule round 27's addendum applied to a
 * group claimed on a finished thread.
 */
const withoutUnusableUsage = (
  metadata: PiThreadMetadata,
): PiThreadMetadata => {
  if (metadata.usage === undefined || sessionUsage(metadata.usage)) {
    return metadata;
  }
  const { usage: _refused, ...rest } = metadata;
  return rest;
};

