def bisect_dirty(values, budget):
    """Return the individual values a YES chunk is dirty on. Costs about 2*log2(len) calls."""
    if budget[0] <= 0:
        return None
    if len(values) == 1:
        return list(values)
    middle = len(values) // 2
    found = []
    for half in (values[:middle], values[middle:]):
        budget[0] -= 1
        if budget[0] <= 0:
            return None
        if judge(half) == "YES":
            sub = bisect_dirty(half, budget)
            if sub is None:
                return None
            found.extend(sub)
    return found

