import transcript_common

KNOWN_BLOCKS = frozenset({"tool-input", "tool-output"})
KNOWN_MESSAGES = frozenset({"user-message", "assistant-response", "compaction"})


class Loose(pydantic.BaseModel):
    """Duck typing. Unknown keys are data, not errors."""

    model_config = pydantic.ConfigDict(extra="allow")


class TextPart(Loose):
    type: Literal["text"]
    text: str


class ToolInputBlock(Loose):
    type: Literal["tool-input"]
    name: str = pydantic.Field(min_length=1)
    id: str | None = None
    native_tool_call_id: str | None = None
    input: dict[str, Any] | None = None


class ToolOutputBlock(Loose):
    type: Literal["tool-output"]
    name: str = pydantic.Field(min_length=1)
    id: str | None = None
    native_tool_call_id: str | None = None
    is_error: bool = False
    content: str | list[Union[TextPart, Loose]] = ""


class OpaqueBlock(Loose):
    """Thinking blocks, subagent tasks, anything else this mode passes through."""

    type: str

    @pydantic.field_validator("type")
    @classmethod
    def must_not_shadow_a_known_block(cls, value: str) -> str:
        if value in KNOWN_BLOCKS:
            raise ValueError(f"malformed {value} block")
        return value


ContentItem = Union[str, ToolInputBlock, ToolOutputBlock, OpaqueBlock]


class KnownMessage(Loose):
    type: Literal["user-message", "assistant-response", "compaction"]
    original_index: int
    content: list[ContentItem]
    role: str | None = None


class ForeignMessage(Loose):
    type: str

    @pydantic.field_validator("type")
    @classmethod
    def must_not_shadow_a_known_message(cls, value: str) -> str:
        if value in KNOWN_MESSAGES:
            raise ValueError(f"malformed {value} message")
        return value


TRANSCRIPT = pydantic.TypeAdapter(list[Union[KnownMessage, ForeignMessage]])


@dataclasses.dataclass(frozen=True)
class Verdict:
    """Whether --annotate may run, and why not when it may not."""

    ok: bool
    reason: str = ""
    messages: tuple[KnownMessage, ...] = ()


def gate(raw: object) -> Verdict:
    """Accept a transcript only when nothing it recognizes is malformed.

    >>> gate([{"type": "user-message", "original_index": 1, "content": ["hi"]}]).ok
    True
    >>> gate([{"type": "user-message", "original_index": 1, "content": []}]).reason
    'no messages match the assumed export shape'
    """
    if not isinstance(raw, list):
        return Verdict(False, "expected a top-level JSON array of message objects")
    try:
        parsed = TRANSCRIPT.validate_python(raw)
    except pydantic.ValidationError as error:
        first = error.errors()[0]
        location = ".".join(str(part) for part in first.get("loc", ()))
        return Verdict(False, f"{location}: {first.get('msg')}")
    recognized = tuple(
        message
        for message in parsed
        if isinstance(message, KnownMessage) and message.content
    )
    if not recognized:
        return Verdict(False, "no messages match the assumed export shape")
    return Verdict(True, messages=recognized)

