def refusal_reason(error: pydantic.ValidationError) -> str:
    """Pick the one union branch the author meant, out of every branch that failed.

    A failed union reports each member. The `str` member and any member whose own
    `type` mismatched are noise, because the object never claimed to be those.

    >>> refusal_reason(_example_union_error())
    'content.0.ToolInputBlock.name: Field required'
