        if location and location[-1] not in {"str", "type"}:
            return f"{'.'.join(location)}: {candidate.get('msg')}"
    first = error.errors()[0]
    return f"{'.'.join(str(part) for part in first.get('loc', ()))}: {first.get('msg')}"


