const SECRET = "__SECRET__";
const toggle = document.getElementById("toggle");
const status = document.getElementById("status");
const result = document.getElementById("result");
let recorder = null;
let chunks = [];
let wakeLock = null;
let pendingBlob = null;
let pendingFilename = null;
let timerInterval = null;

if (!navigator.mediaDevices) document.body.classList.add("no-mic");

toggle.onclick = async () => {
  if (recorder && recorder.state === "recording") { recorder.stop(); return; }
  if (pendingBlob) { upload(pendingBlob, pendingFilename); return; }
  let stream;
  try {
    stream = await navigator.mediaDevices.getUserMedia({ audio: true });
  } catch (_) {
    status.textContent = "יש לאפשר גישה למיקרופון בהגדרות הטלפון.";
    return;
  }
  try { wakeLock = await navigator.wakeLock.request("screen"); } catch (_) { wakeLock = null; }
  const mimeType = MediaRecorder.isTypeSupported("audio/mp4") ? "audio/mp4" : "audio/webm";
  recorder = new MediaRecorder(stream, { mimeType });
  chunks = [];
  recorder.ondataavailable = (event) => chunks.push(event.data);
  recorder.onstop = () => {
    stream.getTracks().forEach((track) => track.stop());
    clearInterval(timerInterval);
    const extension = mimeType === "audio/mp4" ? "m4a" : "webm";
    upload(new Blob(chunks, { type: mimeType }), "recording." + extension);
  };
  recorder.start();
  toggle.textContent = "עצור ושלח";
  toggle.classList.add("recording");
  result.textContent = "";
  const startedAt = Date.now();
  const showElapsed = () => {
    const seconds = Math.floor((Date.now() - startedAt) / 1000);
    const minutes = String(Math.floor(seconds / 60)).padStart(2, "0");
    status.textContent = "מקליט... " + minutes + ":" + String(seconds % 60).padStart(2, "0");
  };
  showElapsed();
  timerInterval = setInterval(showElapsed, 1000);
};

document.getElementById("pick").onchange = (event) => {
  const file = event.target.files[0];
  if (file) upload(file, file.name);
};

async function upload(blob, filename) {
  recorder = null;
  toggle.classList.remove("recording");
  toggle.textContent = "שולח...";
  toggle.disabled = true;
  status.textContent = "מעבד...";
  const form = new FormData();
  form.append("file", blob, filename);
  try {
    const response = await fetch("/recordings", {
      method: "POST",
      headers: { "X-Auth-Secret": SECRET },
      body: form,
    });
    if (!response.ok) throw new Error(await response.text());
    const data = await response.json();
    pendingBlob = null;
    pendingFilename = null;
    toggle.textContent = "התחל הקלטה";
    if (data.findings.length) {
      status.textContent = "הממצאים נשלחו למחשב:";
      result.textContent = data.findings.join("\\n");
    } else {
      status.textContent = "לא זוהו ממצאים רפואיים. התמלול:";
      result.textContent = data.transcript;
    }
  } catch (error) {
    pendingBlob = blob;
    pendingFilename = filename;
    toggle.textContent = "נסה שוב";
    status.textContent = "השליחה נכשלה. ההקלטה נשמרה לניסיון נוסף.";
  } finally {
    toggle.disabled = false;
    if (wakeLock) { wakeLock.release(); wakeLock = null; }
  }
}

