// Every rival holds its own lane for the whole race, and the centre lane belongs
// to the player. Lanes alternate sides and step outward, so rival 0 runs one
// side, rival 1 the other, rival 2 outside rival 0. Holding the lane rather than
// sliding into it near the player is what makes "never share a piece of road" an
// invariant instead of a race between two easing curves — and a field spread
// across the trail reads as a race, where single file does not.
function laneFor(index) {
  const side = index % 2 === 0 ? 1 : -1;
  const rank = Math.floor(index / 2);
  return side * (RACE.laneNearest + rank * RACE.laneStep);
}

