 * ONE thing, all of it or none of it. `status` and `runActive` answer two
 * halves of the same question and a reader that got only the second reached a
 * state the UI cannot mean — a group rendered as still being written on a
 * thread the control surface calls idle. A server older than this resolution
 * sends none of it, and the reader degrades (see `reducePiThreadState`).
 */
export type PiSettlementResolution = {
  /** The thread's status as the host reports it — the same busy union
   * `PiThreadMetadata.status` carries. A settlement that belonged to an older
   * run leaves the host's own run open, and that is what keeps this
   * `running`. */
  status: PiThreadStatus;
  /** Whether a run is still writing the newest group, in the one meaning this
   * field has everywhere else (the same rule a snapshot's
   * `metadata.runActive` carries). A run at `agent_start` whose first message
   * is still behind an extension hook is not writing anything yet. */
  runActive: boolean;
  /** The error the RUN produced, if it did. Absent for a run that finished
   * cleanly, whatever else the thread reported as a notice. */
  runError?: string;
};

cases.new_string:
 * ONE thing, all of it or none of it. `status` and `runActive` answer two
 * halves of the same question and a reader that got only the second reached a
 * state the UI cannot mean — a group rendered as still being written on a
 * thread the control surface calls idle. A server older than this resolution
 * sends none of it, and the reader degrades (see `reducePiThreadState`).
 *
 * The halves are also constrained against EACH OTHER, because that same
 * contradiction is expressible in a whole resolution: only a run the thread
 * still has open can be writing a group, and an open run is what keeps the
 * status `running`, so a terminal status cannot carry an active group. The
 * type says the parts of that a discriminated union says cleanly; the values
 * arrive as JSON, so `reducePiThreadState` is where the rest is enforced.
 */
export type PiSettlementResolution = {
  /** The error the RUN produced, if it did. Absent for a run that finished
   * cleanly, whatever else the thread reported as a notice. */
  runError?: string;
} & (
  | {
      /** The thread's status as the host reports it — the same busy union
       * `PiThreadMetadata.status` carries. A settlement that belonged to an
       * older run leaves the host's own run open, and that is what keeps this
       * `running`. */
      status: "running";
      /** Whether a run is still writing the newest group, in the one meaning
       * this field has everywhere else (the same rule a snapshot's
       * `metadata.runActive` carries). A run at `agent_start` whose first
       * message is still behind an extension hook is not writing anything
       * yet. */
      runActive: boolean;
    }
  | {
      /** The run is over and the thread holds no other, so nothing is being
       * written. */
      status: "idle" | "failed";
      runActive: false;
    }
);

