describe("PiSettlementResolution", () => {
  it("cannot express a group being written on a settled thread", () => {
    // The two halves are constrained against each other, not merely required
    // together: a group is written by a run the thread still holds open, and
    // an open run is what keeps the status `running`. So `runActive` is free
    // only under `running` — a run whose first message is still behind an
    // extension hook is open and writing nothing — while a terminal status
    // has no run left to be writing anything.
    const stillWriting: PiSettlementResolution = {
      status: "running",
      runActive: true,
    };
    const openButSilent: PiSettlementResolution = {
      status: "running",
      runActive: false,
    };
    const over: PiSettlementResolution = {
      status: "idle",
      runActive: false,
      runError: undefined,
    };
    const failed: PiSettlementResolution = {
      status: "failed",
      runActive: false,
      runError: "503: mock upstream overloaded",
    };
    const contradiction: PiSettlementResolution = {
      status: "idle",
      // @ts-expect-error a settled thread has no run writing a group
      runActive: true,
    };
    const failedContradiction: PiSettlementResolution = {
      status: "failed",
      // @ts-expect-error same rule, and a failure is just as terminal
      runActive: true,
    };

    // The compiler is the assertion; these keep the values used.
    expect([
      stillWriting,
      openButSilent,
      over,
      failed,
      contradiction,
      failedContradiction,
    ]).toHaveLength(6);
  });

  it("narrows `runActive` from the status a reader switches on", () => {
    const groupOf = (resolution: PiSettlementResolution): boolean => {
      if (resolution.status !== "running") {
        expectTypeOf(resolution.runActive).toEqualTypeOf<false>();
        return false;
      }
      expectTypeOf(resolution.runActive).toEqualTypeOf<boolean>();
      return resolution.runActive;
    };

    expect(groupOf({ status: "running", runActive: true })).toBe(true);
    expect(groupOf({ status: "idle", runActive: false })).toBe(false);
  });
});

