 * missing, a `null` that is present without being a status, a word from a
 * server newer than this reader, a group claimed on a thread that is done —
 * and degrades exactly like a bare one.
 *
 * >>> settlementResolution({ status: "idle", runActive: true })
 * undefined
 */
const settlementResolution = (event: {
  status?: unknown;
  runActive?: unknown;
  runError?: unknown;
}): PiSettlementResolution | undefined => {
  const { status, runActive, runError } = event;
  if (typeof runActive !== "boolean") return undefined;
  // The run's reason is the optional half, so an absent or unusable one means
  // the settlement reports no run error. It is never grounds to refuse the
  // resolution around it.
  const reason = typeof runError === "string" ? { runError } : {};
  if (status === "running") return { status, runActive, ...reason };
  if ((status === "idle" || status === "failed") && !runActive)
    return { status, runActive, ...reason };
  return undefined;
};

