/**
 * The events that END the group a run is writing, all four of them.
 *
 * State going idle is not the deliverable — the PROJECTION is what a reader
 * renders, and a group-ending event has to move both. `admission_end` moved
 * only the state, and the answer above it stayed running under a positional
 * id forever. The class is asserted here rather than sampled, because that
 * defect was invisible from every other angle: reducer tests call the pure
 * function, and the harness asserts over HTTP.
 */
describe("events that end the group", () => {
  /** A thread mid-run whose answer is written but not yet released: the
   * projection names the group positionally and reads it running. */
  const midRun = async () => {
    const client = createFakeClient(
      snapshot({
        metadata: { id: THREAD, status: "running", runActive: true },
        messages: [
          { role: "user", content: "hello", timestamp: 1 },
          assistantMessage("hi", 2),
        ],
        entryIds: ["e-user", "e-a"],
      }),
    );
    const controller = new PiThreadController(client, THREAD);
    await controller.load();
    controller.connect();

    const projected = () =>
      controller
        .getMessageRepository()
        .messages.map((entry) => entry.message);
    expect(
      projected().map((m) => m.id),
      "the group is still being written, so it holds a positional name",
    ).toEqual(["e-user", "pi-msg:1"]);
    expect(projected()[1]!.status).toEqual({ type: "running" });

    const notifications = { count: 0 };
    controller.subscribeMessages(() => {
      notifications.count += 1;
    });
    return { client, controller, projected, notifications };
  };

  /** What every one of these events has to leave behind: the answer settled
   * onto its durable entry id, read as finished, and the readers told. */
  const expectReleased = (
    { projected, notifications }: Awaited<ReturnType<typeof midRun>>,
    via: string,
  ) => {
    expect(
      projected().map((m) => m.id),
      `${via} ended the group, so the answer takes its durable id`,
    ).toEqual(["e-user", "e-a"]);
    expect(projected()[1]!.status, `${via} left the answer unfinished`).toEqual(
      { type: "complete", reason: "stop" },
    );
    expect(
      notifications.count,
      `${via} repainted without telling the message subscribers`,
    ).toBe(1);
  };

  it("releases it when an admission ends the thread", async () => {
    // The one that was broken. A prompt Pi HANDLED raises neither
    // `agent_start` nor `agent_settled`, so this event is the only thing
    // that ends this group — classified metadata-dirty, nothing could ever
    // repair the projection.
    const scenario = await midRun();

    scenario.client.emit(
      ev({ type: "admission_end", outcome: "handled", status: "idle" }, 5),
    );

    expectReleased(scenario, "admission_end");
  });

  it("releases it when the run settles", async () => {
    // The ordinary path, and the one every other test checked only through
    // `getState()`.
    const scenario = await midRun();

    scenario.client.emit(
      ev({ type: "agent_settled", status: "idle", runActive: false }, 5),
    );

    expectReleased(scenario, "agent_settled");
  });

  it("releases it when a snapshot reports the thread idle", async () => {
    // A snapshot is authoritative and can be the first thing a reconnecting
    // reader hears about a run that ended while the stream was down.
    const scenario = await midRun();

    scenario.client.emit(
      ev(
        {
          type: "snapshot",
          snapshot: snapshot({
            metadata: { id: THREAD, status: "idle", runActive: false },
            messages: [
              { role: "user", content: "hello", timestamp: 1 },
              assistantMessage("hi", 2),
            ],
            entryIds: ["e-user", "e-a"],
          }),
        },
        5,
      ),
    );

    expectReleased(scenario, "snapshot");
  });

  // `entry_ids` is the fourth, covered above by "renames messages from
  // entry_ids without going back for a snapshot" — it renames rather than
  // releases, so it asserts the ids and the notification on its own terms.
});

