/**
 * One thread's feedback file, or `null` when the path it names is not really
 * one. Three locks, each for a way in that the one before it does not close:
 *
 * 1. The id is proven to be ONE SEGMENT — `../owners` here read, and appended
 *    to, the ownership sidecar one directory up.
 * 2. The feedback DIRECTORY is resolved and contained. Being lexically inside
 *    the sidecar tree is a fact about a string; the directory itself can be a
 *    link, and then the id lands wherever that link went.
 * 3. The FILE must be a regular file or absent. `lstat`, not `exists`, because
 *    a dangling link reports absent and appending to one creates the file it
 *    points at — outside the tree, on the agent's terms.
 */
const feedbackFile = (threadId: string, create: boolean): string | null => {
  const dir = path.join(sidecarDir, "feedback");
  if (create) fs.mkdirSync(dir, { recursive: true });
  const realDir = realPathWithin(sidecarDir, dir);
  if (!realDir) return null;
  const file = threadScopedPath(realDir, threadId, ".jsonl");
  try {
    return fs.lstatSync(file).isFile() ? file : null;
  } catch {
    return create ? file : null;
  }
};

