cases.old_string:
 * >>> deriveSessionUsage([{ type: "message", message: { role: "assistant", usage: { cost: { total: 0.5 } } } }] as never)
 * { cost: 0.5, toolCalls: 0 }
 */
export const deriveSessionUsage = (
  entries: readonly SessionEntry[],
): PiSessionUsage => {
  let cost = 0;
  let toolCalls = 0;
  for (const entry of entries) {
    if (entry.type !== "message") continue;
    const message = entry.message as UsageBearingMessage;
    if (message?.role !== "assistant") continue;
    const total = message.usage?.cost?.total;
    if (typeof total === "number") cost += total;
    // `content` is a plain string for a text-only answer; only the block form
    // can carry a tool call.
    if (!Array.isArray(message.content)) continue;
    for (const block of message.content as readonly ContentBlock[]) {
      if (block?.type === "toolCall") toolCalls += 1;
    }
  }
  return { cost, toolCalls };
};

/** The assistant-message shape `deriveSessionUsage` reads, and nothing more. */
type UsageBearingMessage = {
  role?: string;
  usage?: { cost?: { total?: number } };
  content?: unknown;
} | null;

type ContentBlock = { type?: string } | null;

cases.new_string:
 * Pi BILLS more than the assistant messages, and counting only those reported
 * roughly half of a real session ($1.00 against Pi's own $2.05). The walk
 * mirrors `AgentSession.getSessionStats()` entry for entry, which is the
 * authority on what was charged: an assistant message's usage, a TOOL RESULT's
 * usage, and the usage a COMPACTION or a BRANCH SUMMARY records on the entry
 * itself — those two are summarization calls the user paid for, and they carry
 * their cost on the entry rather than on any message.
 *
 * Pi's own helper is not reused directly because it lives on `AgentSession`,
 * and this has to answer for a COLD thread too, where no session is open. It
 * reads the same `getEntries()` that helper reads, so the two agree; the
 * harness asserts that against a real session rather than trusting it.
 *
 * >>> deriveSessionUsage([{ type: "message", message: { role: "assistant", usage: { cost: { total: 0.5 } } } }] as never)
 * { cost: 0.5, toolCalls: 0 }
 */
export const deriveSessionUsage = (
  entries: readonly SessionEntry[],
): PiSessionUsage => {
  let cost = 0;
  let toolCalls = 0;
  const spend = (usage: UsageBearing["usage"]): void => {
    const total = usage?.cost?.total;
    if (typeof total === "number") cost += total;
  };
  for (const entry of entries) {
    const billed = entry as UsageBearing & { type?: string };
    // A summarization Pi ran on the user's behalf. The cost is on the ENTRY;
    // these carry no message at all.
    if (billed.type === "compaction" || billed.type === "branch_summary") {
      spend(billed.usage);
      continue;
    }
    if (entry.type !== "message") continue;
    const message = entry.message as UsageBearingMessage;
    if (message?.role === "toolResult") {
      spend(message.usage);
      continue;
    }
    if (message?.role !== "assistant") continue;
    spend(message.usage);
    // `content` is a plain string for a text-only answer; only the block form
    // can carry a tool call.
    if (!Array.isArray(message.content)) continue;
    for (const block of message.content as readonly ContentBlock[]) {
      if (block?.type === "toolCall") toolCalls += 1;
    }
  }
  return { cost, toolCalls };
};

/** Anything that reports what it cost — an entry or a message. */
type UsageBearing = { usage?: { cost?: { total?: number } } };

/** The message shape `deriveSessionUsage` reads, and nothing more. */
type UsageBearingMessage = (UsageBearing & {
  role?: string;
  content?: unknown;
}) | null;

type ContentBlock = { type?: string } | null;

cases.old_string:
// A message added outside a run — an extension's, say — never reaches a
// settle boundary, so its id would never be published. Pi writes the entry
// immediately after this event, so the ids are read once that has happened.
if (event.type === "message_end" && !record.openRun) {
  queueMicrotask(() => {
    if (!this.records.has(record.threadId)) return;
    this.emit(record, {
      type: "entry_ids",
      entryIds: this.liveTranscriptOf(record).entryIds,
    });
  });
}

