/// Provider-native tool names mapped to shared canonical names.
///
/// Ported from `TOOL_NAME_ALIASES` in `src/chats/registry.py`. Kept beside
/// `tool_schema` because both are the same registry, and both the tool filter and
/// provider decoding read from it — one table, not a copy each.
const TOOL_NAME_ALIASES: &[(&str, &[(&str, &str)])] = &[
    (
        "pi",
        &[
            ("bash", "Bash"),
            ("read", "Read"),
            ("write", "Write"),
            ("edit", "Edit"),
            ("grep", "Grep"),
            ("glob", "Glob"),
            ("task", "Task"),
            ("webfetch", "WebFetch"),
            ("websearch", "WebSearch"),
        ],
    ),
    (
        "codex",
        &[
            ("apply_patch", "Patch"),
            ("exec_command", "Bash"),
            ("exec", "Bash"),
            ("shell", "Bash"),
            ("shell_command", "Bash"),
        ],
    ),
];

/// Map any provider-native filter name to its shared canonical name.
///
/// Python flattens every provider's aliases into one lookup, so a filter name is
/// matched regardless of which provider owns it.
///
/// ```
/// use _native::model::normalize_tool_filter_name;
/// assert_eq!(normalize_tool_filter_name("exec_command"), "Bash");
/// assert_eq!(normalize_tool_filter_name("Unknown"), "Unknown");
/// ```
pub fn normalize_tool_filter_name(name: &str) -> String {
    let lowered = name.to_lowercase();
    for (_provider, aliases) in TOOL_NAME_ALIASES {
        for (native, canonical) in *aliases {
            if *native == lowered {
                return (*canonical).to_string();
            }
        }
    }
    name.to_string()
}

/// Map a provider-native tool name to the canonical shared tool name.
///
/// ```
/// use _native::model::normalize_tool_name;
/// assert_eq!(normalize_tool_name("codex", Some("shell_command")), "Bash");
/// assert_eq!(normalize_tool_name("codex", None), "Unknown");
/// ```
pub fn normalize_tool_name(provider: &str, name: Option<&str>) -> String {
    let Some(name) = name.filter(|value| !value.is_empty()) else {
        return "Unknown".to_string();
    };
    let lowered = name.to_lowercase();
    for (candidate, aliases) in TOOL_NAME_ALIASES {
        if *candidate != provider {
            continue;
        }
        for (native, canonical) in *aliases {
            if *native == lowered {
                return (*canonical).to_string();
            }
        }
    }
    name.to_string()
}

