function counted(count: number, unit: string): string {
	return `${count} ${unit}${count === 1 ? "" : "s"}`;
}

/**
 * Elapsed-only relative time, one grammar across all tiers.
 * relativeTime(now - 20_000, now) === "just now"; relativeTime(now - 12 * 60_000, now) === "12m ago"; relativeTime(now - 5 * 86_400_000, now) === "5 days ago"
 */
export function relativeTime(epochMilliseconds: number, nowMilliseconds: number): string {
	const elapsed = Math.max(0, nowMilliseconds - epochMilliseconds);
	if (elapsed < MINUTE_MILLISECONDS) return "just now";
	if (elapsed < HOUR_MILLISECONDS) return `${Math.floor(elapsed / MINUTE_MILLISECONDS)}m ago`;
	const hours = Math.floor(elapsed / HOUR_MILLISECONDS);
	if (elapsed < 4 * HOUR_MILLISECONDS) {
		const minutes = Math.floor((elapsed % HOUR_MILLISECONDS) / MINUTE_MILLISECONDS);
		return `${hours}h ${String(minutes).padStart(2, "0")}m ago`;
	}
	if (elapsed < DAY_MILLISECONDS) return `${hours}h ago`;
	if (elapsed < 2 * DAY_MILLISECONDS) return `1d ${Math.floor((elapsed % DAY_MILLISECONDS) / HOUR_MILLISECONDS)}h ago`;
	if (elapsed < WEEK_MILLISECONDS) return `${counted(Math.floor(elapsed / DAY_MILLISECONDS), "day")} ago`;
	if (elapsed < MONTH_MILLISECONDS) return `${counted(Math.floor(elapsed / WEEK_MILLISECONDS), "week")} ago`;
	return `${counted(Math.floor(elapsed / MONTH_MILLISECONDS), "month")} ago`;
}

/**
 * futureTime(now + 20 * 86_400_000, now) === "in 2w"
 */
export function futureTime(epochMilliseconds: number, nowMilliseconds: number): string {
	const remaining = Math.max(0, epochMilliseconds - nowMilliseconds);
	if (remaining < HOUR_MILLISECONDS) return `in ${Math.max(1, Math.floor(remaining / MINUTE_MILLISECONDS))}m`;
	if (remaining < DAY_MILLISECONDS) return `in ${Math.floor(remaining / HOUR_MILLISECONDS)}h`;
	if (remaining < WEEK_MILLISECONDS) return `in ${Math.floor(remaining / DAY_MILLISECONDS)}d`;
