 * Admission is serial, so an addition inside an admission window is that
 * admission's prompt.
 *
 * Returns whether the growth was attributed to the admission, so the caller
 * can hold that one frame back: Pi announces the push BEFORE it answers the
 * preflight, and the host still owns the prompt until it does, so publishing
 * there would show it twice. The admission's resolution publishes the
 * settled queue a moment later.
 *
 * contract:: an extension must not queue its own message through
 * `pi.sendMessage` while a prompt is being admitted. The host cannot tell
 * that message from the one it is handing over, and would read the
 * extension's as the admission's. The cost is a mislabelled outcome — never
 * a lost prompt, because ownership is released by the admission itself and
 * not by this reading.
 */
private trackPiQueue(
  record: ThreadRecord,
  queue: { steering: readonly string[]; followUp: readonly string[] },
): boolean {
  const grew =
    queue.steering.length > record.piQueueSeen.steering ||
    queue.followUp.length > record.piQueueSeen.followUp;
  record.piQueueSeen = {
    steering: queue.steering.length,
    followUp: queue.followUp.length,
  };
  if (!grew || !record.admittingSend) return false;
  record.admittingSend.takenByPi = true;
  return true;
}

cases.new_string:
 * Admission is serial, and only the lane the host HANDED Pi can be this
 * prompt: Pi queues into the lane it was given and throws on a lane-less
 * prompt into a live run, so growth anywhere else is somebody else's. That
 * is what the verifier's trace was — an extension steering while the host
 * was handing over a follow-up, read as Pi taking the follow-up.
 *
 * contract:: an extension must not queue its own message (`sendUserMessage`,
 * `sendMessage`) into THAT lane while a prompt is being admitted. Nothing
 * distinguishes the two, and the host reads the extension's as the
 * admission's. The cost is a mislabelled outcome, never a lost prompt: the
 * queue holds an owned prompt until its admission resolves, whatever this
 * reading says (see `queueOf`).
 */
private trackPiQueue(
  record: ThreadRecord,
  queue: { steering: readonly string[]; followUp: readonly string[] },
): void {
  const admitting = record.admittingSend;
  const grewInLane =
    (admitting?.laneGivenToPi === "steer" &&
      queue.steering.length > record.piQueueSeen.steering) ||
    (admitting?.laneGivenToPi === "followUp" &&
      queue.followUp.length > record.piQueueSeen.followUp);
  record.piQueueSeen = {
    steering: queue.steering.length,
    followUp: queue.followUp.length,
  };
  if (grewInLane && admitting) admitting.takenByPi = true;
}

