it("owes one settlement per run, and stays busy until every one arrives", async () => {
  // Pi runs one `_runAgentPrompt` per LOGICAL run and emits exactly one
  // `agent_settled` for it, after a hook it awaits. `isStreaming` goes
  // false at the START of that hook, so a prompt whose own input hook
  // outlasts the run that was going is started as a SECOND run inside the
  // first one's settled hook. The host folded the two into one generation,
  // the older settlement then cleared it, and the gate called a live run
  // idle — long enough for the next check to send into it.
  const t = await openForSends();
  t.emit({ type: "agent_start" });
  t.session.isStreaming = true;
  t.emit({ type: "message_start" });

  // R0 stops streaming and waits in its settled hook.
  t.session.isStreaming = false;
  t.emit({ type: "agent_end", willRetry: false });

  // A leaves its input hook in that window, so Pi starts it as a new run.
  t.session.isStreaming = true;
