/**
 * The real path of `target`, but only when it really is inside `root`.
 *
 * `threadScopedPath` proves a path is LEXICALLY under its root, and that is a
 * statement about a string. The directory it names can itself be a link the
 * agent planted, and every later check then measures against wherever that
 * link landed — a `realpath` of a file under an escaped root faithfully
 * contains it inside the escape. So a root is resolved and contained before
 * anything is willing to treat it as a root.
 *
 * BOTH sides are resolved. A configured root is very often a link itself
 * (`/tmp` is `/private/tmp` on macOS), and comparing a real path against a raw
 * one would refuse every legitimate desk there.
 */
export const realPathWithin = (root: string, target: string): string | null => {
  let realRoot: string;
  let real: string;
  try {
    realRoot = fs.realpathSync(path.resolve(root));
    real = fs.realpathSync(path.resolve(target));
  } catch {
    return null;
  }
  return real === realRoot || real.startsWith(realRoot + path.sep)
    ? real
    : null;
};

