 * artifact root, and a `feedback` directory aliased to the sidecar root lands
 * on the sidecar root — so `owners`, a perfectly valid thread id, names
 * `owners.jsonl`. Every membership test passes both while the caller lists,
 * serves, appends to and deletes what belongs to someone else.
 *
 * So the PARENT is resolved first, and its child must then resolve to itself.
 * Resolving the parent is what keeps a real deployment working, because a
 * configured root is very often a link (`/tmp` is `/private/tmp` on macOS);
 * requiring the child to resolve to itself is what makes the answer the
 * requested child rather than merely a path in the neighbourhood.
 *
 * `threadScopedPath` is what makes the join a child and not a climb: it throws
 * for any name that is not one segment.
 */
export const realChildOf = (root: string, name: string): string | null => {
  let realRoot: string;
  try {
    realRoot = fs.realpathSync(path.resolve(root));
  } catch {
    return null;
  }
  const child = threadScopedPath(realRoot, name);
  try {
    return fs.realpathSync(child) === child ? child : null;
  } catch {
    return null;
  }
};

