/**
 * Whether Pi would EXECUTE this text as a command rather than answer it.
 *
 * Parsed the way Pi parses it — the first token after the slash — and answered
 * from Pi's own list rather than guessed from the shape of the text, so a
 * question that merely starts with a slash is still a question.
 *
 * >>> namesCommand([{ name: "compact", description: "", source: "prompt" }], "/compact now")
 * true
 * >>> namesCommand([{ name: "compact", description: "", source: "prompt" }], "/how much did we sell")
 * false
 */
export const namesCommand = (
  commands: readonly CommandInfo[],
  text: string,
): boolean => {
  const trimmed = text.trimStart();
  if (!trimmed.startsWith("/")) return false;
  const name = trimmed.slice(1).split(/\s/)[0];
  return commands.some((command) => command.name === name);
};

/**
 * Whether to block a chat's FIRST message.
 *
 * Fails CLOSED. Until discovery answers, an empty command list means "unknown",
 * not "there are none" — so anything SHAPED like a command is treated as one,
 * and the window before the fetch lands (or after it fails) cannot let a real
 * command reach `createThread`. A question is unaffected either way, because a
 * question does not start with a slash.
 *
 * >>> blockFirstMessage([], "loading", "/noop")
 * true
 * >>> blockFirstMessage([], "loading", "how many customers churned")
 * false
 */
export const blockFirstMessage = (
  commands: readonly CommandInfo[],
  discovery: "loading" | "ready" | "failed",
  text: string,
): boolean =>
  discovery === "ready"
    ? namesCommand(commands, text)
    : text.trimStart().startsWith("/");

