import { api } from "@/lib/api";
import { blockFirstMessage, type CommandInfo } from "@/lib/commands";

/**
 * The commands Pi would accept in this workspace, fetched once.
 *
 * Two readers need the same list and neither can pass it to the other: the
 * composer's `/` menu is deep inside the thread, and the first-message rule
 * below is decided beside the runtime.
 */
type CommandsState = {
  commands: readonly CommandInfo[];
  /** Whether the list can be trusted yet. An empty list while `loading` or
   * `failed` means "unknown", not "there are none" — and the first-message rule
   * below has to tell those apart, or it fails OPEN in exactly the window
   * before the fetch answers. */
  discovery: "loading" | "ready" | "failed";
};

const EMPTY: CommandsState = { commands: [], discovery: "loading" };

const CommandsContext = createContext<CommandsState>(EMPTY);

export const PiCommandsProvider: FC<{ children: ReactNode }> = ({
  children,
}) => {
  const [state, setState] = useState<CommandsState>(EMPTY);
  useEffect(() => {
    let current = true;
    void api
      .listCommands()
      .then((commands) => {
        if (current) setState({ commands, discovery: "ready" });
      })
      .catch(() => {
        if (current) setState({ commands: [], discovery: "failed" });
      });
    return () => {
      current = false;
    };
  }, []);
  return (
    <CommandsContext.Provider value={state}>
      {children}
    </CommandsContext.Provider>
  );
};

export const usePiCommandsState = (): CommandsState =>
  useContext(CommandsContext);

export const usePiCommands = (): readonly CommandInfo[] =>
  useContext(CommandsContext).commands;

/**
 * A command cannot be a thread's FIRST message.
 *
 * `createThread` does not answer until the message it carries has been
 * admitted, so the thread has no id while Pi is holding the prompt — and a
 * command that raises a dialog would then be waiting on a client that cannot
 * subscribe to it, forever. Nothing here can tell an interactive command from
 * a quiet one, so all of them are excluded from that one position.
 *
 * The verdict is lifted to `isSendDisabled` rather than applied at the Send
 * button, because Enter sends too. The SERVER refuses the same thing on
 * `createThread`, and that is the authoritative half — this one exists so the
 * user is told before the send rather than after it.
 */
export const useFirstMessageCommandBlock = (
  threadId: string | undefined,
): boolean => {
  const { commands, discovery } = usePiCommandsState();
  const text = useAuiState((s) => s.composer.text);
  if (threadId) return false;
  return blockFirstMessage(commands, discovery, text);
};

