const json = async <T>(response: Response): Promise<T> => {
  if (!response.ok)
    throw new Error(`${response.status} ${response.statusText}`);
  return (await response.json()) as T;
};

/**
 * The sentence a refused request carried, out of the error the adapter's HTTP
 * client raised for it.
 *
 * That client builds ONE message per failed request and it is operator-shaped:
 * a status line, then the response body verbatim. Every route in this app
 * answers `{ "error": … }`, so the reason a reader needs is in there, it is the
 * only prose in there, and lifting it out is what turns a status dump into
 * something the user can act on. A failure with no such body — a dropped
 * connection, a crash — has no reason to offer and says so.
 *
 * >>> serverReason(new Error('Pi HTTP request failed: 400 Bad Request — {"error":"nope"}'))
 * "nope"
 * >>> serverReason(new Error("Failed to fetch"))
 * undefined
 */
export const serverReason = (error: unknown): string | undefined => {
  const message = error instanceof Error ? error.message : String(error);
  const start = message.indexOf("{");
  if (start === -1) return undefined;
  try {
    const body = JSON.parse(message.slice(start)) as { error?: unknown };
    return typeof body.error === "string" && body.error ? body.error : undefined;
  } catch {
    return undefined;
  }
};

