 * The real path of one desk file, or `null` when it is not one. The whole
 * symlink chain is resolved before the containment check, so neither traversal
 * nor a planted link can name a file outside the desk.
 */
export const resolveDeskFile = (
  threadId: string,
  relativePath: string,
): string | null => {
  const relative = relativePath.replace(/^\/+/, "");
  if (!relative) return null;
  let root: string;
  let real: string;
  let stat: fs.Stats;
  try {
    // `ensureDesk` answers with a root already proven to be inside the
    // artifacts directory, so this containment check measures against the
    // configured root rather than against wherever a linked desk pointed.
    root = ensureDesk(threadId);
    real = fs.realpathSync(path.resolve(root, relative));
    stat = fs.statSync(real);
  } catch {
    return null;
  }
  if (real !== root && !real.startsWith(root + path.sep)) return null;
  return stat.isFile() ? real : null;
};

cases.new_string:
/**
 * The real path of one desk file, or `null` when it is not one. The whole
 * symlink chain is resolved before the containment check, so neither traversal
 * nor a planted link can name a file outside the desk.
 *
 * Reading never CREATES. This used to open the desk through `ensureDesk`, so a
 * download for a file that is not there left an empty directory behind and
 * then answered 404 — a desk belonging to no chat, made by a stranger's URL.
 */
export const resolveDeskFile = (
  threadId: string,
  relativePath: string,
): string | null => {
  const relative = relativePath.replace(/^\/+/, "");
  if (!relative) return null;
  const root = deskRoot(threadId);
  if (!root) return null;
  let real: string;
  let stat: fs.Stats;
  try {
    real = fs.realpathSync(path.resolve(root, relative));
    stat = fs.statSync(real);
  } catch {
    return null;
  }
  if (real !== root && !real.startsWith(root + path.sep)) return null;
  return stat.isFile() && isSoleName(stat) ? real : null;
};

