// Align a chassis up-axis with the ground normal rebuilt from the pitch/roll
// slopes — one plane alignment, so all four wheels sit flush even when pitch and
// roll are large at once (independent Euler hinges drift apart there). Pure
// tilt, shortest-arc, in the already-yawed frame. Rivals conform with this too.
export function setSurfaceTilt(quaternion, pitch, roll) {
  surfaceNormal.set(-Math.tan(roll), 1, Math.tan(pitch)).normalize();
  quaternion.setFromUnitVectors(CAR_UP, surfaceNormal);
}

