function placeRival(rival, dt, lateralRate) {
  const pose = COURSE.sampleAt(rival.distanceAlong);
  const x = pose.x + pose.normalX * rival.lateral;
  const z = pose.z + pose.normalZ * rival.lateral;

  // The course normal points to the driver's right, and turning right lowers the
  // heading, so drifting right (a positive lateral rate) subtracts from it. Without
  // this a rival running wide keeps pointing straight ahead and crabs sideways.
  const yawIntoDrift = THREE.MathUtils.clamp(
    Math.atan2(lateralRate, Math.max(Math.abs(rival.speed), 1)),
    -RACE.mistakeYawMax,
    RACE.mistakeYawMax,
  );

  rival.carRig.position.set(x, surfaceHeightAt(x, z) + CAR_Y, z);
  rival.heading = dampAngle(rival.heading, pose.heading - yawIntoDrift, RACE.headingDamp, dt);
  rival.carRig.rotation.y = rival.heading;

