// One curve drives the whole mistake: the rival drifts wide and gives back
// ground at the same time, because the wide line is the longer line, and both
// return to nothing as it recovers.
function driftAmount(rival) {
  if (rival.mistakeSecondsLeft <= 0) return 0;
  return Math.sin((1 - rival.mistakeSecondsLeft / RACE.mistakeSeconds) * Math.PI);
}

// Corners are what a rival gets wrong, so it reads the bend it is about to drive
// and errs only where there is a real one. Between mistakes it rests, so a
// corner sequence does not turn into one continuous flail.
function updateMistake(rival, dt) {
  rival.mistakeRest -= dt;
  if (rival.mistakeSecondsLeft > 0) {
    rival.mistakeSecondsLeft -= dt;
    return;
  }
  if (rival.mistakeRest > 0) return;
  if (Math.abs(COURSE.curvatureAt(rival.distanceAlong + RACE.cornerLookAhead)) < RACE.cornerCurvature) return;

  rival.mistakeSecondsLeft = RACE.mistakeSeconds;
  rival.mistakeRest = RACE.mistakeSeconds + RACE.mistakeRest;
}

function updateRival(rival, dt, elapsedTime, playerDistanceAlong) {
  updateMistake(rival, dt);
  const drift = driftAmount(rival);
  const gap = THREE.MathUtils.lerp(-RACE.gapBehind, RACE.gapAhead, surgeAmount(rival, elapsedTime));
  const target = clampToPhotoFinish(playerDistanceAlong + gap - drift * RACE.mistakeCost, playerDistanceAlong);
  const previousDistance = rival.distanceAlong;
  const previousLateral = rival.lateral;

  rival.distanceAlong = THREE.MathUtils.damp(rival.distanceAlong, target, RACE.gapDamp, dt);
  rival.speed = (rival.distanceAlong - previousDistance) / dt;
  rival.gap = rival.distanceAlong - playerDistanceAlong;
  // The drift always carries the rival further out from its own lane, never
  // across the player's. That keeps "never share a piece of road" exact while
  // still reading as a truck that took the corner too wide and lost ground.
  rival.lateral = rival.lane + drift * Math.sign(rival.lane) * RACE.mistakeWidth;

  // No course behind the start line and none past the finish, so there is
  // nowhere for a rival to be. Hide rather than pile up on the clamped end.
  rival.carRig.visible = rival.distanceAlong > 0 && rival.distanceAlong < COURSE.length;
  if (rival.carRig.visible) placeRival(rival, dt, (rival.lateral - previousLateral) / dt);
}

