function driftStarts(rival) {
  return rival.filter((frame, step) => frame.drifting && !(step > 0 && rival[step - 1].drifting));
}

// The mistake has to be a corner mistake. A rival running wide on a dead
// straight does not read as a driver erring, it reads as a broken rival. Only
// where it starts matters: once it starts, it plays out past the corner, which
// is what a car that ran wide actually does.
test('a rival only starts running wide where the course bends', () => {
  const history = runRace(() => 40 / 3, { seconds: 240, startAt: 0 });
  const starts = history.flatMap(driftStarts);

  for (const start of starts) {
    const bend = Math.abs(COURSE.curvatureAt(start.distanceAlong + RACE.cornerLookAhead));
    assert.ok(
      bend >= RACE.cornerCurvature,
      `a rival started running wide at ${start.distanceAlong.toFixed(0)}m, where the bend is only ${bend.toFixed(4)} rad/m`,
    );
  }

  assert.ok(starts.length > 0, 'no rival ran wide at all over four minutes of course');
});

