// mistaken for the mistake.
test('running wide costs a rival ground', () => {
  const withCost = runRace(() => 40 / 3, { seconds: 240, startAt: 0 });
  const realCost = RACE.mistakeCost;
  RACE.mistakeCost = 0;
  const withoutCost = runRace(() => 40 / 3, { seconds: 240, startAt: 0 });
  RACE.mistakeCost = realCost;

  for (let index = 0; index < withCost.length; index++) {
    for (const start of driftStarts(withCost[index])) {
