// Any RACE number can be set from the URL: &race=mistakeSeconds:40,mistakeRest:0
// stretches one wide corner over 40 seconds so a screenshot lands mid-drift
// without chasing the timing. It is also how you try a tuning change without
// editing a file.
function applyRaceOverrides(spec) {
  for (const pair of spec.split(',')) {
    const [name, rawValue] = pair.split(':');
    const value = Number(rawValue);
    if (!(name in RACE)) throw new Error(`?race= names '${name}', which is not in RACE.`);
    if (!Number.isFinite(value)) throw new Error(`?race=${name}:${rawValue} is not a number.`);
    RACE[name] = value;
  }
}

