export function updateRivals(rivals, dt, elapsedTime, playerCoursePoint) {
  // Nothing moves in zero time, and every rate below divides by dt. The damped
  // heading and the wheel spin both accumulate onto their own previous value, so
  // one NaN from a zero-length frame would stick for the rest of the run and
  // blank the truck while leaving its position readable.
  if (dt <= 0) return;

  if (!playerCoursePoint) {
    for (const rival of rivals) rival.carRig.visible = false;
    return;
  }

// A zero-length frame really happens: the clock's first delta inside the loop
// can be zero. The heading and the wheel spin accumulate onto their own previous
// value, so a single NaN there sticks for the whole run and blanks the truck
// while its position keeps reading fine.
test('a zero-length frame leaves no rival with a NaN pose', () => {
  const rivals = [stubRival(0), stubRival(1)];
  updateRivals(rivals, 0, 0, { distanceAlong: 600 });
  updateRivals(rivals, 1 / 60, 1 / 60, { distanceAlong: 600 });

  for (const rival of rivals) {
    assert.ok(Number.isFinite(rival.heading), `rival ${rival.index} heading is ${rival.heading}`);
    assert.ok(Number.isFinite(rival.speed), `rival ${rival.index} speed is ${rival.speed}`);
    assert.ok(Number.isFinite(rival.carRig.rotation.y), `rival ${rival.index} yaw is ${rival.carRig.rotation.y}`);
    for (const wheel of rival.wheels) {
      assert.ok(Number.isFinite(wheel.rotation.x), `rival ${rival.index} has a NaN wheel`);
    }
  }
});

