# --- Segmented exams: the record page splits an exam into segments when iOS kills capture mid-exam. ---

EXAM_ID_PATTERN = re.compile(r"^[0-9]{14}x[a-z0-9]{4}$")
EXAM_RETENTION = timedelta(hours=6)
# Below this an AAC segment holds no speech (the encoder flush alone is ~1.5KB).
MIN_AUDIBLE_SEGMENT_BYTES = 2000


@dataclass
class ExamSegment:
    audio: bytes
    mime_type: str
    suffix: str
    gap_ms: int


@dataclass
class ExamState:
    received_at: datetime
    segments: dict[int, ExamSegment] = field(default_factory=dict)
    last_seq: int | None = None
    result: FindingsItem | None = None


exams: dict[str, ExamState] = {}


def require_exam_id(exam_id: str) -> None:
    if not EXAM_ID_PATTERN.fullmatch(exam_id):
        raise HTTPException(status_code=422, detail=f"Bad exam id: {exam_id}")


def prune_stale_exams() -> None:
    cutoff = datetime.now(UTC) - EXAM_RETENTION
    for exam_id in [exam_id for exam_id, exam in exams.items() if exam.received_at < cutoff]:
        del exams[exam_id]
        logger.info("exam %s pruned (older than %s)", exam_id, EXAM_RETENTION)


def try_process_exam(exam_id: str) -> FindingsItem | None:
    exam = exams[exam_id]
    if exam.result is not None:
        return exam.result
    if exam.last_seq is None or set(exam.segments) < set(range(exam.last_seq + 1)):
        return None

    ordered = [exam.segments[seq] for seq in range(exam.last_seq + 1)]
    audible = [segment for segment in ordered if len(segment.audio) >= MIN_AUDIBLE_SEGMENT_BYTES]
    if sum(len(segment.audio) for segment in audible) > MAX_UPLOAD_BYTES:
        raise HTTPException(status_code=413, detail="Exam too large for inline processing.")
    if audible:
        note = SEGMENTED_EXAM_NOTE.format(count=len(audible)) if len(audible) > 1 else ""
        extraction = extract_findings([(segment.audio, segment.mime_type) for segment in audible], note)
    else:
        extraction = ExamExtraction(transcript="", findings=[])

    gap_seconds = round(sum(segment.gap_ms for segment in ordered) / 1000, 1)
    created = datetime.now(UTC).isoformat(timespec="seconds")
    item = FindingsItem(
        id=exam_id, created=created, transcript=extraction.transcript,
        findings=extraction.findings, gap_seconds=gap_seconds,
    )
    exam.result = item
    logger.info("exam %s processed: %d segments, gap %.1fs, transcript: %s",
                exam_id, len(ordered), gap_seconds, item.transcript)
    logger.info("exam %s findings (%d): %s", exam_id, len(item.findings), item.findings)
    if MIRROR_URL:
        segments_meta = [
            {"seq": seq, "bytes": len(segment.audio), "gap_ms": segment.gap_ms}
            for seq, segment in enumerate(ordered)
        ]
        push_to_worker({"type": "exam", **item.model_dump(), "segments": segments_meta}, f"exam {exam_id}")
    if item.findings:
        unacked_items[exam_id] = item
        logger.info("exam %s queued for desktop", exam_id)
    else:
        logger.info("exam %s NOT queued: no findings", exam_id)
    return item


def processed_response(item: FindingsItem) -> dict[str, object]:
    return {"processed": True, "id": item.id, "findings": item.findings,
            "transcript": item.transcript, "gap_seconds": item.gap_seconds}


@api.post("/exams/{exam_id}/segments")
async def receive_segment(exam_id: str, file: UploadFile, seq: int = Form(), gap_ms: int = Form(0)) -> dict[str, object]:
    require_exam_id(exam_id)
    if not 0 <= seq <= 500:
        raise HTTPException(status_code=422, detail=f"Bad segment seq: {seq}")
    audio_bytes = await file.read()
    if len(audio_bytes) > MAX_UPLOAD_BYTES:
        raise HTTPException(status_code=413, detail="Segment too large for inline processing.")
    suffix = Path(file.filename or "segment.m4a").suffix.lower() or ".m4a"
    mime_type = MIME_TYPE_BY_SUFFIX.get(suffix)
    if mime_type is None:
        raise HTTPException(status_code=415, detail=f"Unsupported audio type: {suffix}")

    prune_stale_exams()
    exam = exams.setdefault(exam_id, ExamState(received_at=datetime.now(UTC)))
    exam.segments[seq] = ExamSegment(audio=audio_bytes, mime_type=mime_type, suffix=suffix, gap_ms=max(gap_ms, 0))
    logger.info("exam %s segment %d: %d bytes, gap_ms=%d", exam_id, seq, len(audio_bytes), gap_ms)
    if MIRROR_URL:
        payload = {
            "id": f"{exam_id}.s{seq}", "created": datetime.now(UTC).isoformat(timespec="seconds"),
            "transcript": "", "findings": [], "suffix": suffix,
            "audio_base64": base64.b64encode(audio_bytes).decode(),
        }
        push_to_worker(payload, f"exam {exam_id} segment {seq}")
    item = try_process_exam(exam_id)
    if item is not None:
        return processed_response(item)
    return {"processed": False, "stored": seq}


class FinishRequest(BaseModel):
    last_seq: int


@api.post("/exams/{exam_id}/finish")
def finish_exam(exam_id: str, request: FinishRequest) -> dict[str, object]:
    require_exam_id(exam_id)
    if not 0 <= request.last_seq <= 500:
        raise HTTPException(status_code=422, detail=f"Bad last_seq: {request.last_seq}")
    exam = exams.setdefault(exam_id, ExamState(received_at=datetime.now(UTC)))
    exam.last_seq = request.last_seq
    item = try_process_exam(exam_id)
    if item is not None:
        return processed_response(item)
    missing = sorted(set(range(request.last_seq + 1)) - set(exam.segments))
    logger.info("exam %s finish: waiting for segments %s", exam_id, missing)
    return {"processed": False, "missing_segments": missing}


class MistakeReport(BaseModel):
    id: str
    correction: str

