text = ", ".join(oldest.findings)
if oldest.gap_seconds >= 2:
    text = f"[שים לב: נתק בהקלטה, חסרות כ-{round(oldest.gap_seconds)} שניות] {text}"
payload = {"id": oldest.id, "created": oldest.created, "text": text}

