<meta name="viewport" content="width=device-width, initial-scale=1">
<title>הקלטת בדיקה</title>
<style>
  body { font-family: -apple-system, sans-serif; display: flex; flex-direction: column;
         align-items: center; gap: 24px; padding: 40px 20px; background: #f5f5f7; }
  #toggle { font-size: 28px; padding: 40px 48px; border-radius: 24px; border: none;
            background: #0a84ff; color: white; width: 100%; max-width: 400px; }
