  #result:empty, #fallback, #debug { display: none; }
  body.no-mic #fallback { display: block; }
  body.no-mic #toggle { display: none; }
  body.debug #debug { display: block; direction: ltr; text-align: left; width: 100%;
            max-width: 400px; background: #1c1c1e; color: #30d158; border-radius: 12px;
            padding: 12px; font: 11px ui-monospace, Menlo, monospace; }
  #debug-state { white-space: pre; border-bottom: 1px solid #3a3a3c; padding-bottom: 8px;
            margin-bottom: 8px; }
  #debug-log { white-space: pre-wrap; color: #98989d; max-height: 40vh; overflow-y: auto; }
</style>
</head>
<body>
<button id="toggle">התחל הקלטה</button>
<div id="fallback">
  <p>אין גישה למיקרופון בדפדפן. הקלט ב״הקלטות קוליות״ ובחר את הקובץ:</p>
  <input type="file" id="pick" accept="audio/*">
</div>
<p id="status"></p>
<div id="result"></div>
<div id="debug"><div id="debug-state"></div><div id="debug-log"></div></div>
<script>
const SECRET = "__SECRET__";
const DEBUG = new URLSearchParams(location.search).has("debug");
const DEAD_SILENCE_MS = 3000;      // this long of bit-exact zeros = capture is dead
const METER_INTERVAL_MS = 250;
const VERIFY_TIMEOUT_MS = 2000;    // a new capture must show live audio within this
const RECOVERY_BACKOFF_MS = [1000, 2000, 4000, 5000];

const toggle = document.getElementById("toggle");
const status = document.getElementById("status");
const result = document.getElementById("result");
const debugState = document.getElementById("debug-state");
const debugLog = document.getElementById("debug-log");
if (DEBUG) document.body.classList.add("debug");
if (!navigator.mediaDevices) document.body.classList.add("no-mic");

let audioContext = null;  // one per page; iOS allows creation only from a user gesture
let wakeLock = null;
let exam = null;          // the active exam session, or null
let capture = null;       // the live mic capture (stream+recorder+meter), or null
let tickerInterval = null;

const logLines = [];
function dlog(message) {
  logLines.push(new Date().toISOString().slice(11, 23) + " " + message);
  if (logLines.length > 60) logLines.shift();
  if (DEBUG) debugLog.textContent = logLines.slice().reverse().join("\\n");
}

function appState() {
  if (!exam) return "idle";
  if (exam.finished) return "sending";
  if (exam.recovering) return "RECOVERING";
  if (capture && capture.recorder.state === "recording") return "recording";
  return "transition";
}

function renderDebugState() {
  if (!DEBUG) return;
  const level = capture ? (capture.level > 0 ? (20 * Math.log10(capture.level)).toFixed(1) + "dB" : "ZERO") : "-";
  const lastLive = capture && capture.lastLiveAt ? ((Date.now() - capture.lastLiveAt) / 1000).toFixed(1) + "s ago" : "never";
  debugState.textContent = [
    "state: " + appState(),
    "exam: " + (exam ? exam.id + " seg=" + exam.seq : "-"),
    "recorder: " + (capture ? capture.recorder.state : "-") +
      "  track: " + (capture ? capture.track.readyState + " muted=" + capture.track.muted : "-"),
    "meter: " + level + "  lastLive: " + lastLive,
    "gaps: " + (exam ? (exam.gapTotalMs / 1000).toFixed(1) + "s" : "-") +
      "  uploading: " + (exam ? exam.uploading : 0) +
      "  wakeLock: " + (wakeLock ? "held" : "no"),
  ].join("\\n");
}

function sleep(ms) { return new Promise((resolve) => setTimeout(resolve, ms)); }

function makeExamId() {
  return new Date().toISOString().replace(/[^0-9]/g, "").slice(0, 14) + "x" +
         Math.random().toString(36).slice(2, 6).padEnd(4, "0");
}

async function ensureAudioContext() {
  if (!audioContext) audioContext = new (window.AudioContext || window.webkitAudioContext)();
  if (audioContext.state !== "running") {
    try { await audioContext.resume(); } catch (error) { dlog("audioContext resume failed: " + error.message); }
  }
}

// Acquire mic + recorder + level meter, and only count it live once real audio flows.
// The meter is both the silent-death detector and the recovery verifier: a live mic
// always shows a noise floor; bit-exact zero means iOS took the capture away.
async function openCapture(gapStartAt) {
  const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
  const track = stream.getAudioTracks()[0];
  await ensureAudioContext();
  const source = audioContext.createMediaStreamSource(stream);
  const analyser = audioContext.createAnalyser();
  analyser.fftSize = 2048;
  source.connect(analyser);
  const mimeType = MediaRecorder.isTypeSupported("audio/mp4") ? "audio/mp4" : "audio/webm";
  const recorder = new MediaRecorder(stream, { mimeType });
  const cap = { stream, track, source, analyser, recorder, mimeType, exam,
                chunks: [], seq: undefined, gapMsBefore: 0, level: 0, lastLiveAt: null,
                deadHandled: false, userStopped: false, discarded: false, meterTimer: null };
  recorder.ondataavailable = (event) => cap.chunks.push(event.data);
  recorder.onstop = () => onRecorderStop(cap);
  track.onended = () => { dlog("EVENT track ended"); captureDead(cap, "track-ended"); };
  track.onmute = () => dlog("EVENT track mute");
  track.onunmute = () => dlog("EVENT track unmute");
  const buffer = new Float32Array(analyser.fftSize);
  cap.meterTimer = setInterval(() => {
    analyser.getFloatTimeDomainData(buffer);
    let max = 0;
    for (let i = 0; i < buffer.length; i++) { const a = Math.abs(buffer[i]); if (a > max) max = a; }
    cap.level = max;
    if (max > 0) cap.lastLiveAt = Date.now();
    else if (cap.lastLiveAt && Date.now() - cap.lastLiveAt > DEAD_SILENCE_MS) {
      captureDead(cap, "silent-" + DEAD_SILENCE_MS + "ms");
    }
    renderDebugState();
  }, METER_INTERVAL_MS);
  recorder.start();

  const verifyStart = Date.now();
  while (cap.lastLiveAt === null && Date.now() - verifyStart < VERIFY_TIMEOUT_MS) await sleep(100);
  if (cap.lastLiveAt === null) {
    cap.discarded = true;
    closeCapture(cap);
    throw new Error("mic delivers only silence");
  }
  exam.seq += 1;
  cap.seq = exam.seq;
  cap.gapMsBefore = gapStartAt ? Date.now() - gapStartAt : 0;
  exam.gapTotalMs += cap.gapMsBefore;
  capture = cap;
  dlog("segment " + cap.seq + " LIVE (gap before: " + Math.round(cap.gapMsBefore) + "ms)");
  return cap;
}

function closeCapture(cap) {
  clearInterval(cap.meterTimer);
  cap.track.onended = cap.track.onmute = cap.track.onunmute = null;
  cap.stream.getTracks().forEach((track) => track.stop());
  try { cap.source.disconnect(); } catch (error) {}
  if (cap.recorder.state !== "inactive") cap.recorder.stop();
}

function onRecorderStop(cap) {
  clearInterval(cap.meterTimer);
  if (cap.discarded || cap.seq === undefined) { dlog("capture discarded before going live"); return; }
  uploadSegment(cap, new Blob(cap.chunks, { type: cap.mimeType }));
  if (!cap.userStopped) captureDead(cap, "unexpected-recorder-stop");
}

function captureDead(cap, reason) {
  if (cap.deadHandled || cap.userStopped || cap.discarded) return;
  cap.deadHandled = true;
  dlog("CAPTURE DEAD (" + reason + ") seg=" + (cap.seq === undefined ? "unverified" : cap.seq));
  closeCapture(cap);
  if (cap.seq === undefined) return;  // died during verify: the recovery loop's retry handles it
  if (capture === cap) capture = null;
  const silentSince = reason.indexOf("silent") === 0 && cap.lastLiveAt ? cap.lastLiveAt : Date.now();
  if (!cap.exam.gapStartAt) cap.exam.gapStartAt = silentSince;
  if (!cap.exam.stopping) recoveryLoop();
  updateUi();
}

async function recoveryLoop() {
  if (!exam || exam.recovering || exam.stopping) return;
  exam.recovering = true;
  updateUi();
  let attempt = 0;
  while (exam && !exam.stopping) {
    try {
      await openCapture(exam.gapStartAt);
      exam.gapStartAt = null;
      exam.recovering = false;
      dlog("RECOVERED into segment " + exam.seq);
      updateUi();
      return;
    } catch (error) {
      attempt += 1;
      dlog("recovery attempt " + attempt + " failed: " + error.message);
      await sleep(RECOVERY_BACKOFF_MS[Math.min(attempt - 1, RECOVERY_BACKOFF_MS.length - 1)]);
    }
  }
  if (exam) exam.recovering = false;
}

async function uploadSegment(cap, blob) {
  const current = cap.exam;
  current.uploading += 1;
  const extension = cap.mimeType === "audio/mp4" ? "m4a" : "webm";
  const form = new FormData();
  form.append("file", blob, "seg" + cap.seq + "." + extension);
  form.append("seq", String(cap.seq));
  form.append("gap_ms", String(Math.round(cap.gapMsBefore)));
  let attempt = 0;
  while (true) {
    try {
      const response = await fetch("/exams/" + current.id + "/segments",
        { method: "POST", headers: { "X-Auth-Secret": SECRET }, body: form });
      if (response.status >= 400 && response.status < 500) {
        current.failedSegments.push(cap.seq);
        dlog("segment " + cap.seq + " REJECTED: HTTP " + response.status);
        break;
      }
      if (!response.ok) throw new Error("HTTP " + response.status);
      dlog("segment " + cap.seq + " uploaded (" + blob.size + " bytes)");
      break;
    } catch (error) {
      attempt += 1;
      dlog("segment " + cap.seq + " upload attempt " + attempt + " failed: " + error.message);
      await sleep(Math.min(2000 * attempt, 5000));
    }
  }
  current.uploading -= 1;
  renderDebugState();
}

async function startExam() {
  exam = { id: makeExamId(), seq: -1, stopping: false, recovering: false, finished: false,
           startedAt: Date.now(), gapTotalMs: 0, gapStartAt: null, uploading: 0, failedSegments: [] };
  result.textContent = "";
  dlog("=== exam " + exam.id + " started ===");
  try {
    await openCapture(null);
  } catch (error) {
    dlog("start failed: " + error.message);
    exam = null;
    status.className = "";
    status.textContent = "יש לאפשר גישה למיקרופון בהגדרות הטלפון.";
    return;
  }
  try { wakeLock = await navigator.wakeLock.request("screen"); } catch (error) { wakeLock = null; }
  toggle.disabled = true;  // absorb an accidental double-tap
  setTimeout(() => { toggle.disabled = false; }, 800);
  tickerInterval = setInterval(tick, 500);
  tick();
  updateUi();
}

async function stopExam() {
  const current = exam;
  current.stopping = true;
  dlog("=== stop pressed, last segment seq=" + current.seq + " ===");
  if (capture) { capture.userStopped = true; closeCapture(capture); capture = null; }
  clearInterval(tickerInterval);
  current.finished = true;
  updateUi();
  await finishExam(current);
}

async function finishExam(current) {
  toggle.disabled = true;
  status.className = "";
  status.textContent = "מעבד...";
  while (true) {
    if (current.failedSegments.length) {
      status.textContent = "שגיאה: קטע הקלטה נדחה על ידי השרת (" + current.failedSegments.join(", ") + ")";
      break;
    }
    try {
      const response = await fetch("/exams/" + current.id + "/finish", {
        method: "POST",
        headers: { "X-Auth-Secret": SECRET, "Content-Type": "application/json" },
        body: JSON.stringify({ last_seq: current.seq }),
      });
      if (!response.ok) throw new Error("HTTP " + response.status);
      const data = await response.json();
      if (data.processed) { showResult(current, data); break; }
      dlog("finish: server still waiting for segments " + JSON.stringify(data.missing_segments));
    } catch (error) {
      dlog("finish attempt failed: " + error.message);
      status.textContent = "השליחה נכשלה. מנסה שוב...";
    }
    await sleep(2000);
  }
  toggle.disabled = false;
  if (wakeLock) { wakeLock.release(); wakeLock = null; }
  exam = null;
  updateUi();
}

function showResult(current, data) {
  status.className = "";
  let header = "";
  if (data.gap_seconds >= 2) {
    header = "שים לב: היו נתקים בהקלטה, חסרות כ-" + Math.round(data.gap_seconds) + " שניות.\\n\\n";
  }
  if (data.findings.length) {
    status.textContent = "הממצאים נשלחו למחשב:";
    result.textContent = header + data.findings.join("\\n");
  } else {
    status.textContent = "לא זוהו ממצאים רפואיים. התמלול:";
    result.textContent = header + data.transcript;
  }
  dlog("exam processed: " + data.findings.length + " findings, gap " + data.gap_seconds + "s");
}

function tick() {
  if (!exam || exam.finished) return;
  const seconds = Math.floor((Date.now() - exam.startedAt) / 1000);
  const clock = String(Math.floor(seconds / 60)).padStart(2, "0") + ":" + String(seconds % 60).padStart(2, "0");
  if (exam.recovering) {
    status.className = "warning";
    status.textContent = "המיקרופון נותק - מתחבר מחדש... " + clock;
  } else if (capture && capture.lastLiveAt && Date.now() - capture.lastLiveAt < 1500) {
    status.className = "";
    status.textContent = "מקליט... " + clock;
  } else {
    status.className = "warning";
    status.textContent = "לא נקלט קול... " + clock;
  }
  renderDebugState();
}

function updateUi() {
  if (!exam) {
    toggle.textContent = "התחל הקלטה";
    toggle.classList.remove("recording");
  } else if (exam.finished) {
    toggle.textContent = "שולח...";
    toggle.classList.remove("recording");
  } else {
    toggle.textContent = "עצור ושלח";
    toggle.classList.add("recording");
  }
  renderDebugState();
}

toggle.onclick = () => {
  if (!exam) { startExam(); return; }
  if (!exam.finished) stopExam();
};

document.addEventListener("visibilitychange", async () => {
  dlog("EVENT visibility: " + document.visibilityState);
  if (document.visibilityState !== "visible" || !exam || exam.stopping) return;
  if (!wakeLock) { try { wakeLock = await navigator.wakeLock.request("screen"); } catch (error) {} }
  if (capture && (capture.track.readyState === "ended" || capture.recorder.state !== "recording")) {
    captureDead(capture, "visibility-check");
  } else if (!capture && !exam.recovering) {
    recoveryLoop();
  }
});

document.getElementById("pick").onchange = (event) => {
  const file = event.target.files[0];
  if (file) uploadWholeFile(file, file.name);
};

// Fallback path (no-mic browsers): one whole file to the v1 endpoint.
async function uploadWholeFile(blob, filename) {
  toggle.disabled = true;
  status.className = "";
  status.textContent = "מעבד...";
  const form = new FormData();
  form.append("file", blob, filename);
  try {
    const response = await fetch("/recordings",
      { method: "POST", headers: { "X-Auth-Secret": SECRET }, body: form });
    if (!response.ok) throw new Error(await response.text());
    const data = await response.json();
    showResult(null, { findings: data.findings, transcript: data.transcript, gap_seconds: 0 });
  } catch (error) {
    status.textContent = "השליחה נכשלה: " + error.message;
  } finally {
    toggle.disabled = false;
  }
}
</script>
</body>
</html>
