// hook, where Pi is not streaming and `sendUserMessage` starts a NEW run the
// host never admitted.
pi.registerCommand("spawn", {
  description: "Waits, then sends a user message of its own",
  handler: async () => {
    const ms = delayOf("PI_SPAWN_DELAY_MS");
    if (ms > 0) await sleep(ms);
    // Fire and forget, which is what makes the run invisible: awaiting it
    // would keep the command's own admission open for the whole run, and
    // the host holds the gate shut for an admission. No `deliverAs`, so
    // mid-stream this throws (Pi refuses a lane-less prompt into a live
    // run) and outside a run it starts one.
    void pi.sendUserMessage("spawned by the command");
  },
});

