// A command that starts LLM WORK, which is a shape Pi documents. Pi runs a
// registered command immediately, even mid-stream, so a handler that waits
// resumes wherever the thread has got to by then — and
// `PI_SPAWN_DELAY_MS` long enough puts that inside the older run's settled
// hook, where Pi is not streaming and `sendUserMessage` starts a NEW run the
// host never admitted.
//
// With no delay the handler runs while Pi is STILL STREAMING, which is where
// the lane decides everything. `PI_SPAWN_DELIVER` says what the handler
// passes: "steer" or "followUp" is queued into the live run, and anything
// else — "bare", or no value at all — is sent without a lane, which Pi
// refuses mid-stream and turns into a run of its own when idle.
pi.registerCommand("spawn", {
  description: "Waits, then sends a user message of its own",
  handler: async () => {
    const ms = delayOf("PI_SPAWN_DELAY_MS");
    if (ms > 0) await sleep(ms);
    const lane = process.env.PI_SPAWN_DELIVER;
    // Fire and forget, which is what makes the run invisible: awaiting it
    // would keep the command's own admission open for the whole run, and
    // the host holds the gate shut for an admission.
    pi.sendUserMessage(
      "spawned by the command",
      lane === "steer" || lane === "followUp" ? { deliverAs: lane } : undefined,
    );
  },
});

