/**
 * CONTRACT 2 — QUEUE / CONTROL. What a prompt must do to be accepted.
 *
 * Read by: `sendMessage`. Three answers, because Pi has three states:
 * - `queue`   — Pi is streaming, so the prompt needs a lane or Pi rejects it.
 * - `hold`    — Pi is not streaming but a run is still settling. A lane does
 *               NOT queue here: Pi would start the prompt as a second,
 *               overlapping run. The host waits for the boundary instead.
 * - `send-now`— nothing is in flight.
 */
export type PiSendDisposition = "send-now" | "queue" | "hold";

const sendDisposition = (record: ThreadRecord): PiSendDisposition => {
  if (record.session.isStreaming) return "queue";
  return record.generations.length > 0 ? "hold" : "send-now";
};

/**
 * CONTRACT 3 — HOST BUSY. Whether restarting would interrupt work.
 *
 * Read by: the deploy gate, through `getRunningThreadCount()`. The union of
 * every state a restart would cut, which is deliberately wider than either
 * contract above: Pi streaming (this covers the awaited `agent_start` hook,
 * where Pi is already streaming and no run has been announced), any run not
 * yet settled (this covers the awaited settled hook, where Pi is no longer
 * streaming), compaction of every kind — manual, pre-prompt and overflow —
 * and a retry backoff.
 *
 * Never derived from CONTRACT 1. A manual compaction has no active group and
 * must still hold the gate shut.
 */
const hostIsBusy = (record: ThreadRecord): boolean => {
  const session = record.session;
  return (
    session.isStreaming ||
    session.isCompacting ||
    session.isRetrying ||
    record.generations.length > 0
  );
};

cases.new_string:
/**
 * CONTRACT 2 — QUEUE / CONTROL. What a prompt must do to be accepted.
 *
 * Read by the admission loop, once per prompt, at the moment it hands that
 * prompt to Pi — never by the caller, whose thread may have moved on since.
 * Three answers, because Pi has three states:
 * - `queue`   — Pi is streaming, so the prompt needs a lane or Pi rejects it.
 * - `hold`    — Pi is not streaming and still cannot take a prompt. A lane does
 *               NOT queue here: after a run Pi would start the prompt as a
 *               second, overlapping run, and during a compaction it throws
 *               outright. The host keeps the prompt in its own queue and waits.
 * - `send-now`— nothing is in flight.
 */
export type PiSendDisposition = "send-now" | "queue" | "hold";

const sendDisposition = (record: ThreadRecord): PiSendDisposition => {
  if (record.session.isStreaming) return "queue";
  if (record.session.isCompacting) return "hold";
  return record.generations.length > 0 ? "hold" : "send-now";
};

/**
 * CONTRACT 3 — HOST BUSY. Whether restarting would interrupt work.
 *
 * Read by: the deploy gate, through `getRunningThreadCount()`. The union of
 * every state a restart would cut, which is deliberately wider than either
 * contract above: Pi streaming (this covers the awaited `agent_start` hook,
 * where Pi is already streaming and no run has been announced), any run not
 * yet settled (this covers the awaited settled hook, where Pi is no longer
 * streaming), compaction of every kind — manual, pre-prompt and overflow —
 * a retry backoff, and a prompt inside Pi's PREFLIGHT.
 *
 * Preflight is the widest of the blind spots. Before Pi sets `isStreaming` or
 * raises `agent_start` it may run an extension command, the `input` hook,
 * authentication, a pre-prompt compaction and `before_agent_start` — so a
 * thread with an accepted prompt in hand reported itself idle and a deploy
 * could release straight through it.
 *
 * Never derived from CONTRACT 1. A manual compaction has no active group and
 * must still hold the gate shut.
 */
const hostIsBusy = (record: ThreadRecord): boolean => {
  const session = record.session;
  return (
    session.isStreaming ||
    session.isCompacting ||
    session.isRetrying ||
    record.generations.length > 0 ||
    record.admittingSend !== undefined
  );
};

