/**
 * A prompt the host has accepted and Pi has not.
 *
 * The host owns a prompt from the moment a caller hands it over until Pi has
 * queued it, started it, or refused it. This is that ownership: the caller's
 * promise, the lane the prompt takes if Pi turns out to be streaming when its
 * turn comes, and the text every reader must be able to see while it waits.
 */
type PendingSend = {
  input: PiSendMessageInput;
  mode: PiQueueMode;
  resolve: () => void;
  reject: (error: unknown) => void;
