async sendMessage(
  threadId: string,
  input: PiSendMessageInput,
): Promise<void> {
  const record = await this.ensureOpen(threadId);
  // CONTRACT 2. A prompt sent while a run is settling would not queue — Pi
  // is no longer streaming, so it would start as a second, overlapping run.
  if (sendDisposition(record) === "hold") {
    return new Promise<void>((resolve, reject) => {
      record.heldSends.push({ input, resolve, reject });
    });
  }
  await this.send(record, input);
}

/** Send what was waiting for the boundary, in the order it arrived. */
private flushHeldSends(record: ThreadRecord): void {
  if (record.heldSends.length === 0) return;
  const waiting = record.heldSends.splice(0, record.heldSends.length);
  for (const held of waiting) {
    this.send(record, held.input).then(held.resolve, held.reject);
  }
}

cases.new_string:
/**
 * Accept a prompt. Resolves once Pi has it — queued or running — and rejects
 * if Pi refuses it or the thread goes away first.
 *
 * The prompt joins the thread's queue and the admission loop hands it over
 * when Pi can take it. Nothing about Pi's state is decided here: a caller's
 * read of the thread is already out of date by the time its request arrives.
 */
async sendMessage(
  threadId: string,
  input: PiSendMessageInput,
): Promise<void> {
  const record = await this.ensureOpen(threadId);
  const accepted = new Promise<void>((resolve, reject) => {
    record.pendingSends.push({
      input,
      mode: input.streamingBehavior === "steer" ? "steer" : "followUp",
      resolve,
      reject,
    });
  });
  this.admitPendingSends(record);
  return accepted;
}

/**
 * Hand prompts to Pi, one at a time, for as long as Pi will take them.
 *
 * Serial by construction: the loop awaits Pi's answer for one prompt before
 * looking at the next, so two prompts can no longer sit in Pi's preflight
 * together — where neither `isStreaming` nor any run exists and Pi's own
 * re-entrancy guard cannot see them.
 *
 * When Pi cannot take a prompt at all the loop parks, leaving the queue
 * visible, and any later session event starts it again.
 */
private admitPendingSends(record: ThreadRecord): void {
  if (record.admittingSend) return;
  void this.runAdmission(record);
}

private async runAdmission(record: ThreadRecord): Promise<void> {
  while (record.pendingSends.length > 0) {
    if (sendDisposition(record) === "hold") {
      this.syncQueue(record);
      return;
    }
    const pending = record.pendingSends[0]!;
    record.pendingSends.shift();
    record.admittingSend = pending;
    this.syncQueue(record);
    try {
      await this.send(record, pending);
      pending.resolve();
    } catch (error) {
      pending.reject(error);
    } finally {
      record.admittingSend = undefined;
    }
  }
}

/** Answer every prompt the host still holds for a thread that is going away.
 * Left alone they would hang until the caller's socket died. */
private rejectPendingSends(record: ThreadRecord, reason: string): void {
  const abandoned = record.pendingSends.splice(0, record.pendingSends.length);
  if (record.admittingSend) abandoned.push(record.admittingSend);
  for (const pending of abandoned) pending.reject(new Error(reason));
}

