cases.new_string:
/**
 * Clear the whole queue — Pi's half and the host's — and return the text so
 * the composer can restore it. Cold threads hold no live session and
 * therefore no queue.
 *
 * A held prompt is one the host accepted and never handed over, so clearing
 * it also answers its caller. It resolves rather than fails: the request was
 * completed by returning the text here, which is what the composer restores,
 * and an error notice on a deliberate Stop would be a lie about a message
 * the user is looking at.
 */
async clearQueue(
  threadId: string,
): Promise<{ steering: string[]; followUp: string[] }> {
  const record = this.records.get(threadId);
  if (!record) return { steering: [], followUp: [] };
  const held = record.pendingSends.splice(0, record.pendingSends.length);
  record.publishedPendingCount = 0;
  // Pi's own clear emits a `queue_update`; the host's half is already empty
  // by then, so that one event states the whole truth.
  const cleared = record.session.clearQueue();
  for (const pending of held) {
    cleared[pending.mode === "steer" ? "steering" : "followUp"].push(
      pending.input.content,
    );
    pending.resolve();
  }
  return cleared;
}

