/**
 * The thread's ONE queue: what Pi holds, then what the host holds for it.
 *
 * A prompt waiting for the admission gate is as real as one Pi has taken —
 * it was accepted, it will run, and Clear must be able to take it back — so
 * the two halves reach every reader as a single list. A prompt currently
 * inside Pi's `prompt()` is in neither half: Pi owns it, and it surfaces as
 * Pi's own queue entry or as the transcript message its run writes.
 */
private queueOf(record: ThreadRecord): {
  steering: string[];
  followUp: string[];
} {
  const session = record.session;
  const steering = [...session.getSteeringMessages()];
  const followUp = [...session.getFollowUpMessages()];
  for (const pending of record.pendingSends) {
    const lane = pending.mode === "steer" ? steering : followUp;
    lane.push(pending.input.content);
  }
  return { steering, followUp };
}

private queuedMessagesOf(record: ThreadRecord): PiQueuedMessage[] {
  const { steering, followUp } = this.queueOf(record);
  return [
    ...steering.map((content, i) => ({
      id: piQueueItemId("steer", i),
      mode: "steer" as const,
      content,
    })),
    ...followUp.map((content, i) => ({
      id: piQueueItemId("followUp", i),
      mode: "followUp" as const,
      content,
    })),
  ];
}

/** The one emitter of `queue_update`, so an event and a snapshot can never
 * describe different queues. */
private publishQueue(record: ThreadRecord): void {
  record.publishedPendingCount = record.pendingSends.length;
  this.emit(record, { type: "queue_update", ...this.queueOf(record) });
}

private syncQueue(record: ThreadRecord): void {
  if (record.publishedPendingCount === record.pendingSends.length) return;
  this.publishQueue(record);
}

