describe("prompt admission", () => {
  type PromptOptions = {
    streamingBehavior?: "followUp" | "steer";
    preflightResult?: (ok: boolean) => void;
  };

  /**
   * A live record whose session sequences a prompt the way Pi does.
   *
   * Pi's `prompt()` runs an extension command, the `input` hook,
   * authentication, a pre-prompt compaction and `before_agent_start` BEFORE
   * it sets `isStreaming` or raises a run — `hold()` holds the session in
   * exactly that window. Once streaming, a prompt without a lane gets the
   * refusal Pi raises for it, which is what the lost message ran into.
   */
  const openForSends = async () => {
    const steering: string[] = [];
    const followUp: string[] = [];
    const waiting: (() => void)[] = [];
    let holding = false;
    let emit: (event: Record<string, unknown>) => void = () => {};
    let promptImpl: (
      content: string,
      options?: PromptOptions,
    ) => Promise<void> = async () => {};

    const prompt = vi.fn((content: string, options?: PromptOptions) =>
      promptImpl(content, options),
    );
    const session = createLiveSession({
      prompt,
      dispose: vi.fn(),
      getSteeringMessages: () => steering,
      getFollowUpMessages: () => followUp,
      clearQueue: vi.fn(() => {
        const drained = { steering: [...steering], followUp: [...followUp] };
        steering.length = 0;
        followUp.length = 0;
        emit({ type: "queue_update", steering: [], followUp: [] });
        return drained;
      }),
      subscribe: vi.fn(
        (listener: (event: Record<string, unknown>) => void) => {
          emit = listener;
          return () => {};
        },
      ),
    });

    promptImpl = async (content, options = {}) => {
      if (holding) await new Promise<void>((r) => waiting.push(r));
      if (session.isStreaming) {
        if (!options.streamingBehavior) {
          options.preflightResult?.(false);
          throw new Error(
            "Agent is already processing. Specify streamingBehavior ('steer' or 'followUp') to queue the message.",
          );
        }
        const lane =
          options.streamingBehavior === "steer" ? steering : followUp;
        lane.push(content);
        emit({
          type: "queue_update",
          steering: [...steering],
          followUp: [...followUp],
        });
        options.preflightResult?.(true);
        return;
      }
      options.preflightResult?.(true);
      session.isStreaming = true;
      emit({ type: "agent_start" });
    };

    sdk.createAgentSession.mockResolvedValue({ session });
    const supervisor = new PiThreadSupervisor({ workspacePath: "/ws" });
    await supervisor.setThinkingLevel("t1", "off"); // opens the record
    return {
      supervisor,
      session,
      prompt,
      steering,
      followUp,
      emit: (event: Record<string, unknown>) => emit(event),
      hold: () => {
        holding = true;
      },
      release: () => {
        holding = false;
        for (const resolve of waiting.splice(0)) resolve();
      },
      /** A run in flight, then settling: Pi is no longer streaming and the
       * run has not settled, which is the window a lane cannot join. */
      settling: () => {
        emit({ type: "agent_start" });
        session.isStreaming = false;
      },
      queued: async () =>
        (await supervisor.getThread("t1")).metadata.queuedMessages ?? [],
      tick: () => new Promise((resolve) => setTimeout(resolve, 0)),
    };
  };

  it("hands Pi one prompt at a time through its preflight", async () => {
    const t = await openForSends();
    t.hold();

