private async runAdmission(record: ThreadRecord): Promise<void> {
  while (record.pendingSends.length > 0) {
    if (sendDisposition(record) === "hold") return;
    const admitting: AdmittingSend = {
      ...record.pendingSends.shift()!,
      wasStreaming: record.session.isStreaming,
      piQueueLength: piQueueLength(record.session),
    };
    record.admittingSend = admitting;
    // The queue does not change here — the prompt is still the host's, it is
    // just in Pi's hands now. What changes is that the thread is busy with
    // something Pi will not announce.
    this.emit(record, { type: "admission_start" });
    let outcome: PiAdmissionOutcome = "refused";
    try {
      await this.send(record, admitting);
      outcome = this.admissionOutcome(record, admitting);
      admitting.resolve();
    } catch (error) {
      admitting.reject(error);
    } finally {
      record.admittingSend = undefined;
      this.applyPendingAbort(record, outcome);
      this.publishQueue(record);
      this.emit(record, {
