/**
 * A prompt in Pi's hands, with the two readings taken as it went in.
 *
 * Pi never says what it did with a prompt, so the host reads the answer off
 * the difference: its queue grew (`queued`), it started streaming (`started`),
 * or neither (`handled` — an extension command, or an `input` hook that
 * consumed the prompt).
 */
type AdmittingSend = PendingSend & {
  wasStreaming: boolean;
  piQueueLength: number;
};

/** How many prompts Pi itself is holding. */
const piQueueLength = (session: AgentSession): number =>
  session.getSteeringMessages().length + session.getFollowUpMessages().length;

cases.new_string:
/**
 * A prompt in Pi's hands, with the thread as it stood when the prompt went in.
 *
 * Pi never says what it did with a prompt, so the host reads the answer off
 * what changed while it held it. Admission is serial, so nothing else could
 * have caused those changes: the window IS the attribution.
 */
type AdmittingSend = PendingSend & {
  wasStreaming: boolean;
  /** Pi's own queue, by content. An aggregate count cannot answer the
   * question: Pi consuming one queued prompt while taking this one leaves the
   * total unchanged. */
  piQueue: readonly string[];
  /** Runs settled so far. A run that ends inside the window is how the host
   * knows a later `isStreaming` belongs to a NEW run rather than the one that
   * was already going. */
  settleCount: number;
};

/** Everything Pi itself is holding, by content. */
const piQueueContents = (session: AgentSession): string[] => [
  ...session.getSteeringMessages(),
  ...session.getFollowUpMessages(),
];

/**
 * Whether Pi's queue GAINED an entry while it held this prompt.
 *
 * By content, as a multiset: a consume-and-add leaves the length identical, and
 * reading the length there reported "Pi took nothing" about a prompt Pi had
 * just queued. Pi expands templates and skills before queueing, so the host
 * cannot look for its own text — only for growth it did not have before.
 */
const piQueueTook = (session: AgentSession, held: readonly string[]): boolean => {
  const before = new Map<string, number>();
  for (const text of held) before.set(text, (before.get(text) ?? 0) + 1);
  for (const text of piQueueContents(session)) {
    const remaining = before.get(text);
    if (remaining === undefined || remaining === 0) return true;
    before.set(text, remaining - 1);
  }
  return false;
};

