/** What Pi did with the prompt, read off the two readings taken when it went
 * in. Pi reports none of this itself. */
private admissionOutcome(
  record: ThreadRecord,
  admitting: AdmittingSend,
): PiAdmissionOutcome {
  if (piQueueLength(record.session) > admitting.piQueueLength) return "queued";
  if (record.session.isStreaming && !admitting.wasStreaming) return "started";
  // Pi took the prompt and started nothing: an extension command, or an
  // `input` hook that consumed it. Nothing else will say the thread is free.
  return "handled";
}

/** Carry out a stop or a teardown that could not reach the prompt while it
 * was in Pi's preflight. Only a run can be aborted; the other outcomes
 * started nothing. */
private applyPendingAbort(
  record: ThreadRecord,
  outcome: PiAdmissionOutcome,
): void {
  if (!record.abortOnAdmission) return;
  record.abortOnAdmission = false;
  if (outcome !== "started") return;
  record.session.abortCompaction();
  record.session.abortRetry();
  void record.session.abort();
}

cases.new_string:
/**
 * What Pi did with the prompt, read off what changed while it held it.
 *
 * `isStreaming` alone cannot answer it. A prompt admitted into a live run
 * that is then STOPPED comes back to a streaming thread again — a different
 * run, started by this very prompt — and reading the flag before and after
 * called that "handled". The run that ended inside the window is the tell,
 * and serial admission means no other prompt could have started the new one.
 */
private admissionOutcome(
  record: ThreadRecord,
  admitting: AdmittingSend,
): PiAdmissionOutcome {
  if (piQueueTook(record.session, admitting.piQueue)) return "queued";
  if (
    record.session.isStreaming &&
    (!admitting.wasStreaming || record.settleCount > admitting.settleCount)
  ) {
    return "started";
  }
  // Pi took the prompt and started nothing: an extension command, or an
  // `input` hook that consumed it. Nothing else will say the thread is free.
  return "handled";
}

/**
 * Carry out a stop that could not reach a prompt inside Pi's preflight.
 *
 * The stop stays ARMED rather than being spent on one guess about what the
 * admission produced. Whatever run appears next belongs to that prompt —
 * admission is serial, so nothing else can start one — and a queued prompt
 * reaches the same place, because Pi continues the run to deliver it. The
 * arming ends when the thread is genuinely idle.
 */
private applyPendingStop(record: ThreadRecord): void {
  if (!record.pendingStop) return;
  record.session.abortCompaction();
  record.session.abortRetry();
  void record.session.abort();
}

