  // Pi rewrites prompts before queueing and dequeues by `indexOf(text)`,
  // so text owns nothing. Reading the queue before and after saw a
  // consume-and-add as no change at all, mislabelled the admission and
  // showed the prompt twice.
  for (const lane of ["followUp", "steer"] as const) {
