    await t.supervisor.sendMessage("t1", {
      content: "same",
      ...(lane === "steer" ? { streamingBehavior: lane } : {}),
    });

    expect(t.lastOutcome(), lane).toBe("queued");
    expect(await t.queued(), lane).toMatchObject([
      { mode: lane, content: "same" },
    ]);
  }
});

