cases.old_string:
/**
 * Who is asking.
 *
 * The fork ships one deployment, one user, nothing to attribute — so the
 * default answer is `null` and every ownership record reads "anonymous".
 * A deployment behind an identity-aware proxy names the header it stamps with
 * `PI_IDENTITY_HEADER` and gets the raw value; a deployment whose header needs
 * decoding (a prefix, a JWT claim, a lookup) replaces this one function, which
 * is the only place identity enters the host.
 */
import { identityHeader } from "./host-config";

export const identify = (request: Request): string | null => {
  if (!identityHeader) return null;
  const value = request.headers.get(identityHeader);
  return value && value.trim() ? value.trim() : null;
};

cases.new_string:
/**
 * Who is asking.
 *
 * The fork ships one deployment, one user, nothing to attribute — so the
 * default answer is `null` and every ownership record reads "anonymous".
 * A deployment behind an identity-aware proxy names the header it stamps with
 * `PI_IDENTITY_HEADER` and gets the raw value; a deployment whose header needs
 * decoding (a prefix, a JWT claim, a lookup) replaces this one function, which
 * is the only place identity enters the host.
 */
import { AsyncLocalStorage } from "node:async_hooks";
import { identityHeader } from "./host-config";

export const identify = (request: Request): string | null => {
  if (!identityHeader) return null;
  const value = request.headers.get(identityHeader);
  return value && value.trim() ? value.trim() : null;
};

const creating = new AsyncLocalStorage<{ by: string | null }>();

/**
 * Run a create with the caller who asked for it in scope.
 *
 * An ownership record needs two things at once, and one request holds only
 * one of them: the identity is in the headers, and the chat's id belongs to
 * `createThread`. They meet inside the create, in the resource-loader hook Pi
 * runs before it builds the session — which is where the record has to be
 * written, because a record written afterwards can fail with the chat already
 * made. This is how the identity gets there.
 */
export const createdBy = <T>(
  by: string | null,
  create: () => Promise<T>,
): Promise<T> => creating.run({ by }, create);

/**
 * The caller of the create in progress, or `undefined` outside one.
 *
 * Absent is a real answer and not a missing one: the same hook runs on every
 * RESUME, and resuming a chat owns nothing.
 */
export const creator = (): { by: string | null } | undefined =>
  creating.getStore();

cases.old_string:
const NOT_OURS = "the ownership sidecar is not the sidecar root's own file";

/**
 * Refuse to go on unless the ownership store is this host's own.
 *
 * Every chat has an ownership line, and `appendOwner` runs AFTER the chat is
 * made — so a store it turns down leaves a chat nobody owns, which nothing
 * retries and no later pass repairs. The caller runs this FIRST and makes
 * nothing if it throws, which turns a permanently unowned chat into a chat
 * that was never created.
 */
export const assertOwnershipStore = (): void => {
  if (!ownersFile(true)) throw new Error(NOT_OURS);
};

/** Stamp a thread with its creator. Throws rather than writing the record
 * somewhere else — a sidecar tree this host did not build is a fault to fix,
 * not a condition to route around. */
export const appendOwner = (threadId: string, by: string | null): void => {
  const file = ownersFile(true);
  if (!file) throw new Error(NOT_OURS);
  append(file, { ts: new Date().toISOString(), threadId, by });
};

cases.new_string:
const NOT_OURS = "the ownership sidecar is not the sidecar root's own file";

/**
 * The ownership record could not be written, so the chat must not be made.
 *
 * Its own type because its own answer follows from it: this is raised before
 * anything exists, so the caller can say the create was REFUSED and hand the
 * user their draft back. Every other failure of a create has to answer for a
 * chat that may be open already.
 */
export class OwnerRecordError extends Error {
  constructor(reason: string, options?: { cause?: unknown }) {
    super(`the chat was not created: ${reason}`, options);
    this.name = "OwnerRecordError";
  }
}

/**
 * Stamp a chat with its creator, BEFORE the chat exists.
 *
 * Every chat has an ownership line, and this is what makes that true rather
 * than likely: it runs inside the create, from the hook Pi calls before it
 * builds the session, so a store that cannot take the record stops the chat
 * being made at all. Written afterwards it could fail with the chat already
 * open — nothing retries a stamp and no later pass repairs one, so that chat
 * would have no owner for the rest of its life.
 *
 * The cost of this order is a line naming a chat that was never created, when
 * a later step of the same create refuses. That is harmless: the record says
 * who asked for a chat, and nothing reads it for a chat that is not in the
 * listing.
 *
 * A tampered tree throws too, rather than writing the record somewhere else —
 * a sidecar tree this host did not build is a fault to fix, not a condition to
 * route around.
 */
export const appendOwner = (threadId: string, by: string | null): void => {
  try {
    const file = ownersFile(true);
    if (!file) throw new OwnerRecordError(NOT_OURS);
    append(file, { ts: new Date().toISOString(), threadId, by });
  } catch (cause) {
    if (cause instanceof OwnerRecordError) throw cause;
    throw new OwnerRecordError("its ownership record could not be written", {
      cause,
    });
  }
};

