export const POST = withFail(async (req: NextRequest) => {
  const body = (await req.json().catch(() => ({}))) as {
    title?: string;
    initialMessage?: PiSendMessageInput;
  };
  // Ownership is stamped after the chat exists, because the id is what
  // `createThread` answers with — so the store is proven writable BEFORE one
  // is made. Without this a tampered or unwritable store leaves a chat nobody
  // owns, permanently: nothing retries the stamp and no later pass repairs it,
  // and «every chat has an ownership line» would be false for that chat
  // forever.
  assertOwnershipStore();
  // A command cannot be a chat's FIRST message, and `createThread` is what
  // decides it: the session it builds is the registry Pi will dispatch
  // against, so it sees the commands an extension registers in `session_start`
  // and the prompts and skills it contributes from `resources_discover`. This
  // route asks no list of its own, so nothing about command discovery can
  // stand between a user and an ordinary new chat.
  let snapshot;
  try {
    snapshot = await piClient.createThread({
      ...(body.title ? { title: body.title } : {}),
      ...(body.initialMessage ? { initialMessage: body.initialMessage } : {}),
    });
  } catch (error) {
    if (error instanceof PiFirstMessageCommandError) {
      // The desk was made before Pi built the session, so a refusal has to
      // hand it back — otherwise every refused command leaves one behind.
      removeEmptyDesk(error.threadId);
      return badRequest(error.message);
    }
    throw error;
  }
  appendOwner(snapshot.metadata.id, identify(req));
  return Response.json(snapshot);
});

