export const POST = withFail(async (req: NextRequest) => {
  const body = (await req.json().catch(() => ({}))) as {
    title?: string;
    initialMessage?: PiSendMessageInput;
  };
  // A command cannot be a chat's FIRST message, and `createThread` is what
  // decides it: the session it builds is the registry Pi will dispatch
  // against, so it sees the commands an extension registers in `session_start`
  // and the prompts and skills it contributes from `resources_discover`. This
  // route asks no list of its own, so nothing about command discovery can
  // stand between a user and an ordinary new chat.
  //
  // The caller rides along because the chat is stamped with its creator from
  // INSIDE the create, before there is a chat to stamp — see `createdBy`.
  let snapshot;
