  /** The id the refused chat would have had. A host that prepared anything for
   * it (`createResourceLoader` makes an output directory, say) needs the name
   * to take it back. */
  readonly threadId: string;

  constructor(
    threadId: string,
    options?: { cause?: unknown; message?: string },
  ) {
    super(options?.message ?? "the chat was not created", false, {
      cause: options?.cause,
    });
    this.name = "PiCreateRefusedError";
    this.threadId = threadId;
  }
