/**
 * Run-level states that leave no trace in the transcript: an in-flight
 * compaction, an auto-retry, the last run error, and what the last Stop
 * reached. Each clears itself when the state it reports ends.
 *
 * The Stop line is the one a user cannot get anywhere else. A thread goes idle
 * whether or not the stop reached anything, so a report of `false` (Pi was
 * holding the prompt and offers no way to recall it) or `"unknown"` (the host
 * had no view of the work) has to be said out loud — otherwise pressing Stop
 * always looks like it worked.
 */
const RunNotices: FC = () => {
  const { compaction, retry, lastError, lastStop } = usePiRuntimeExtras();

  const stopNotice =
    lastStop?.stopped === true
      ? strings.stopped
      : lastStop?.stopped === false
        ? strings.stopFailed
        : lastStop
          ? strings.stopUnknown
          : undefined;

  const notices = [
    compaction.active &&
      `${strings.compacting}${compaction.reason ? ` (${compaction.reason})` : ""}…`,
    retry.active && `${strings.retrying(retry.attempt)}…`,
    lastError,
    stopNotice,
  ].filter((notice): notice is string => typeof notice === "string");
  if (notices.length === 0) return null;

  const alarming = new Set(
    [lastError, lastStop?.stopped === true ? undefined : stopNotice].filter(
