type FeedbackStore = {
  records: readonly FeedbackRecord[];
  submit: (messageId: string, value: "up" | "down") => void;
};

const FeedbackContext = createContext<FeedbackStore | undefined>(undefined);

export const PiFeedbackProvider: FC<{
  threadId: string | undefined;
  children: ReactNode;
}> = ({ threadId, children }) => {
  const [records, setRecords] = useState<readonly FeedbackRecord[]>([]);

  useEffect(() => {
    setRecords([]);
    if (!threadId) return;
    let current = true;
    void api
      .listFeedback(threadId)
      .then((next) => {
        if (current) setRecords(next);
      })
      .catch(() => {});
    return () => {
      current = false;
    };
  }, [threadId]);

  const submit = useCallback(
    (messageId: string, value: "up" | "down") => {
      if (!threadId) return;
      // Appended locally first so the thumb lights immediately; the file is
      // append-only and read front to back, so the same last-write-wins rule
      // applies to this optimistic entry as to the stored one.
      const optimistic: FeedbackRecord = {
        messageId,
        value,
        ts: new Date().toISOString(),
      };
      setRecords((current) => [...current, optimistic]);
      void api.submitFeedback(threadId, messageId, value).catch(() => {
        setRecords((current) =>
          current.filter((record) => record !== optimistic),
        );
      });
    },
    [threadId],
  );

  const store = useMemo<FeedbackStore>(
    () => ({ records, submit }),
    [records, submit],
  );
  return (
    <FeedbackContext.Provider value={store}>
      {children}
    </FeedbackContext.Provider>
  );
};

