type FeedbackStore = {
  /** The sidecar, as the server wrote it. */
  records: readonly FeedbackRecord[];
  /** Clicks this session has made and the server has not answered yet. */
  pending: Readonly<Record<string, Thumb>>;
  submit: (messageId: string, value: Thumb) => void;
};

const FeedbackContext = createContext<FeedbackStore | undefined>(undefined);

const withoutPending = (
  pending: Readonly<Record<string, Thumb>>,
  messageId: string,
  settled: Thumb,
): Readonly<Record<string, Thumb>> => {
  // A second click while the first is in flight leaves a NEWER pending value
  // here, and that one is still waiting for its own answer.
  if (pending[messageId] !== settled) return pending;
  const { [messageId]: _done, ...rest } = pending;
  return rest;
};

export const PiFeedbackProvider: FC<{
  threadId: string | undefined;
  children: ReactNode;
}> = ({ threadId, children }) => {
  const [records, setRecords] = useState<readonly FeedbackRecord[]>([]);
  const [pending, setPending] = useState<Readonly<Record<string, Thumb>>>({});

  useEffect(() => {
    setRecords([]);
    setPending({});
    if (!threadId) return;
    let current = true;
    void api
      .listFeedback(threadId)
      .then((next) => {
        if (current) setRecords(next);
      })
      .catch(() => {});
    return () => {
      current = false;
    };
  }, [threadId]);

  const submit = useCallback(
    (messageId: string, value: Thumb) => {
      if (!threadId) return;
      // The thumb lights from here, above the store. The record that lands in
      // the store is the one the SERVER wrote, timestamp included — see
      // `chosenThumb` for why a browser clock may not compete with it.
      setPending((current) => ({ ...current, [messageId]: value }));
      void api
        .submitFeedback(threadId, messageId, value)
        .then((written) => {
          setRecords((current) => [...current, written]);
          setPending((current) => withoutPending(current, messageId, value));
        })
        .catch(() => {
          setPending((current) => withoutPending(current, messageId, value));
        });
    },
    [threadId],
  );

  const store = useMemo<FeedbackStore>(
    () => ({ records, pending, submit }),
    [records, pending, submit],
  );
  return (
    <FeedbackContext.Provider value={store}>
      {children}
    </FeedbackContext.Provider>
  );
};

