// Probe the surface along two vehicle-relative axes and read each as a tilt
// angle. Forward = (-sin h, -cos h); the vehicle's right = forward rotated +90°
// about Y → (-forwardZ, forwardX) = (cos h, -sin h). Front higher → positive
// pitch (nose up); right higher → positive roll (rotation.z lifts +X toward +Y).
// The player truck and every rival share this, so they all sit on the same
// terrain the same way.
export function surfaceTiltAt(x, z, heading) {
  const forwardX = -Math.sin(heading);
  const forwardZ = -Math.cos(heading);
  const frontY = surfaceHeightAt(x + forwardX * PITCH_SAMPLE_D, z + forwardZ * PITCH_SAMPLE_D);
  const backY = surfaceHeightAt(x - forwardX * PITCH_SAMPLE_D, z - forwardZ * PITCH_SAMPLE_D);
  const rightY = surfaceHeightAt(x - forwardZ * ROLL_SAMPLE_D, z + forwardX * ROLL_SAMPLE_D);
  const leftY = surfaceHeightAt(x + forwardZ * ROLL_SAMPLE_D, z - forwardX * ROLL_SAMPLE_D);

  return {
    pitch: Math.atan2(frontY - backY, PITCH_SAMPLE_D * 2),
    roll: Math.atan2(rightY - leftY, ROLL_SAMPLE_D * 2),
  };
