// Synthetic player motion, in m/s along the course centreline. These are the
// cases that decide whether a rival reads as a driver or as a puppet, and none
// of them can be reached from a still frame: a rival that stops when the player
// stops is a puppet, and so is one that reverses when the player reverses.
const DRIVE_PROFILES = {
  cruise: () => MAX_SPEED,
  stop: (time) => (time < 6 ? MAX_SPEED : 0),
  reverse: (time) => (time < 6 ? MAX_SPEED : -MAX_SPEED * 0.5),
  crawl: () => 2,
};

function createSyntheticDriver(shell, profileName) {
  const profile = DRIVE_PROFILES[profileName];
  if (!profile) {
    throw new Error(`?drive=${profileName} is not one of: ${Object.keys(DRIVE_PROFILES).join(', ')}.`);
  }

  let distanceAlong = null;

  return function advance(dt, elapsedTime) {
    if (distanceAlong === null) distanceAlong = playerDistanceAlong(shell);
    const speed = profile(elapsedTime);
    distanceAlong = THREE.MathUtils.clamp(distanceAlong + speed * dt, 0, COURSE.length);
    gotoCourse(shell, distanceAlong);
    shell.driveState.speed = speed;
  };
}

