// Lanes alternate sides and step outward, so rival 0 passes on one side, rival 1
// on the other, rival 2 outside rival 0, and no two ever share a lane.
function laneFor(index) {
  const side = index % 2 === 0 ? 1 : -1;
  const rank = Math.floor(index / 2);
  return side * (RACE.laneNearest + rank * RACE.laneStep);
}

// A pass happens beside the player, never through him. A rival runs the
// centreline while it is far away and sits fully in its own lane by the time the
// gap closes. Read straight off the gap rather than damped toward it: the gap is
// already smooth, and a damped lateral lags behind a fast close and lets the two
// trucks overlap, which is the one thing this rule exists to prevent.
function passingLateral(rival) {
  const closeness = 1 - Math.min(Math.abs(rival.gap) / RACE.overtakeRange, 1);
  return rival.lane * closeness;
}

