/**
 * The refusals waiting to be handed back, under the chat that produced each —
 * `undefined` for a chat that does not exist yet.
 *
 * One slot PER OWNER, and not one slot in all. A single slot holds one attempt,
 * so a failure from a chat that EXISTS had to be turned away at the door to
 * stop it throwing away one that would have been consumed: a refused first
 * message stored while its chat was off screen, overwritten by an unrelated
 * send elsewhere, and its text and images gone by the time the user came back
 * to it. Turning it away lost that draft instead — an upload the server refuses
 * is an everyday event on a chat that exists, and no composer was ever handed
 * it back. Keyed by owner the two cannot collide, so neither is lost.
 */
export type PiSendRefusals = ReadonlyMap<string | undefined, PiSendRefusal>;

/**
 * What the app should hold after this failure.
 *
 * A second failure on the SAME chat replaces that chat's, and only that
 * chat's: the composer it belongs to shows one reason and takes one draft
 * back, and the newer attempt is the one the user just made.
 *
 * >>> nextRefusal(new Map(), { error: 1, input: { content: "hi" }, threadId: "t1", delivered: false }, "no").size
 * 1
 */
export const nextRefusal = (
  held: PiSendRefusals,
  failure: PiSendFailure,
  reason: string,
): PiSendRefusals => new Map(held).set(failure.threadId, { reason, failure });

/**
 * The refusals left once this one has been dealt with.
 *
 * Retiring is per owner too. A composer takes its own and leaves every other
 * chat's where it is, however long that chat stays off screen.
 */
export const withoutRefusal = (
  held: PiSendRefusals,
  refusal: PiSendRefusal,
): PiSendRefusals => {
  const rest = new Map(held);
  rest.delete(refusal.failure.threadId);
  return rest;
};

/**
 * The refusal this composer may act on, or undefined.
 *
 * The attempt names its owner and that is the whole rule. Reading the open
 * thread instead pasted one chat's draft into another's empty composer.
 *
 * >>> ownedRefusal(new Map(), undefined)
 * undefined
 */
export const ownedRefusal = (
  held: PiSendRefusals,
  threadId: string | undefined,
): PiSendRefusal | undefined => held.get(threadId);

