describe("persistInheritedMessages — the child session file is resumable", () => {
	function roundTrip(messages: AgentMessage[]): AgentMessage[] {
		const sessionDirectory = mkdtempSync(join(tmpdir(), "pi-user-agents-"));
		try {
			const sessionManager = SessionManager.create("/tmp/project", sessionDirectory);
			persistInheritedMessages(sessionManager, messages);
			const sessionFile = sessionManager.getSessionFile();
			expect(sessionFile, "Expected the child session to have a file path").toBeString();
			return SessionManager.open(sessionFile as string).buildSessionContext().messages;
		} finally {
			rmSync(sessionDirectory, { recursive: true, force: true });
		}
	}

	test("a reopened child session sees the same conversation the live child inherited", () => {
		const inherited = [
			{ role: "user", content: "review the migration", timestamp: 1 },
			{
				role: "assistant",
				content: [{ type: "text", text: "reviewed" }],
				timestamp: 2,
				stopReason: "stop",
			},
			{
				role: "custom",
				customType: "pi-user-agents",
				content: "<user_agent>an earlier result card</user_agent>",
				display: false,
				timestamp: 3,
			},
		] as AgentMessage[];

		const restored = roundTrip(inherited);

		expect(restored.map((message) => message.role)).toEqual(["user", "assistant", "custom"]);
		expect(restored[0]).toMatchObject({ role: "user", content: "review the migration" });
		expect(restored[2]).toMatchObject({
			role: "custom",
			customType: "pi-user-agents",
			display: false,
		});
	});

	test("a snapshot taken after the main session compacted keeps its summary at the head", () => {
		const inherited = [
			{ role: "compactionSummary", summary: "everything before the compaction", tokensBefore: 90_000, timestamp: 1 },
			{ role: "user", content: "carry on", timestamp: 2 },
			{
				role: "assistant",
				content: [{ type: "text", text: "carrying on" }],
				timestamp: 3,
				stopReason: "stop",
			},
		] as AgentMessage[];

		const restored = roundTrip(inherited);

		expect(restored.map((message) => message.role)).toEqual([
			"compactionSummary",
			"user",
			"assistant",
		]);
		expect(restored[0]).toMatchObject({
			role: "compactionSummary",
			summary: "everything before the compaction",
			tokensBefore: 90_000,
		});
	});
});

