cases.new_string:
/**
 * A queued prompt as the user wrote it.
 *
 * A prompt is PREPARED before it is handed over, so everything the host holds
 * mid-admission and everything in Pi's lanes carries the file-upload envelope
 * `prepareSend` appended. That envelope addresses the agent, and a person must
 * never be shown it: the queue card renders this text, and Clear and Stop put
 * it back in the composer, where a resend would envelope it a second time.
 * `parsePiFileReferences` is the exact inverse of the append that made it, and
 * a prompt that never carried one comes back unchanged.
 *
 * >>> queueTextForReader("summarize it")
 * 'summarize it'
 */
const queueTextForReader = (content: string): string =>
  parsePiFileReferences(content).content;

type CatalogCacheEntry = {
  infos: readonly PiSessionInfo[] | undefined;
  promise: Promise<readonly PiSessionInfo[]> | undefined;
};

