cases.new_string:
sdk.createAgentSession.mockResolvedValue({ session });
const supervisor = new PiThreadSupervisor({
  workspacePath: "/ws",
  ...options,
});
await supervisor.setThinkingLevel("t1", "off"); // opens the record

const UPLOAD = {
  name: "sixth.txt",
  mimeType: "text/plain",
  size: 10,
  path: "/ws/.artifacts/t1/.upload-9d3f",
};

/** The host hook the chat app installs, in miniature: an uploaded file goes
 * to the session desk and the prompt gains the envelope naming it. */
const materializeUpload = async ({
  input,
}: PiPrepareSendContext): Promise<PiSendMessageInput> => {
  const files =
    input.attachments?.filter(({ type }) => type === "file") ?? [];
  if (files.length === 0) return input;
  const prepared = {
    ...input,
    content: appendPiFileReferences(input.content, [UPLOAD]),
  };
  delete prepared.attachments;
  return prepared;
};

const withUpload = (content: string): PiSendMessageInput => ({
  content,
  attachments: [
    {
      type: "file",
      name: UPLOAD.name,
      mimeType: UPLOAD.mimeType,
      data: "c2l4dGgK",
    },
  ],
});

const lastQueueUpdate = (events: Record<string, unknown>[]) =>
  [...events].reverse().find((event) => event.type === "queue_update");

it("shows a queued upload prompt as the user wrote it, and still gives Pi the file references", async () => {
  const t = await openForSends({ prepareSend: materializeUpload });
  const events: Record<string, unknown>[] = [];
  t.supervisor.subscribe("t1", (event) => events.push(event));
  await vi.waitFor(() => expect(events).not.toHaveLength(0));
  // A run is live, so the sends behind it go into Pi's own lanes.
  await t.supervisor.sendMessage("t1", { content: "start" });

  await t.supervisor.sendMessage("t1", {
    ...withUpload("summarize it"),
    streamingBehavior: "steer",
  });
  await t.supervisor.sendMessage("t1", withUpload("and translate it"));

  // Pi's half: the agent still reads the file off the desk path.
  expect(t.session.steer).toHaveBeenCalledWith(
    appendPiFileReferences("summarize it", [UPLOAD]),
    undefined,
  );
  expect(t.session.followUp).toHaveBeenCalledWith(
    appendPiFileReferences("and translate it", [UPLOAD]),
    undefined,
  );

  // The reader's half: the queue card renders these, and an envelope
  // addressed to the agent is not something a person may be shown.
  expect(await t.queued()).toMatchObject([
    { mode: "steer", content: "summarize it" },
    { mode: "followUp", content: "and translate it" },
  ]);
  expect(lastQueueUpdate(events)).toMatchObject({
    steering: ["summarize it"],
    followUp: ["and translate it"],
  });

  // Clear restores what the user typed. Restoring the prepared text would
  // put the envelope in the composer, where a resend enveloped it twice.
  await expect(t.supervisor.clearQueue("t1")).resolves.toEqual({
    steering: ["summarize it"],
    followUp: ["and translate it"],
  });
});

it("shows an upload prompt inside Pi's preflight as the user wrote it", async () => {
  // The prompt is prepared at admission, so the one the host still holds
  // carries the envelope too — `queueOf` publishes it either way.
  const t = await openForSends({ prepareSend: materializeUpload });
  const events: Record<string, unknown>[] = [];
  t.supervisor.subscribe("t1", (event) => events.push(event));
  await vi.waitFor(() => expect(events).not.toHaveLength(0));
  t.hold();

  const send = t.supervisor.sendMessage("t1", withUpload("read this"));
  await vi.waitFor(() => expect(t.prompt).toHaveBeenCalled());

  expect(t.prompt).toHaveBeenCalledWith(
    appendPiFileReferences("read this", [UPLOAD]),
    expect.anything(),
  );
  expect(await t.queued()).toMatchObject([{ content: "read this" }]);
  expect(lastQueueUpdate(events)).toMatchObject({
    followUp: ["read this"],
  });

  t.release();
  await send;
});

