async function upload(blob, filename) {
  recorder = null;
  toggle.classList.remove("recording");
  toggle.textContent = "שולח...";
  toggle.disabled = true;
  status.textContent = "מעבד...";
  const form = new FormData();
  form.append("file", blob, filename);
  try {
    const response = await fetch("/recordings", {
      method: "POST",
      headers: { "X-Auth-Secret": SECRET },
      body: form,
    });
    if (!response.ok) throw new Error(await response.text());
    const data = await response.json();
    pendingBlob = null;
    pendingFilename = null;
    toggle.textContent = "התחל הקלטה";
    if (data.findings.length) {
      status.textContent = "הממצאים נשלחו למחשב:";
      result.textContent = data.findings.join("\\n");
    } else {
      status.textContent = "לא זוהו ממצאים רפואיים. התמלול:";
      result.textContent = data.transcript;
    }
  } catch (error) {
    pendingBlob = blob;
    pendingFilename = filename;
    toggle.textContent = "נסה שוב";
    status.textContent = "השליחה נכשלה. ההקלטה נשמרה לניסיון נוסף.";
  } finally {
    toggle.disabled = false;
    if (wakeLock) { wakeLock.release(); wakeLock = null; }
  }
}

