  error: unknown;
  /** The message exactly as it went out — the text and the attachments. */
  input: PiSendMessageInput;
  /** The thread the attempt was made on, or `undefined` for a chat that did
   * not exist yet. Never inferred from whichever thread is open when the
   * failure arrives. */
  threadId: string | undefined;
};

