const reportPiCallbackError = (name: string, callbackError: unknown) => {
  console.error(`[react-pi] ${name} callback threw an error`, callbackError);
};

/** Call a host callback without letting it break the caller, however it fails. */
const invokePiCallback = <T>(
  name: string,
  callback: ((value: T) => unknown) | undefined,
  value: T,
) => {
  if (!callback) return;
  try {
    void Promise.resolve(callback(value)).catch((callbackError: unknown) =>
      reportPiCallbackError(name, callbackError),
    );
  } catch (callbackError) {
    reportPiCallbackError(name, callbackError);
  }
};

const invokePiErrorCallback = (
  onError: PiRuntimeOptions["onError"],
  error: unknown,
) => invokePiCallback("onError", onError, error);

/**
 * Report a send that did not get through — to `onError` as any failure, and to
 * `onSendFailed` with the attempt itself.
 *
 * The attempt is rebuilt from `buildPiSendInput`, the one function that decides
 * what a send puts on the wire, so what a host is handed back is what went out
 * rather than a second reading of it.
 */
const reportFailedSend = (
  options: PiRuntimeOptions,
  threadId: string | undefined,
  message: AppendMessage,
  sendOptions: PiSendOptions | undefined,
  error: unknown,
) => {
  invokePiErrorCallback(options.onError, error);
  invokePiCallback("onSendFailed", options.onSendFailed, {
    error,
    input: buildPiSendInput(message, sendOptions),
    threadId,
  });
};

