    };
    root = createRoot(document.createElement("div"));
    await act(async () => root!.render(createElement(App)));
    return onSendFailed;
  };

  it("hands back the attempt an existing thread refused, named by that thread", async () => {
    const refusal = new Error("refused");
    mocks.controller.sendMessage.mockRejectedValueOnce(refusal);
    const onSendFailed = await render();

    await expect(mocks.adapters.at(-1)!.onNew(messageWithImage)).rejects.toBe(
      refusal,
    );

    expect(onSendFailed).toHaveBeenCalledWith({
      error: refusal,
      input: expectedInput,
      threadId: "t1",
    });
  });

  it("names a queued send's own thread too", async () => {
    const refusal = new Error("refused");
    mocks.controller.sendMessage.mockRejectedValueOnce(refusal);
    const onSendFailed = await render();

    await act(async () => {
      mocks.adapters.at(-1)!.queue!.steer!(messageWithImage);
    });

    await vi.waitFor(() =>
      expect(onSendFailed).toHaveBeenCalledWith({
        error: refusal,
        input: { ...expectedInput, streamingBehavior: "steer" },
        threadId: "t1",
      }),
    );
  });

  it("names no thread for a chat that does not exist yet", async () => {
    // The owner of a refused first message is the new-chat request, not
    // whichever chat the user opens next — reading the open thread instead
