/** Where a slash-prefixed name comes from. A `skill` name carries Pi's own
 * `skill:` prefix, which is how `_expandSkillCommand` reads it. */
export type PiCommandSource = "extension" | "skill" | "prompt";

/**
 * The name Pi would look up in `source`'s registry, or undefined when Pi would
 * not read this text as one of its names at all.
 *
 * >>> piCommandName("/compact now", "prompt")
 * "compact"
 * >>> piCommandName("/compact\tnow", "prompt")
 * "compact"
 * >>> piCommandName("/compact\tnow", "extension")
 * "compact\tnow"
 * >>> piCommandName(" /compact", "extension")
 * undefined
 */
export const piCommandName = (
  text: string,
  source: PiCommandSource,
): string | undefined => {
  if (!text.startsWith("/")) return undefined;
  const name = source === "prompt" ? whitespaceToken(text) : spaceToken(text);
  return name === "" ? undefined : name;
};

cases.new_string:
/** Where a slash-prefixed name comes from. A `skill` name carries Pi's own
 * `skill:` prefix, which is how `_expandSkillCommand` reads it. */
export type PiCommandSource = "extension" | "skill" | "prompt";

/** Pi enters skill lookup only for this prefix, and keeps it in the name it
 * takes (`_expandSkillCommand` returns the text untouched without it). */
const SKILL_PREFIX = "/skill:";

/**
 * The name Pi would look up in `source`'s registry, or undefined when Pi would
 * not read this text as one of its names at all.
 *
 * >>> piCommandName("/compact now", "prompt")
 * "compact"
 * >>> piCommandName("/compact\tnow", "prompt")
 * "compact"
 * >>> piCommandName("/compact\tnow", "extension")
 * "compact\tnow"
 * >>> piCommandName(" /compact", "extension")
 * undefined
 * >>> piCommandName("/compact", "skill")
 * undefined
 */
export const piCommandName = (
  text: string,
  source: PiCommandSource,
): string | undefined => {
  if (!text.startsWith("/")) return undefined;
  if (source === "skill" && !text.startsWith(SKILL_PREFIX)) return undefined;
  const name = source === "prompt" ? whitespaceToken(text) : spaceToken(text);
  return name === "" ? undefined : name;
};

