/**
 * Report a send that did not get through — to `onError` as any failure, and to
 * `onSendFailed` with the attempt itself.
 *
 * The attempt is rebuilt from `buildPiSendInput`, the one function that decides
 * what a send puts on the wire, so what a host is handed back is what went out
 * rather than a second reading of it.
 */
const reportFailedSend = (
  callbacks: PiSendCallbacks,
  threadId: string | undefined,
  message: AppendMessage,
  sendOptions: PiSendOptions | undefined,
  error: unknown,
) => {
  invokePiErrorCallback(callbacks.onError, error);
  invokePiCallback("onSendFailed", callbacks.onSendFailed, {
    error,
    input: buildPiSendInput(message, sendOptions),
    threadId,
  });
};

cases.new_string:
/**
 * Report a send that did not get through — to `onError` as any failure, and to
 * `onSendFailed` with the attempt itself.
 *
 * `input` is the caller's, captured BEFORE the send went out. An `AppendMessage`
 * belongs to whoever built it and can change while the request is open, so
 * reading it again in the catch would report something other than what was
 * sent. Every caller builds it with `buildPiSendInput` — the one function that
 * decides what a send puts on the wire — on the same tick the controller does.
 */
const reportFailedSend = (
  callbacks: PiSendCallbacks,
  threadId: string | undefined,
  input: PiSendMessageInput,
  error: unknown,
) => {
  invokePiErrorCallback(callbacks.onError, error);
  invokePiCallback("onSendFailed", callbacks.onSendFailed, {
    error,
    input,
    threadId,
  });
};

