/** `root` as the filesystem really names it, or `null` when it is not there. */
export const realPathOf = (root: string): string | null => {
  try {
    return fs.realpathSync(path.resolve(root));
  } catch {
    return null;
  }
};

export const realChildOf = (root: string, name: string): string | null => {
  const realRoot = realPathOf(root);
  if (realRoot === null) return null;
  const child = threadScopedPath(realRoot, name);

const OWNERS = "owners.jsonl";

/**
 * The ownership file, or `null` when the path that name leads to is not it.
 *
 * The feedback rules, in the other direction. Rounds 4 and 5 stopped a thread
 * id from reaching ownership through `feedback`; nothing stopped ownership
 * from reaching a thread's feedback the same two ways. `owners.jsonl` aliased
 * to a feedback file makes every ownership read and write land in that file,
 * and a HARD link makes the two one with no target to resolve and no path test
 * that can see it.
 *
 * So: the sidecar root as the filesystem really names it, its OWN child of
 * that name, and one that is a regular file with exactly one NAME. `lstat`,
 * not `exists`, because a dangling link reports absent and appending to one
 * creates the file it points at.
 *
 * Absent is the FIRST WRITE and only a create may have it: the name is built
 * on the resolved root, so the file this makes is the root's own child by
 * construction. A read of a sidecar that is not there is simply no records.
 */
const ownersFile = (create: boolean): string | null => {
  if (create) fs.mkdirSync(sidecarDir, { recursive: true });
  const realRoot = realPathOf(sidecarDir);
  if (!realRoot) return null;
  const file = threadScopedPath(realRoot, OWNERS);
  try {
    const stat = fs.lstatSync(file);
    return stat.isFile() && stat.nlink === 1 ? file : null;
  } catch {
    return create ? file : null;
  }
};

