cases.new_string:
export const PiSendRefusalProvider: FC<{
  /** The open chat, or `undefined` for one that does not exist yet. */
  threadId: string | undefined;
  refusal: PiSendRefusal | undefined;
  /** Called once the draft is back in the composer, so the holder can retire
   * the refusal. Consumption is the ONLY thing that retires one: a refusal
   * that lands while the user is in another chat has to survive however many
   * chats they visit before returning to the one it belongs to. */
  onConsumed: () => void;
  children: ReactNode;
}> = ({ threadId, refusal, onConsumed, children }) => {
  const aui = useAui();
  // A restore is a TAKE, on the rule a Stop's reclaimed queue already follows:
  // the attempt goes back once. The ref guards the window before the holder's
  // state update lands, and a double-invoked effect inside it.
  const restored = useRef<PiSendRefusal>(undefined);
  // The notice outlives the payload it came with. The draft is handed back
  // once and the refusal is then gone, but the reason has to stay on screen
  // until this composer stops being the chat it was about.
  const [reason, setReason] = useState<string>();
  const owned = ownedRefusal(refusal, threadId);

  useEffect(() => {
    if (threadId === undefined) return;
    setReason(undefined);
  }, [threadId]);

  useEffect(() => {
    if (!owned || restored.current === owned) return;
    restored.current = owned;
    setReason(owned.reason);
    void restoreComposerSend(aui, owned.failure.input);
    onConsumed();
  }, [aui, owned, onConsumed]);

  return (
    <SendRefusalContext.Provider value={reason}>
      {children}
    </SendRefusalContext.Provider>
  );
};

