  recorder.ondataavailable = (event) => chunks.push(event.data);
  recorder.onstop = () => {
    stream.getTracks().forEach((track) => track.stop());
    clearInterval(timerInterval);
    const extension = mimeType === "audio/mp4" ? "m4a" : "webm";
