/**
 * Put the host's resolution on a settlement before it goes out.
 *
 * Pi's `agent_settled` is bare, and the two questions a reader has to answer
 * from it are both the host's: whether the run it tracks is still open (a
 * settlement arriving mid-stream belongs to an older run), and whether the
 * run itself failed rather than something reported around it. Left to
 * decide, a reader ended a live run and failed a clean one.
 */
private resolveSettlement(
  record: ThreadRecord,
  body: PiClientEventBody,
): PiClientEventBody {
  if (body.type !== "agent_settled") return body;
  return {
    ...body,
    status: this.runStatus(record),
    runActive: record.openRun !== undefined,
    ...(record.runError ? { runError: record.runError } : {}),
  };
}

cases.new_string:
/**
 * Put the host's resolution on a settlement before it goes out.
 *
 * Pi's `agent_settled` is bare, and the two questions a reader has to answer
 * from it are both the host's: whether work is still under way (a settlement
 * arriving mid-stream belongs to an older run, so the host's is untouched),
 * and whether the run itself failed rather than something reported around
 * it. Left to decide, a reader ended a live run and failed a clean one.
 *
 * Each field answers in the ONE meaning it has everywhere else. `runActive`
 * is CONTRACT 1, the same rule `metadataOf` puts on every snapshot — a run
 * that has not written a message yet is not writing the newest group, and a
 * settlement that said otherwise made a connected client rename a finished
 * answer to a positional id and mark it running, while a client reading the
 * snapshot beside it kept the durable id. Whether the host still HAS a run
 * open is CONTRACT 3, and it already travels here as `status: "running"`.
 */
private resolveSettlement(
  record: ThreadRecord,
  body: PiClientEventBody,
): PiClientEventBody {
  if (body.type !== "agent_settled") return body;
  return {
    ...body,
    status: this.runStatus(record),
    runActive: activeGroupExists(record),
    ...(record.runError ? { runError: record.runError } : {}),
  };
}

/**
 * Whether the attempt that just ended was STOPPED rather than broken.
 *
 * Pi shapes a user's stop exactly like a failure: the attempt ends with an
 * assistant message carrying an `errorMessage`, and `state.errorMessage` holds
 * it either way (`AgentState`: "the most recent failed or aborted assistant
 * turn"). The stop reason on that message is the only thing that separates
 * them — Pi writes `aborted` when the run's own signal fired, and the same
 * reason is what the projection already renders as a cancelled message.
 *
 * >>> endedByAbort([{ role: "assistant", stopReason: "aborted" }])
 * true
 */
const endedByAbort = (messages: readonly unknown[]): boolean => {
  for (let index = messages.length - 1; index >= 0; index -= 1) {
    const message = messages[index] as { role?: string; stopReason?: string };
    if (message.role !== "assistant") continue;
    return message.stopReason === "aborted";
  }
  return false;
};

