it("ends a stop in a retry backoff idle, and an unstopped failure failed", async () => {
  // Pi records the attempt's error, THEN moves into its backoff, and the
  // stop ends the backoff without another `agent_start` to clear it — so
  // the settlement announced `failed` for a run the user ended.
  const backoff = async (stop: boolean) => {
    const t = await openForSends();
    t.emit({ type: "agent_start" });
    t.session.isStreaming = true;
    t.emit({ type: "message_start" });
    t.session.state.errorMessage = "503: mock upstream overloaded";
    t.emit({ type: "agent_end", willRetry: true });
    t.emit({ type: "auto_retry_start", attempt: 1, delayMs: 8000 });
    t.session.isRetrying = true;

    if (stop) {
      await t.supervisor.cancelRun("t1");
      expect(t.session.abortRetry).toHaveBeenCalled();
    }

    // Pi gives up on the run either way: a cancelled backoff and an
    // exhausted one both end it without a further attempt.
    t.session.isRetrying = false;
    t.session.isStreaming = false;
    t.emit({ type: "auto_retry_end", success: false });
    t.emit({ type: "agent_settled" });
    return t.supervisor.getThread("t1");
  };

  const stopped = await backoff(true);
  expect(stopped.metadata.status).toBe("idle");
  // The reason survives as the notice it always was.
  expect(stopped.lastError).toBe("503: mock upstream overloaded");

  expect((await backoff(false)).metadata.status).toBe("failed");
});

