  t.session.isCompacting = false;
  t.session.isStreaming = false;
  t.emit({ type: "compaction_end", aborted: true, willRetry: false });
  t.emit({ type: "agent_settled" });

  expect((await t.supervisor.getThread("t1")).metadata.status).toBe("idle");
});

