 * It fires at every chance and is NOT spent on the first one: Pi delivers a
 * queued prompt by continuing the run, so stopping once leaves the delivery
 * still to come. `releasePendingStop` decides when it is over.
 */
private applyPendingStop(record: ThreadRecord): void {
  if (!record.pendingStop) return;
  record.session.abortCompaction();
  record.session.abortRetry();
  void record.session.abort();
}

cases.new_string:
 * It fires at every chance and is NOT spent on the first one: Pi delivers a
 * queued prompt by continuing the run, so stopping once leaves the delivery
 * still to come. `releasePendingStop` decides when it is over.
 *
 * The chances include the phases Pi starts as a CONSEQUENCE of a stop. Its
 * post-run loop decides what happens next only after the aborts land: kill a
 * retry and the failed message goes straight to the compaction check, which
 * can start an auto-compaction the one abort already passed, on a controller
 * `session.abort()` does not reach. Every phase announces itself, so the arm
 * meets each one as it starts rather than the host guessing how many rounds
 * to wait.
 */
private applyPendingStop(record: ThreadRecord): void {
  if (!record.pendingStop) return;
  // Retry first: killing the backoff is what sends Pi into the compaction
  // check, so aborting compaction before that would be aborting the phase
  // that does not exist yet.
  record.session.abortRetry();
  record.session.abortCompaction();
  void record.session.abort();
}

