it("gives a new chat the same reason for the file a chat that exists is given", async () => {
  // The refusal above, raised on the create path instead. Nothing about the
  // file changed, so nothing about the reason may: a refusal is written for
  // the person who can act on it, and one that arrives as "the chat was not
  // created" leaves them with a file they cannot fix.
  const prompt = vi.fn();
  sdk.createAgentSession.mockImplementation(async () => ({
    session: createLiveSession({
      sessionId: sdk.create.mock.calls.at(-1)?.[2]?.id,
      prompt,
    }),
  }));
  const supervisor = new PiThreadSupervisor({
    workspacePath: "/ws",
    prepareSend: () => {
      throw new Error("uploaded file exceeds 10 MiB");
    },
  });

  await expect(
    supervisor.createThread({
      initialMessage: {
        content: "read this",
        attachments: [
          {
            type: "file",
            name: "huge.bin",
            mimeType: "application/octet-stream",
            data: "AAAA",
          },
        ],
      },
    }),
  ).rejects.toSatisfy(
    (error: unknown) =>
      error instanceof PiCreateRefusedError &&
      error.message === "uploaded file exceeds 10 MiB" &&
      // Carrying its own sentence takes nothing from the create's own claim:
      // no chat was made, and the id it would have had comes back so the host
      // can take back whatever it prepared under it.
      error.delivered === false &&
      error.threadId === (sdk.create.mock.calls[0]?.[2]?.id as string),
  );
  expect(prompt).not.toHaveBeenCalled();
});

