it("carries a sentence the same loader raised deliberately", async () => {
  // The other direction of the rule above, and the whole of it: raising a
  // `PiRequestError` at `delivered: false` is the statement that this
  // sentence is for the person who can act on it. The stage answers that
  // statement wherever in it the statement is made, so a host is not
  // confined to `prepareSend` to refuse in terms a user can read.
  const supervisor = new PiThreadSupervisor({
    workspacePath: "/ws",
    createResourceLoader: (() => {
      throw new PiRequestError("this workspace is read-only today", false);
    }) as never,
  });

  await expect(supervisor.createThread()).rejects.toSatisfy(
    (error: unknown) =>
      error instanceof PiCreateRefusedError &&
      error.message === "this workspace is read-only today" &&
      error.delivered === false &&
      error.threadId === (sdk.create.mock.calls[0]?.[2]?.id as string),
  );
});

