def longest_line(output: bytes) -> int:
    """Longest visible line, ignoring SGR sequences and carriage returns."""
    import re

    plain = re.sub(rb"\x1b\[[0-9;]*m", b"", output)
    return max(
        (len(line.rstrip(b"\r")) for line in plain.split(b"\n")), default=0
    )

