const DAILY_LIST_PATH = process.env.PI_BRIDGE_DAILY_LIST || "/opt/avidor/daily/latest.csv";
const NO_STORE = { "Cache-Control": "no-store" }; // one URL, different bytes every morning

// Nightly analyses (the "אנליזות מהלילה" strip on the home view): a flat directory where nightly
// jobs drop ready-made files for Ran (today: the outreach two-sheet Excel). Session-independent
// like the daily list, and rides the same unmask seam on download.
const NIGHTLY_DIR = process.env.PI_BRIDGE_NIGHTLY_DIR || "/opt/avidor/nightly";

// The nightly handover files, newest first. Top-level real files only — dotfiles and symlinks
// are never advertised, mirroring listArtifacts. Empty (not an error) until a job has dropped one.
function listNightly() {
  let names;
  try { names = fs.readdirSync(NIGHTLY_DIR); } catch { return []; }
  const out = [];
  for (const name of names) {
    if (name.startsWith(".")) continue;
    let st;
    try { st = fs.lstatSync(path.join(NIGHTLY_DIR, name)); } catch { continue; }
    if (st.isFile()) out.push({ name, size: st.size, mtime: st.mtimeMs });
  }
  return out.sort((a, b) => b.mtime - a.mtime);
}

// Same realpath guard shape as the artifact desk: a bare filename, resolved and required to stay
// inside the nightly directory. Returns the real path (or null).
function resolveNightly(name) {
  if (!name || name.startsWith(".") || name !== path.basename(name)) return null;
  let root, real, st;
  try {
    root = fs.realpathSync(NIGHTLY_DIR);
    real = fs.realpathSync(path.join(root, name));
    st = fs.statSync(real);
  } catch { return null; }
  if (real !== root && !real.startsWith(root + path.sep)) return null;
  return st.isFile() ? real : null;
}

