cases.old_string:
// Proxy an unmask download to the daemon: read the (fake) bytes of an already-resolved file, POST
// them with the original IAP JWT forwarded, stream the daemon's (real) response back as an
// attachment. The daemon — not the bridge — verifies the JWT and reads the crosswalk; the bridge
// only forwards. A missing/forged JWT is rejected by the daemon (403), surfaced here unchanged.
// Callers resolve the path themselves (each download route owns its own guard and its own 404).
async function proxyUnmask(req, res, real, extraHeaders = {}) {
  const name = path.basename(real);
  const jwt = req.headers["x-goog-iap-jwt-assertion"];
  let dres;
  try {
    dres = await fetch(`${UNMASK_DAEMON_URL}/unmask?name=${encodeURIComponent(name)}`, {
      method: "POST",
      headers: { "Content-Type": "application/octet-stream", ...(jwt ? { "x-goog-iap-jwt-assertion": String(jwt) } : {}) },
      body: fs.readFileSync(real),
    });
  } catch { res.writeHead(502, CORS); return res.end("unmask unavailable"); }
  if (dres.status === 403) { res.writeHead(403, CORS); return res.end("forbidden"); }
  if (!dres.ok) { res.writeHead(502, CORS); return res.end("unmask failed"); }
  const out = Buffer.from(await dres.arrayBuffer());
  const unmaskHeaders = {};
  for (const [key, value] of dres.headers) {
    if (key.toLowerCase().startsWith("x-unmask-")) unmaskHeaders[key] = value;
  }
  res.writeHead(200, {
    "Content-Type": dres.headers.get("content-type") || "application/octet-stream",
    "Content-Length": out.length,
    "Content-Disposition": attachmentDisposition(name),
    ...unmaskHeaders,
    ...extraHeaders,
    ...CORS,
  });
  res.end(out);
}

cases.new_string:
// Fetch the enriched bytes of an already-resolved file from the daemon: POST the (fake) bytes
// with the original IAP JWT forwarded; the daemon — not the bridge — verifies the JWT and reads
// the crosswalk. A missing/forged JWT is rejected by the daemon (403), surfaced unchanged.
// Byte-level (not streaming) so terminal presentation stages can compose DOWNSTREAM of
// enrichment. Callers resolve the path themselves (each download route owns its own guard).
async function unmaskBytes(req, real) {
  const name = path.basename(real);
  const jwt = req.headers["x-goog-iap-jwt-assertion"];
  let dres;
  try {
    dres = await fetch(`${UNMASK_DAEMON_URL}/unmask?name=${encodeURIComponent(name)}`, {
      method: "POST",
      headers: { "Content-Type": "application/octet-stream", ...(jwt ? { "x-goog-iap-jwt-assertion": String(jwt) } : {}) },
      body: fs.readFileSync(real),
    });
  } catch { return { error: 502, message: "unmask unavailable" }; }
  if (dres.status === 403) return { error: 403, message: "forbidden" };
  if (!dres.ok) return { error: 502, message: "unmask failed" };
  const buffer = Buffer.from(await dres.arrayBuffer());
  const unmaskHeaders = {};
  for (const [key, value] of dres.headers) {
    if (key.toLowerCase().startsWith("x-unmask-")) unmaskHeaders[key] = value;
  }
  return { buffer, contentType: dres.headers.get("content-type") || "application/octet-stream", unmaskHeaders };
}

async function proxyUnmask(req, res, real, extraHeaders = {}) {
  const got = await unmaskBytes(req, real);
  if (got.error) { res.writeHead(got.error, CORS); return res.end(got.message); }
  res.writeHead(200, {
    "Content-Type": got.contentType,
    "Content-Length": got.buffer.length,
    "Content-Disposition": attachmentDisposition(path.basename(real)),
    ...got.unmaskHeaders,
    ...extraHeaders,
    ...CORS,
  });
  res.end(got.buffer);
}

// The xlsx birth point — the TERMINAL presentation stage (Gilad's 26-07-29 ruling): Excel is
// write-only, born as late and as far downstream as possible — here, at the response edge,
// AFTER enrichment — streamed to the browser and held nowhere. No component ever sits on the
// consumer side of a workbook or parses one back as data; the CSV stays the only source of
// truth. The converter is a subprocess: CSV bytes on stdin, xlsx bytes on stdout, counts-only
// stderr (no identity value can reach the journal).
const XLSX_PYTHON = process.env.PI_BRIDGE_XLSX_PYTHON || "/opt/avidor/daily/venv/bin/python3";
const XLSX_SCRIPT = process.env.PI_BRIDGE_XLSX_SCRIPT || "/opt/avidor/daily/csv_to_xlsx.py";
function convertCsvToXlsx(csvBuffer) {
  return new Promise((resolve, reject) => {
    const child = spawn(XLSX_PYTHON, [XLSX_SCRIPT], { stdio: ["pipe", "pipe", "pipe"] });
    const out = [], err = [];
    child.stdout.on("data", (chunk) => out.push(chunk));
    child.stderr.on("data", (chunk) => err.push(chunk));
    child.on("error", reject);
    child.on("close", (code) => {
      if (code === 0) resolve(Buffer.concat(out));
      else reject(new Error(`csv_to_xlsx exited ${code}: ${Buffer.concat(err)}`));
    });
    child.stdin.end(csvBuffer);
  });
}

// Serve a resolved downloadable file: optional enrichment (unmask=1, flag-gated), then the
// optional terminal xlsx conversion (as=xlsx, CSVs only) — strictly in that order.
async function sendDownload(req, res, real, { unmask, asXlsx }, extraHeaders = {}) {
  let buffer, statHeaders = {};
  if (unmask && UNMASK_ENABLED) {
    const got = await unmaskBytes(req, real);
    if (got.error) { res.writeHead(got.error, CORS); return res.end(got.message); }
    buffer = got.buffer;
    statHeaders = got.unmaskHeaders;
  } else {
    buffer = fs.readFileSync(real);
  }
  let name = path.basename(real);
  let contentType = MIME[path.extname(real)] || "application/octet-stream";
  if (asXlsx && name.toLowerCase().endsWith(".csv")) {
    buffer = await convertCsvToXlsx(buffer);
    name = name.replace(/\.csv$/i, ".xlsx");
    contentType = MIME[".xlsx"];
  }
  res.writeHead(200, {
    "Content-Type": contentType,
    "Content-Length": buffer.length,
    "Content-Disposition": attachmentDisposition(name),
    ...statHeaders,
    ...extraHeaders,
    ...CORS,
  });
  res.end(buffer);
}

