  const events = (message: boolean): PiClientEvent[] =>
    [
      { type: "agent_start", threadId: "t1", seq: 1 },
      { type: "message_start", threadId: "t1", seq: 2, message: answer },
      { type: "agent_end", threadId: "t1", seq: 3 },
      ...(message
        ? [{ type: "agent_start", threadId: "t1", seq: 4 }, { type: "message_start", threadId: "t1", seq: 5, message: answer }]
        : []),
      { ...bare, seq: 6 },
    ] as PiClientEvent[];

  expect(reduce(events(false)).runActive).toBe(false);
  expect(reduce(events(true)).runActive).toBe(true);
