it("keeps Pi's unannounced streaming message out of both transcripts", async () => {
  // Pi assigns `state.streamingMessage` a hook before it emits
  // `message_start`. A snapshot taken from that live state handed an
  // attaching reader a message the connected reader had never been told
  // about: two transcripts of different lengths, and with them two sets of
  // positional ids for the same answer. The snapshot carries only what has
  // been announced, so the two agree throughout and the attacher converges
  // when the held announcement arrives.
  const { supervisor, session, entries, messages, entryFor, emit } =
    await openWithTranscript();
  const asked = { role: "user", content: "q", timestamp: 1 };
  messages.push(asked);
  entries.push(entryFor("e-asked", asked));

  const connected: PiClientEvent[] = [];
  supervisor.subscribe("t1", (event) => connected.push(event));
  await vi.waitFor(() => expect(connected).not.toHaveLength(0));

  emit({ type: "agent_start" });
  session.isStreaming = true;
  // Pi is holding the announcement of this one behind its `message_start`
  // hook. Nobody has been told.
  const held = { role: "assistant", content: [], timestamp: 2 };
  session.state = {
    pendingToolCalls: new Set<string>(),
    streamingMessage: held,
  };

  const midHook = await supervisor.getThread("t1");
  expect(midHook.messages).toEqual([asked]);
  expect(midHook.metadata.runActive).toBe(false);

  const reduce = (events: PiClientEvent[]) =>
    events.reduce(
      (state, event) => reducePiThreadState(state, event),
      createPiThreadState("t1"),
    );
  const fresh: PiClientEvent[] = [];
  supervisor.subscribe("t1", (event) => fresh.push(event));
  await vi.waitFor(() => expect(fresh).not.toHaveLength(0));
  expect(reduce(fresh).messages).toEqual(reduce(connected).messages);

  // The hook lets go: one announcement, both readers, one transcript.
  emit({ type: "message_start", message: held });
  expect((await supervisor.getThread("t1")).messages).toEqual([asked, held]);
  expect(reduce(fresh).messages).toEqual([asked, held]);
  expect(reduce(connected).messages).toEqual([asked, held]);
});

