it("cuts a backoff the stop was already armed against", async () => {
  // Pi creates the controller that can abort a retry on the line AFTER it
  // announces the backoff (0.84.1 `_prepareRetry`), so an abort delivered
  // inside the event reaches nothing and the arm sits out the full delay.
  // The fake keeps that order: `abortRetry` can only reach a controller
  // that exists.
  const t = await openForSends();
  let backoff: { aborted: boolean } | undefined;
  t.session.abortRetry = vi.fn(() => {
    if (backoff) backoff.aborted = true;
  });
  t.emit({ type: "agent_start" });
  t.session.isStreaming = true;
  t.emit({ type: "message_start" });

  await t.supervisor.cancelRun("t1");

  // The attempt dies and Pi backs off instead of ending the run.
  t.session.state.errorMessage = "503: mock upstream overloaded";
  t.emit({ type: "agent_end", willRetry: true });
  t.emit({ type: "auto_retry_start", attempt: 1, delayMs: 8000 });
  backoff = { aborted: false };
  t.session.isRetrying = true;
  await t.tick();

  expect(backoff.aborted).toBe(true);
});

it("answers a stop only once a standalone compaction has let go", async () => {
  // `session.abort()` waits for an agent RUN, and a manual compaction is
  // not one: `waitForIdle()` returns at once, so the report went out with
  // Pi still inside the compaction and the stop still armed. A slow
  // `session_before_compact` hook holds that window open for as long as it
  // likes.
  const t = await openForSends();
  t.emit({ type: "compaction_start", reason: "manual" });
  t.session.isCompacting = true;

  let answered = false;
  const stopping = t.supervisor.cancelRun("t1").then((report) => {
    answered = true;
    return report;
  });
  await t.tick();
  expect(answered).toBe(false);
  expect(t.session.abortCompaction).toHaveBeenCalled();

  t.session.isCompacting = false;
  t.emit({ type: "compaction_end", aborted: false, willRetry: false });

  // The value is the one decided before the first await; only the answer
  // waited. And the thread it reports on really has let go.
  expect(await stopping).toEqual({ stopped: true });
  expect(t.supervisor.getRunningThreadCount()).toBe(0);
});

