/**
 * Derive model/credential readiness. Only the two cheaply-knowable states are
 * surfaced: a model is selected (`ready`) or none is (`missing-model`).
 * `missing-credentials` / `unavailable-model` are detected lazily when a send
 * fails and routed into `lastError` — we do not probe the provider eagerly.
 */
export const deriveReadiness = (input: {
  model?: { provider: string; id: string } | undefined;
  source?: "env" | "session" | "pi-default";
}): PiRuntimeReadiness => {
  if (!input.model) {
    return {
      state: "missing-model",
      message:
        "No model selected. Set PI_PROVIDER + PI_MODEL_ID (or configure a Pi default) and restart the host.",
    };
  }
  return {
    state: "ready",
    selection: { provider: input.model.provider, modelId: input.model.id },
    source: input.source ?? "session",
  };
};

cases.new_string:
/**
 * Derive model/credential readiness for one thread's selected model.
 *
 * `hasCredentials` comes from the host's shared model runtime, which knows
 * every credential source (stored, environment, runtime-only). Leaving it
 * `undefined` means the host could not answer, and an unknown answer never
 * blocks: only a definite `false` reports `missing-credentials`.
 * `unavailable-model` is still detected lazily when a send fails.
 */
export const deriveReadiness = (input: {
  model?: { provider: string; id: string } | undefined;
  source?: "env" | "session" | "pi-default";
  hasCredentials?: boolean | undefined;
}): PiRuntimeReadiness => {
  if (!input.model) {
    return {
      state: "missing-model",
      message:
        "No model selected. Set PI_PROVIDER + PI_MODEL_ID (or configure a Pi default) and restart the host.",
    };
  }
  if (input.hasCredentials === false) {
    return {
      state: "missing-credentials",
      provider: input.model.provider,
      message: `No credentials configured for ${input.model.provider}. Authenticate with \`pi\`, or give the host a runtime API key, then reload.`,
    };
  }
  return {
    state: "ready",
    selection: { provider: input.model.provider, modelId: input.model.id },
    source: input.source ?? "session",
  };
};

