/** How many live sessions are mid-run (streaming, compacting or retrying).
 * A deploy that waits for the host to go idle reads this; restarting while it
 * is above zero aborts someone's turn. Idle sessions do not count — they
 * resume from their session file, so a restart does not disturb them. */
getRunningThreadCount(): number {
  // One record can be reachable under more than one thread id, so count records.
  const running = new Set<ThreadRecord>();
  for (const record of this.records.values()) {
    if (this.runStatus(record) === "running") running.add(record);
  }
  return running.size;
}

