 * different one is refused rather than quietly redirected — the request is
 * either a bug or an attempt to read another directory. */
private resolveWorkspace(requested: string | undefined): string {
  if (requested === undefined) return this.workspacePath;
  if (this.lockWorkspace && requested !== this.workspacePath) {
    throw new Error(
      `This host serves ${this.workspacePath} only; it will not use ${requested}`,
    );
