describe("PiThreadSupervisor host configuration", () => {
  const SESSIONS_DIR = "/srv/sessions";
  const FLASH = {
    provider: "openrouter",
    id: "google/gemini-3.1-flash-lite-preview",
    name: "Gemini 3.1 Flash Lite",
  };
  const OPUS = {
    provider: "anthropic",
    id: "claude-opus-4-5",
    name: "Claude Opus 4.5",
  };

  const runtime = () => ({
    refresh: vi.fn(async () => ({})),
    getAvailableSnapshot: vi.fn(() => [FLASH, OPUS]),
    getModels: vi.fn(() => [FLASH, OPUS]),
    getModel: vi.fn((provider: string, modelId: string) =>
      [FLASH, OPUS].find(
        (model) => model.provider === provider && model.id === modelId,
      ),
    ),
    hasConfiguredAuth: vi.fn(() => true),
  });

  beforeEach(() => {
    vi.clearAllMocks();
    sdk.list.mockResolvedValue([SESSION]);
    sdk.listAll.mockResolvedValue([]);
    sdk.open.mockReturnValue(createReadonlySessionManager());
    sdk.create.mockReturnValue({ kind: "created" });
    sdk.modelRuntimeCreate.mockResolvedValue(runtime());
  });

  const openedWith = () => sdk.createAgentSession.mock.calls[0]?.[0] ?? {};

  // --- 1. session-store isolation -------------------------------------------

  it("routes create, list and lookup through the configured session store", async () => {
    const supervisor = new PiThreadSupervisor({
      workspacePath: "/ws",
      sessionsDir: SESSIONS_DIR,
    });
    sdk.createAgentSession.mockImplementation(
      async (options: { sessionManager: unknown }) => ({
        session: createLiveSession({
          sessionId: sdk.create.mock.calls[0]?.[2]?.id,
          sessionManager: options.sessionManager,
        }),
      }),
    );

    await supervisor.createThread();
    await supervisor.listThreads();

    expect(sdk.create).toHaveBeenCalledWith("/ws", SESSIONS_DIR, {
      id: expect.any(String),
    });
    expect(sdk.list).toHaveBeenCalledWith("/ws", SESSIONS_DIR);
  });

  it("resolves an unlisted thread inside the configured store, never the host's", async () => {
    sdk.list.mockResolvedValue([]);
    const supervisor = new PiThreadSupervisor({
      workspacePath: "/ws",
      sessionsDir: SESSIONS_DIR,
    });

    await expect(supervisor.getThread("t1")).rejects.toThrow("Unknown Pi thread");
    expect(sdk.listAll).toHaveBeenCalledWith(SESSIONS_DIR);
  });

  // --- 2 + 3. one shared, workspace-isolated model runtime ------------------

  it("keeps the model runtime inside the configured agent dir", async () => {
    new PiThreadSupervisor({ workspacePath: "/ws", agentDir: "/srv/agent" });
    await new PiThreadSupervisor({
      workspacePath: "/ws",
      agentDir: "/srv/agent",
    }).getAvailableModels();

    expect(sdk.modelRuntimeCreate).toHaveBeenCalledWith({
      authPath: "/srv/agent/auth.json",
      modelsPath: "/srv/agent/models.json",
    });
  });

  it("gives every session the host's runtime instead of building its own", async () => {
    const shared = runtime();
    const supervisor = new PiThreadSupervisor({
      workspacePath: "/ws",
      modelRuntime: shared as never,
    });
    sdk.createAgentSession.mockResolvedValue({ session: createLiveSession() });

    await supervisor.setThinkingLevel("t1", "high");

    expect(sdk.modelRuntimeCreate).not.toHaveBeenCalled();
    expect(openedWith().modelRuntime).toBe(shared);
    await expect(supervisor.getAvailableModels()).resolves.toHaveLength(2);
    expect(shared.getAvailableSnapshot).toHaveBeenCalled();
  });

  it("reports missing credentials for the selected thread's provider", async () => {
    const shared = runtime();
    shared.hasConfiguredAuth = vi.fn(() => false);
    const supervisor = new PiThreadSupervisor({
      workspacePath: "/ws",
      modelRuntime: shared as never,
    });
    sdk.createAgentSession.mockResolvedValue({
      session: createLiveSession({ model: FLASH }),
    });

    await supervisor.setThinkingLevel("t1", "high");

    expect(await supervisor.getThread("t1")).toMatchObject({
      readiness: { state: "missing-credentials", provider: "openrouter" },
    });
    expect(shared.hasConfiguredAuth).toHaveBeenCalledWith("openrouter");
  });

  // --- 4. curated and enforced models ---------------------------------------

  it("offers only the scoped models, in the configured order", async () => {
    const supervisor = new PiThreadSupervisor({
      workspacePath: "/ws",
      scopedModels: [
        { provider: "openrouter", modelId: FLASH.id },
        { provider: "anthropic", modelId: OPUS.id },
      ],
    });

    await expect(supervisor.getAvailableModels()).resolves.toEqual([
      { provider: "openrouter", modelId: FLASH.id, name: FLASH.name, supportsThinking: false },
      { provider: "anthropic", modelId: OPUS.id, name: OPUS.name, supportsThinking: false },
    ]);
  });

  it("refuses setModel for a model outside the scope, and passes the scope to Pi", async () => {
    const supervisor = new PiThreadSupervisor({
      workspacePath: "/ws",
      scopedModels: [{ provider: "openrouter", modelId: FLASH.id }],
    });
    const session = createLiveSession();
    sdk.createAgentSession.mockResolvedValue({ session });

    await expect(
      supervisor.setModel("t1", { provider: "anthropic", modelId: OPUS.id }),
    ).rejects.toThrow("is not one of this host's models");
    expect(session.setModel).not.toHaveBeenCalled();

    await supervisor.setModel("t1", { provider: "openrouter", modelId: FLASH.id });
    expect(session.setModel).toHaveBeenCalledWith(FLASH);
    expect(openedWith().scopedModels).toEqual([{ model: FLASH }]);
  });

  it("fails loudly when a scoped model is not in the registry", async () => {
    const supervisor = new PiThreadSupervisor({
      workspacePath: "/ws",
      scopedModels: [{ provider: "openrouter", modelId: "typo/model" }],
    });

    await expect(supervisor.getAvailableModels()).rejects.toThrow(
      "Scoped model openrouter/typo/model is not in Pi's model registry",
    );
  });

  // --- 5. new-session defaults ----------------------------------------------

  it("applies the default model and thinking level to a new session only", async () => {
    const supervisor = new PiThreadSupervisor({
      workspacePath: "/ws",
      model: FLASH as never,
      thinkingLevel: "xhigh",
    });
    sdk.createAgentSession.mockImplementation(async () => ({
      session: createLiveSession({
        sessionId: sdk.create.mock.calls.at(-1)?.[2]?.id ?? "t1",
      }),
    }));

    await supervisor.createThread();
    expect(openedWith()).toMatchObject({ model: FLASH, thinkingLevel: "xhigh" });

    // A resumed session must keep the model and level it was saved with.
    await supervisor.setThinkingLevel("t1", "low");
    const resumed = sdk.createAgentSession.mock.calls[1]?.[0] ?? {};
    expect(resumed.model).toBeUndefined();
    expect(resumed.thinkingLevel).toBeUndefined();
  });

  // --- 6 + 7. explicit session id, then the per-session resource loader ------

  it("names the session before Pi builds it, and hands that name to the loader", async () => {
    const loader = { reload: vi.fn() };
    const createResourceLoader = vi.fn(() => loader);
    const supervisor = new PiThreadSupervisor({
      workspacePath: "/ws",
      createResourceLoader: createResourceLoader as never,
    });
    sdk.createAgentSession.mockImplementation(async () => ({
      session: createLiveSession({
        sessionId: sdk.create.mock.calls.at(-1)?.[2]?.id,
      }),
    }));

    const snapshot = await supervisor.createThread();

    const chosenId = sdk.create.mock.calls[0]?.[2]?.id;
    expect(chosenId).toEqual(expect.any(String));
    expect(snapshot.metadata.id).toBe(chosenId);
    expect(createResourceLoader).toHaveBeenCalledWith({
      threadId: chosenId,
      workspacePath: "/ws",
    });
    expect(openedWith().resourceLoader).toBe(loader);
    // The loader must exist before the session does.
    expect(createResourceLoader.mock.invocationCallOrder[0]!).toBeLessThan(
      sdk.createAgentSession.mock.invocationCallOrder[0]!,
    );
  });

  it("builds a resumed session's loader with that session's id", async () => {
    const createResourceLoader = vi.fn(() => ({ reload: vi.fn() }));
    const supervisor = new PiThreadSupervisor({
      workspacePath: "/ws",
      createResourceLoader: createResourceLoader as never,
    });
    sdk.createAgentSession.mockResolvedValue({ session: createLiveSession() });

    await supervisor.setThinkingLevel("t1", "high");

    expect(createResourceLoader).toHaveBeenCalledWith({
      threadId: "t1",
      workspacePath: "/ws",
    });
  });

  // --- 8. durable entry ids --------------------------------------------------

  it("carries Pi's entry ids on the snapshot and refreshes them at run boundaries", async () => {
    const first = { role: "user", content: "hello", timestamp: 1 };
    const streaming = { role: "assistant", content: [], timestamp: 2 };
    const entries: unknown[] = [
      { type: "message", id: "e-user", parentId: null, message: first },
    ];
    let emit: (event: Record<string, unknown>) => void = () => {};
    const session = createLiveSession({
      messages: [first, streaming],
      sessionManager: { buildContextEntries: vi.fn(() => entries) },
      subscribe: vi.fn((listener: (event: Record<string, unknown>) => void) => {
        emit = listener;
        return () => {};
      }),
    });
    sdk.createAgentSession.mockResolvedValue({ session });
    const supervisor = new PiThreadSupervisor({ workspacePath: "/ws" });
    const events: Record<string, unknown>[] = [];
    supervisor.subscribe("t1", (event) => events.push(event));
    await vi.waitFor(() => expect(events).not.toHaveLength(0));

    // A message Pi has not written yet has no id, so the projection stays positional.
    expect((await supervisor.getThread("t1")).entryIds).toEqual(["e-user", null]);

    entries.push({
      type: "message",
      id: "e-assistant",
      parentId: "e-user",
      message: streaming,
    });
    emit({ type: "agent_end" });

    expect(events.at(-1)).toMatchObject({
      type: "entry_ids",
      entryIds: ["e-user", "e-assistant"],
    });
  });

  it("pairs a cold thread's messages with their entry ids", async () => {
    const supervisor = new PiThreadSupervisor({ workspacePath: "/ws" });

    expect((await supervisor.getThread("t1")).entryIds).toEqual(["m1"]);
  });

  // --- 9. running-session observability -------------------------------------

  it("counts only the sessions a deploy would interrupt", async () => {
    const supervisor = new PiThreadSupervisor({ workspacePath: "/ws" });
    const session = createLiveSession();
    sdk.createAgentSession.mockResolvedValue({ session });

    await supervisor.setThinkingLevel("t1", "high");
    expect(supervisor.getRunningThreadCount()).toBe(0);

    session.isStreaming = true;
    expect(supervisor.getRunningThreadCount()).toBe(1);

    session.isStreaming = false;
    session.isCompacting = true;
    expect(supervisor.getRunningThreadCount()).toBe(1);
  });

  // --- 10. server-authoritative workspace ------------------------------------

  it("refuses a workspace other than the configured one when locked", async () => {
    const supervisor = new PiThreadSupervisor({
      workspacePath: "/ws",
      lockWorkspace: true,
    });

    await expect(
      supervisor.listThreads({ workspacePath: "/etc" }),
    ).rejects.toThrow("This host serves /ws only");
    await expect(
      supervisor.createThread({ workspacePath: "/etc" }),
    ).rejects.toThrow("This host serves /ws only");
    expect(sdk.create).not.toHaveBeenCalled();

    // The host's own value, and no value at all, both pass.
    await expect(
      supervisor.listThreads({ workspacePath: "/ws" }),
    ).resolves.toHaveLength(1);
    await expect(supervisor.listThreads()).resolves.toHaveLength(1);
  });

  it("still follows a per-call workspace when the host has not locked one", async () => {
    const supervisor = new PiThreadSupervisor({ workspacePath: "/ws" });

    await supervisor.listThreads({ workspacePath: "/other" });

    expect(sdk.list).toHaveBeenCalledWith("/other", undefined);
  });
});

