describe("entryIdsForMessages", () => {
  const entry = (id: string, message: unknown): SessionEntry =>
    ({ type: "message", id, parentId: null, timestamp: "", message }) as SessionEntry;

  it("pairs each message with the entry that holds it", () => {
    const first = { role: "user", content: "hi", timestamp: 1 };
    const second = { role: "assistant", content: [], timestamp: 2 };

    expect(
      entryIdsForMessages([entry("a", first), entry("b", second)], [first, second]),
    ).toEqual(["a", "b"]);
  });

  it("leaves a message Pi has not written yet without an id", () => {
    const written = { role: "user", content: "hi", timestamp: 1 };
    const streaming = { role: "assistant", content: [], timestamp: 2 };

    expect(
      entryIdsForMessages([entry("a", written)], [written, streaming]),
    ).toEqual(["a", null]);
  });

  it("ignores entries that are not messages", () => {
    const message = { role: "user", content: "hi", timestamp: 1 };
    const info = {
      type: "session_info",
      id: "s1",
      parentId: null,
      timestamp: "",
      name: "Title",
    } as SessionEntry;

    expect(entryIdsForMessages([info, entry("a", message)], [message])).toEqual([
      "a",
    ]);
  });

  it("keeps the ids of surviving messages when compaction drops earlier ones", () => {
    const dropped = { role: "user", content: "old", timestamp: 1 };
    const kept = { role: "user", content: "new", timestamp: 2 };
    const all = [entry("a", dropped), entry("b", kept)];

    // `buildContextEntries` hands back only the post-cut-point entries; the
    // surviving message keeps the id it always had, where a positional id would
    // have shifted from 1 to 0.
    expect(entryIdsForMessages(all.slice(1), [kept])).toEqual(["b"]);
  });
});

