private async findSessionInfo(threadId: string) {
  return this.confine(await this.lookupSessionInfo(threadId));
}

private async lookupSessionInfo(threadId: string) {
  const cached = this.catalogInfoByThreadId.get(threadId);
  if (cached) return cached;
  const local = await this.listSessionInfos(this.workspacePath);
  const hit = local.find((info) => info.id === threadId);
  if (hit) return hit;
  // The wider sweep stays inside the configured store: a host with its own
  // session directory must not resolve a thread out of the host's `~/.pi`.
  const all = await SessionManager.listAll(this.sessionsDir);
  this.rememberSessionInfos(all);
  return all.find((info) => info.id === threadId);
}

/**
 * The confinement check every id lookup passes through.
 *
 * `listThreads` is already scoped by workspace, but the id path is not: the
 * wider sweep returns every session in the store, whatever directory it was
 * started in, and opening one would run Pi in that directory. A session
 * recorded with no cwd (Pi's older sessions) is not a foreign workspace and
 * is served as this host's own, which is how a migrated store keeps working.
 */
private confine(info: PiSessionInfo | undefined): PiSessionInfo | undefined {
  if (!info || !this.lockWorkspace) return info;
  if (!info.cwd || info.cwd === this.workspacePath) return info;
  throw new Error(
    `This host serves ${this.workspacePath} only; session ${info.id} belongs to ${info.cwd}`,
  );
}

