/** The saved selection, when Pi opened the session on something else. Pi
 * restores a model only if its provider has credentials; otherwise it picks
 * another authenticated default and says nothing to the caller. */
const unrestoredModel = (
  saved: { provider: string; modelId: string } | undefined,
  opened: { provider: unknown; id: string } | undefined,
): PiModelSelection | undefined => {
  if (!saved) return undefined;
  const same =
    opened !== undefined &&
    String(opened.provider) === saved.provider &&
    opened.id === saved.modelId;
  return same ? undefined : saved;
};

