cases.old_string:
/**
 * Pair each transcript message with the id of the session entry holding it.
 *
 * Pi appends the very message object it emitted, so the two are matched by
 * identity rather than by a role/timestamp guess. A message Pi has not written
 * yet (the one still streaming) has no entry and gets `null`.
 *
 * >>> entryIdsForMessages([], [{ role: "user" }])
 * [null]
 */
export const entryIdsForMessages = (
  entries: readonly SessionEntry[],
  messages: readonly unknown[],
): (string | null)[] => {
  const idByMessage = new Map<unknown, string>();
  for (const entry of entries) {
    if (entry.type === "message") idByMessage.set(entry.message, entry.id);
  }
  return messages.map((message) => idByMessage.get(message) ?? null);
};

cases.new_string:
/** Whether an entry contributes one message to the transcript Pi builds from
 * it (`sessionEntryToContextMessages`). Compaction, branch summaries and
 * extension messages all become messages the reader sees, so all of them need
 * an id — only `message` entries carry theirs by object identity. */
const yieldsTranscriptMessage = (entry: SessionEntry): boolean => {
  if (entry.type === "message" || entry.type === "custom_message") return true;
  if (entry.type === "compaction") return true;
  if (entry.type === "branch_summary") return Boolean(entry.summary);
  return false;
};

/**
 * Pair each transcript message with the id of the session entry behind it.
 *
 * Entries and messages advance in lockstep: Pi builds the transcript by
 * flat-mapping the active entries in order. A `message` entry also carries its
 * message by identity — Pi appends the very object it emitted — so that pairing
 * is checked, and a mismatch stops the walk rather than mislabelling the rest.
 * Messages past the end of the entries (the one still streaming) get `null`.
 *
 * >>> entryIdsForMessages([], [{ role: "user" }])
 * [null]
 */
export const entryIdsForMessages = (
  entries: readonly SessionEntry[],
  messages: readonly unknown[],
): (string | null)[] => {
  const ids: (string | null)[] = messages.map(() => null);
  let cursor = 0;
  for (const entry of entries) {
    if (cursor >= messages.length) break;
    if (!yieldsTranscriptMessage(entry)) continue;
    if (entry.type === "message" && entry.message !== messages[cursor]) break;
    ids[cursor] = entry.id;
    cursor += 1;
  }
  return ids;
};

