  it("still follows a per-call workspace when the host has not locked one", async () => {
    const supervisor = new PiThreadSupervisor({ workspacePath: "/ws" });

    await supervisor.listThreads({ workspacePath: "/other" });

    expect(sdk.list).toHaveBeenCalledWith("/other", undefined);
  });

  it("refuses a foreign-workspace session reached by id, not just by listing", async () => {
    // The session lives in the configured store but was started elsewhere, so
    // the workspace-scoped listing hides it while the id path still finds it.
    const foreign: SessionInfo = { ...SESSION, id: "foreign", cwd: "/etc" };
    sdk.list.mockResolvedValue([]);
    sdk.listAll.mockResolvedValue([foreign]);
    const supervisor = new PiThreadSupervisor({
      workspacePath: "/ws",
      sessionsDir: SESSIONS_DIR,
      lockWorkspace: true,
    });
    sdk.createAgentSession.mockResolvedValue({ session: createLiveSession() });

    await expect(supervisor.listThreads()).resolves.toEqual([]);
    await expect(supervisor.getThread("foreign")).rejects.toThrow(
      "This host serves /ws only; session foreign belongs to /etc",
    );
    // The operation routes are the real risk: they would open a live Pi
    // session with the foreign directory as its cwd.
    await expect(supervisor.setThinkingLevel("foreign", "high")).rejects.toThrow(
      "This host serves /ws only",
    );
    await expect(supervisor.renameThread("foreign", "x")).rejects.toThrow(
      "This host serves /ws only",
    );
    expect(sdk.createAgentSession).not.toHaveBeenCalled();
  });

  it("serves a session recorded with no cwd as its own", async () => {
    // Pi's older sessions carry an empty cwd. They are not a foreign workspace,
    // and a migrated store must keep resolving them.
    const legacy: SessionInfo = { ...SESSION, id: "legacy", cwd: "" };
    sdk.list.mockResolvedValue([legacy]);
    const supervisor = new PiThreadSupervisor({
      workspacePath: "/ws",
      sessionsDir: SESSIONS_DIR,
      lockWorkspace: true,
    });

    await expect(supervisor.getThread("legacy")).resolves.toMatchObject({
      metadata: { id: "legacy" },
    });
  });

  // --- resume keeps the saved model ------------------------------------------

  const resumeWithoutCredentials = () => {
    // Pi restores a saved model only when its provider has credentials; here it
    // silently opens the session on the other one instead.
    const manager = createReadonlySessionManager();
    manager.buildSessionContext = vi.fn(() => ({
      messages: [],
      thinkingLevel: "high",
      model: { provider: "anthropic", modelId: OPUS.id },
    }));
    sdk.open.mockReturnValue(manager);
    const session = createLiveSession({ model: FLASH });
    sdk.createAgentSession.mockResolvedValue({
      session,
      modelFallbackMessage: `Could not restore model anthropic/${OPUS.id}`,
    });
    return { manager, session };
  };

