/** The saved selection, when Pi opened the session on something else. Pi
 * restores a model only if its provider has credentials; otherwise it picks
 * another authenticated default and says nothing to the caller. */
const unrestoredModel = (
  saved: { provider: string; modelId: string } | undefined,
  opened: { provider: unknown; id: string } | undefined,
): PiModelSelection | undefined => {
  if (!saved) return undefined;
  const same =
    opened !== undefined &&
    String(opened.provider) === saved.provider &&
    opened.id === saved.modelId;
  return same ? undefined : saved;
};

cases.new_string:
/**
 * A directory the way Pi records it. Pi resolves a `cwd` before writing it into
 * a session header, so a host configured with `.` or a trailing slash has to be
 * resolved the same way before the two can be compared at all.
 *
 * >>> normalizeDirectory("/ws/") === normalizeDirectory("/ws")
 * true
 */
const normalizeDirectory = (path: string): string =>
  resolveFsPath(
    path.startsWith("~") ? `${homedir()}${path.slice(1)}` : path,
  );

/** Raised instead of opening a session Pi could not restore. Carries the saved
 * selection so callers can say which model and provider is missing. */
export class PiUnrestorableModelError extends Error {
  constructor(
    readonly threadId: string,
    readonly savedModel: PiModelSelection,
  ) {
    super(
      `Cannot open thread ${threadId}: it is set to ${savedModel.provider}/${savedModel.modelId} and ${savedModel.provider} has no credentials configured. Add them and reload, or pick another model for this thread.`,
    );
    this.name = "PiUnrestorableModelError";
  }
}

