/**
 * Whether the composer may send for the thread that is open.
 *
 * The startup handshake answers a different question from the open thread. It
 * says whether the server came up and what a NEW thread will run on; it knows
 * nothing about a thread already running another model. So an open thread
 * speaks for itself, and the handshake governs only the cases it is right
 * about: the server not answering, and a composer with no thread behind it yet.
 *
 * Live readiness counts only when it belongs to the thread now open. During a
 * switch the two disagree for one render, and answering from the thread that
 * just closed would be a guess.
 *
 * >>> composerGate({ status: "loading" }, { threadId: "t1", readiness: undefined }, "t1").blockSending
 * true
 */
export const composerGate = (
  state: PiHandshakeState,
  live: PiLiveReadiness,
  activeThreadId: string | undefined,
): { blockSending: boolean; message: string | undefined } => {
  // The server itself is unusable or unknown; no thread can speak over that.
  if (state.status !== "ready") return handshakeGate(state);

  const isCurrent = activeThreadId !== undefined && live.threadId === activeThreadId;
  const readiness = isCurrent ? live.readiness : undefined;
  if (!readiness) return handshakeGate(state);
  if (readiness.state !== "ready") {
    return { blockSending: true, message: readiness.message };
  }
  return { blockSending: false, message: undefined };
};

cases.new_string:
/**
 * Whether the composer may send for the thread that is open.
 *
 * The startup handshake answers a different question from the open thread. It
 * says whether the server came up and what a NEW thread will run on; it knows
 * nothing about a thread already running another model. So an open thread
 * speaks for itself, and the handshake governs exactly two things: a server
 * that is not usable, and a composer with no thread behind it yet.
 *
 * A thread whose verdict has not arrived blocks. The id and the verdict reach
 * this function by different routes, so they disagree for a render on every
 * switch; answering from the handshake in that window would let a ready seed
 * open the composer over a thread that cannot run. An unknown thread is not a
 * ready one.
 *
 * >>> composerGate({ status: "loading" }, { threadId: "t1", readiness: undefined }, "t1").blockSending
 * true
 */
export const composerGate = (
  state: PiHandshakeState,
  live: PiLiveReadiness,
  activeThreadId: string | undefined,
): { blockSending: boolean; message: string | undefined } => {
  // The server itself is unusable or unknown; no thread can speak over that.
  if (state.status !== "ready") return handshakeGate(state);

  // No thread yet: the composer would create one on the seeded model.
  if (activeThreadId === undefined) return handshakeGate(state);

  const readiness =
    live.threadId === activeThreadId ? live.readiness : undefined;
  if (!readiness) {
    return { blockSending: true, message: "Checking this chat…" };
  }
  if (readiness.state !== "ready") {
    return { blockSending: true, message: readiness.message };
  }
  return { blockSending: false, message: undefined };
};

