it("holds one id through a multi-turn run, and settles on the final answer", () => {
  // The event sequence a two-turn run produces. The id must not move while
  // the run is going: a merged run is named by its final answer, and that
  // answer is not known until the run settles.
  let seq = 0;
  const at = (body: PiClientEventBody): PiClientEvent =>
    ({ ...body, threadId: "t1", seq: ++seq }) as PiClientEvent;
  const turnOne = assistant([toolCall("tc1", "bash", {})]);
  const toolResult = {
    role: "toolResult" as const,
    toolCallId: "tc1",
    toolName: "bash",
    content: [{ type: "text" as const, text: "ok" }],
    isError: false,
    timestamp: 2,
  };
  const finalAnswer = assistant([{ type: "text", text: "done" }], {
    timestamp: 3,
  });

  let state = createPiThreadState("t1");
  const idNow = () =>
    projectPiThreadMessages({
      messages: state.messages,
      entryIds: state.entryIds,
      toolExecutions: state.toolExecutions,
      runStatus: state.runStatus,
      hostUiRequests: state.hostUiRequests,
    })[0]?.id;

  const seen: (string | undefined)[] = [];
  for (const event of [
    at({ type: "agent_start" }),
    at({ type: "message_start", message: turnOne }),
    at({ type: "message_end", message: turnOne }),
    at({ type: "message_start", message: toolResult }),
    at({ type: "message_end", message: toolResult }),
    at({ type: "turn_end", turnIndex: 0 }),
    at({ type: "message_start", message: finalAnswer }),
    at({ type: "message_end", message: finalAnswer }),
  ]) {
    state = reducePiThreadState(state, event);
    seen.push(idNow());
  }
  expect(new Set(seen)).toEqual(new Set(["pi-msg:0"]));

  // Only the run boundary publishes ids, and the run's name settles once.
  state = reducePiThreadState(
    state,
    at({
      type: "entry_ids",
      entryIds: ["e-first", "e-result", "e-final"],
    }),
  );
  state = reducePiThreadState(state, at({ type: "agent_end" }));
  expect(idNow()).toBe("e-final");
});

